// What a property card shows, derived from a real property record.
//
// Pure functions with no React in them, so the mapping the cards depend on can
// be tested directly — including the awkward cases: a property with no image,
// no availability, a studio, or a name far too long for one line.

import { isPublished } from "../property/derive.ts";
import type { Property } from "../property/types";

/**
 * Whether a property is on the website.
 *
 * Deliberately NOT the same thing as availability, which the ticket is right to
 * separate:
 *
 *   publication  is this listing on the website at all?
 *   availability can somebody move into it?
 *
 * A published property can be fully occupied, and a draft can be standing
 * empty. Conflating them would mean unpublishing a listing the moment it was
 * let, which is the opposite of what an agent wants.
 *
 * The current record has no publication field, because every bundled property
 * has a live page — they are published by definition. Rather than invent a
 * persistence model for a state nothing can currently set, this reads an
 * optional field and defaults to published. When the property workflow can
 * create a draft, it sets the field and nothing here changes.
 */
export type Publication = "published" | "draft";

export type PropertyWithPublication = Property & {
  publication?: Publication;
};

export function publicationOf(property: PropertyWithPublication): Publication {
  /* Delegated rather than repeated. This rule now also decides which listings
     the public site builds, searches and suggests, so the CMS badge and the
     website cannot come to different conclusions about the same property. */
  return isPublished(property) ? "published" : "draft";
}

/** A draft has no public page yet, so there is nothing to link to. */
export function publicHref(property: PropertyWithPublication): string | null {
  if (publicationOf(property) === "draft") return null;
  return `/properties/${property.slug}/`;
}

/** Studio reads better than "0 Beds", matching the public pages. */
export function bedroomLabel(bedrooms: number): string {
  if (!Number.isFinite(bedrooms) || bedrooms < 0) return "";
  if (bedrooms === 0) return "Studio";
  return `${bedrooms} ${bedrooms === 1 ? "Bed" : "Beds"}`;
}

export function bathroomLabel(bathrooms: number): string {
  if (!Number.isFinite(bathrooms) || bathrooms <= 0) return "";
  // Halves are ordinary in US listings, so 1.5 stays 1.5 rather than rounding.
  return `${bathrooms} ${bathrooms === 1 ? "Bath" : "Baths"}`;
}

/**
 * The short line under the property name: type, size, then rooms.
 *
 * Built by filtering rather than by string concatenation with separators, so a
 * property missing any one of them does not render a stray middle dot.
 */
export function metaLine(property: Property): string[] {
  return [
    property.type,
    bedroomLabel(property.bedrooms),
    bathroomLabel(property.bathrooms),
  ].filter((part) => Boolean(part && part.trim()));
}

export type AvailabilityTone = "now" | "soon" | "none";

/** Availability is free text on the record, so this reads it rather than assuming. */
export function availabilityTone(availability: string | undefined): AvailabilityTone {
  if (!availability || !availability.trim()) return "none";
  return /now|immediate/i.test(availability) ? "now" : "soon";
}

export type PropertyCardModel = {
  id: string;
  slug: string;
  title: string;
  location: string;
  /** Null when the record has no usable photograph; the card draws a fallback. */
  image: string | null;
  imageSrcSet?: string;
  imageAlt: string;
  meta: string[];
  availability: string | null;
  availabilityTone: AvailabilityTone;
  publication: Publication;
  /** Null for a draft, which has no page on the website yet. */
  href: string | null;
};

export function toCardModel(property: PropertyWithPublication): PropertyCardModel {
  const image = typeof property.image === "string" && property.image.trim()
    ? property.image
    : null;

  return {
    id: property.id,
    slug: property.slug,
    title: property.title,
    location: property.location,
    image,
    imageSrcSet: property.imageSrcSet,
    /* Empty when the record carries no description: the card already names
       the property immediately beside the photograph, so inventing alt text
       would only make a screen reader say the same thing twice. */
    imageAlt: property.imageAlt || "",
    meta: metaLine(property),
    availability: property.availability?.trim() || null,
    availabilityTone: availabilityTone(property.availability),
    publication: publicationOf(property),
    href: publicHref(property),
  };
}
