import { useEffect, useState } from "react";

export type Rect = {
  top: number;
  left: number;
  width: number;
  height: number;
};

/** Everything DOM-facing is behind this, so the machine stays pure. */
export const selectorFor = (target: string) => `[data-tutorial="${target}"]`;

export function findTarget(target: string): HTMLElement | null {
  if (typeof document === "undefined") return null;
  return document.querySelector<HTMLElement>(selectorFor(target));
}

/* Long enough for a dialog to mount, short enough that a step the reader has
   already passed does not leave them looking at a dark screen. The observer
   below fires the instant a target appears, so this only bounds the genuinely
   absent case. */
const RETRY_MS = 1200;

export type TargetState =
  | { status: "searching" }
  | { status: "found"; rect: Rect; element: HTMLElement }
  | { status: "missing" };

/**
 * Tracks where a target is on screen.
 *
 * Three jobs, all of which the walkthrough would be broken without:
 *
 *   1. Wait for the target. A step often points at something that does not
 *      exist yet — the name field inside a dialog the reader has not opened.
 *      A MutationObserver waits for it, bounded by a timeout so a genuinely
 *      absent target reports back rather than spinning forever behind an 80%
 *      black screen.
 *   2. Bring it into view, then measure. Measuring before the scroll settles
 *      gives coordinates that are already stale.
 *   3. Keep measuring. Scroll, resize and layout changes all move the target,
 *      and a spotlight that stays where the button used to be is worse than no
 *      spotlight.
 *
 * Every listener and observer is torn down when the step changes.
 */
export function useTargetRect(target: string | null, nonce: number): TargetState {
  const [state, setState] = useState<TargetState>({ status: "searching" });
  /* Bumped when a target we were tracking leaves the page, which re-runs the
     whole search. A dialog closing is the ordinary case. */
  const [generation, setGeneration] = useState(0);

  useEffect(() => {
    if (!target || typeof window === "undefined") return;

    setState({ status: "searching" });

    let cancelled = false;
    let frame = 0;
    let element: HTMLElement | null = null;

    const measure = () => {
      if (cancelled || !element) return;

      /* The element may have been removed since we last looked — a dialog
         closing, a tab switching, a list re-rendering. Without this the
         spotlight sits at the last place the element was, over whatever
         happens to be there now, and the walkthrough looks stuck. */
      if (!element.isConnected) {
        element = null;
        setGeneration((value) => value + 1);
        return;
      }

      const box = element.getBoundingClientRect();

      // A zero box means display:none or not laid out yet — keep waiting
      // rather than spotlighting a point.
      if (box.width === 0 && box.height === 0) return;

      setState({
        status: "found",
        element,
        rect: {
          top: box.top,
          left: box.left,
          width: box.width,
          height: box.height,
        },
      });
    };

    /* Coalesced into one frame: scroll fires far more often than the layout
       actually changes. */
    const schedule = () => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        frame = 0;
        measure();
      });
    };

    const attach = (found: HTMLElement) => {
      element = found;

      const reduced = window.matchMedia?.(
        "(prefers-reduced-motion: reduce)"
      )?.matches;

      found.scrollIntoView({
        behavior: reduced ? "auto" : "smooth",
        block: "center",
        inline: "nearest",
      });

      // Smooth scrolling has no completion event, so measure continuously for
      // a moment and let the listeners take over from there.
      measure();
      const settle = window.setInterval(measure, 60);
      window.setTimeout(() => window.clearInterval(settle), reduced ? 120 : 700);

      /* Scroll and resize cover movement, but nothing fires when an element is
         simply removed, so this is the watchdog for that. */
      const watchdog = window.setInterval(() => {
        if (element && !element.isConnected) measure();
      }, 250);

      window.addEventListener("scroll", schedule, true);
      window.addEventListener("resize", schedule);

      const observer = new ResizeObserver(schedule);
      observer.observe(found);
      observer.observe(document.body);

      cleanups.push(() => {
        window.clearInterval(settle);
        window.clearInterval(watchdog);
        window.removeEventListener("scroll", schedule, true);
        window.removeEventListener("resize", schedule);
        observer.disconnect();
      });
    };

    const cleanups: (() => void)[] = [];

    const immediate = findTarget(target);
    if (immediate) {
      attach(immediate);
    } else {
      const observer = new MutationObserver(() => {
        const found = findTarget(target);
        if (!found) return;
        observer.disconnect();
        window.clearTimeout(timeout);
        if (!cancelled) attach(found);
      });

      observer.observe(document.body, { childList: true, subtree: true });

      const timeout = window.setTimeout(() => {
        observer.disconnect();
        if (!cancelled) setState({ status: "missing" });
      }, RETRY_MS);

      cleanups.push(() => {
        observer.disconnect();
        window.clearTimeout(timeout);
      });
    }

    return () => {
      cancelled = true;
      if (frame) window.cancelAnimationFrame(frame);
      cleanups.forEach((cleanup) => cleanup());
    };
  }, [target, nonce, generation]);

  return state;
}
