// The unit types inside a property.
//
// This is the one place in the workflow where asking twice is correct, and it
// is worth being precise about why, because the rest of MTC-KRP-026 is about
// never asking twice.
//
// A property fact is entered once: the property's type, its location, its
// amenities. A UNIT fact belongs to the unit. Cedar Line Apartments offering a
// Studio XL, a 1 Bedroom, a 1 Bed + Den and a 2 Bedroom has four genuinely
// different bedroom counts, four sizes, four prices and four availabilities.
// Deriving those from one property-level number would not be tidiness, it
// would be wrong — and it is exactly what MTC-KRP-024's derivations exist to
// go the other way: the figures at the TOP of the page are summarised from
// these, not typed again.
//
// So the property's own numbers seed the FIRST unit, as a convenience for the
// common case of a single home, and then stop. After that the unit is its own.
// Nothing here re-synchronises a unit to the property, ever: a manager who
// changes a unit's size meant to.

import type { FloorPlan } from "../../floor-plans/types";
import type { PropertyDraft } from "./draft";

let counter = 0;

function makeId(): string {
  counter += 1;
  return `plan-${counter}`;
}

/**
 * A new unit.
 *
 * The first one inherits the property's figures, because for a single house or
 * a one-layout building the manager has already typed them and typing them
 * again is the kind of thing that makes people stop using a CMS. Later ones
 * start empty, because a second unit that is identical to the first is not a
 * second unit.
 */
export function newFloorPlan(draft: PropertyDraft): FloorPlan {
  const first = (draft.floorPlans ?? []).length === 0;

  if (!first) {
    return {
      id: makeId(),
      label: "",
      title: "",
      description: "",
      bedrooms: 0,
      bathrooms: 1,
      squareFeet: 0,
      rentFrom: null,
      availability: "contact",
    };
  }

  return {
    id: makeId(),
    label: "",
    title: "",
    description: "",
    bedrooms: typeof draft.bedrooms === "number" ? draft.bedrooms : 0,
    bathrooms: typeof draft.bathrooms === "number" ? draft.bathrooms : 1,
    squareFeet: typeof draft.area === "number" ? draft.area : 0,
    /* Ask for Pricing at property level means this unit starts with no figure
       either, rather than inheriting one the property has chosen not to show. */
    rentFrom:
      draft.priceDisplay === "ask"
        ? null
        : typeof draft.rent === "number" && draft.rent > 0
          ? draft.rent
          : null,
    availability: "contact",
  };
}

export function addFloorPlan(draft: PropertyDraft): FloorPlan[] {
  return [...(draft.floorPlans ?? []), newFloorPlan(draft)];
}

export function updateFloorPlan(
  plans: FloorPlan[] | undefined,
  id: string,
  patch: Partial<FloorPlan>
): FloorPlan[] {
  return (plans ?? []).map((plan) => (plan.id === id ? { ...plan, ...patch } : plan));
}

export function removeFloorPlan(
  plans: FloorPlan[] | undefined,
  id: string
): FloorPlan[] {
  return (plans ?? []).filter((plan) => plan.id !== id);
}

/**
 * The unit's drawing, or none.
 *
 * Optional throughout. A client publishes a unit before its plan has been
 * redrawn all the time, and the public section already renders the unit's
 * name, size, availability and price without a picture — omitting the frame
 * rather than showing a placeholder or, worse, another unit's drawing. The one
 * thing that must never happen is a schematic being invented to fill the space.
 */
export function setFloorPlanImage(
  plans: FloorPlan[] | undefined,
  id: string,
  image: { src: string; alt: string } | null
): FloorPlan[] {
  return (plans ?? []).map((plan) => {
    if (plan.id !== id) return plan;
    const next = { ...plan };
    if (image) next.image = image;
    else delete next.image;
    return next;
  });
}

/**
 * The name shown in the public selector, filled in where it was left blank.
 *
 * `title` is the heading in the detail panel and `label` the tab; a manager who
 * types one and not the other means the same thing by both.
 */
export function withResolvedTitles(plans: FloorPlan[] | undefined): FloorPlan[] {
  return (plans ?? []).map((plan) => ({
    ...plan,
    title: plan.title?.trim() || plan.label,
  }));
}

export const planCount = (draft: PropertyDraft): number =>
  (draft.floorPlans ?? []).length;

export const plansWithoutImage = (draft: PropertyDraft): number =>
  (draft.floorPlans ?? []).filter((plan) => !plan.image).length;
