// @ppm--version--1.0

/**
 * Route for the full Leads view. `LEADS_VIEW_PATH` is what the plugin
 * registers; CmsRouter resolves it under /dashboard, and CmsLayout builds the
 * nav entry from it. Both live here so the plugin registration and the
 * preview's "View All" link cannot drift apart.
 */
export const LEADS_VIEW_PATH = "leads";
export const LEADS_ROUTE = `/dashboard/${LEADS_VIEW_PATH}`;

/**
 * The submission named by a Leads address, if any.
 *
 * `/dashboard/leads` is the list; `/dashboard/leads/<id>` is one submission.
 * Reading it from the path rather than from component state is what makes a
 * submission linkable and a refresh survivable — the capability the Application
 * Builder's Applicants tab had and this view did not, before MTC-KRP-030
 * brought submissions here for good.
 */
export function openLeadIdFrom(pathname: string): string | null {
  const tail = (pathname || "")
    .replace(/[?#].*$/, "")
    .replace(/^\/+|\/+$/g, "")
    .replace(new RegExp(`^dashboard\/${LEADS_VIEW_PATH}\/?`), "");

  return tail ? decodeURIComponent(tail.split("/")[0]) : null;
}

/**
 * Whether a submission is a rental application or a general enquiry.
 *
 * The Application Builder configures the first; the contact page produces the
 * second. They arrive in the same table, and reading them the same way loses
 * the most useful thing about a submission.
 */
export type LeadKind = "application" | "enquiry";

/** Lifecycle of a lead once it reaches the CMS. */
export type LeadStatus = "new" | "contacted" | "qualified";

export const LEAD_STATUSES: LeadStatus[] = ["new", "contacted", "qualified"];

export const LEAD_STATUS_LABELS: Record<LeadStatus, string> = {
  new: "New",
  contacted: "Contacted",
  qualified: "Qualified",
};

/**
 * One form submission from the customer's website, normalized for the UI.
 *
 * Fields mirror the submission actually stored in the leads repository —
 * submissionId, name, phone, email, message, siteId, tag, and mappings.form —
 * and nothing beyond it.
 *
 * `receivedAt` is epoch milliseconds, read from the submission's filename
 * (`<epochMillis>.json`); the payload itself carries no timestamp.
 *
 * `status` is NOT part of a submission. It stays optional and is currently
 * always undefined, which the UI renders as an em dash. Populate it once the
 * source or the CMS starts tracking lead state.
 */
export type Lead = {
  id: string;
  name: string;
  phone: string;
  email: string;
  message?: string;
  siteId?: string;
  /** Bracketed marker written by the source, e.g. "[raw][kahdel]". */
  tag?: string;
  /** Identifier of the originating form, read from `mappings.form`. */
  form?: string;
  receivedAt: number;
  status?: LeadStatus;
  /**
   * Which form this came from, as that form declared it.
   *
   * Absent on submissions received before MTC-KRP-047, which is why the Leads
   * view derives a fallback rather than showing those as unknown.
   */
  kind?: LeadKind;
  /**
   * When this lead was moved to the Trash, or absent if it never was.
   *
   * A soft delete, matching the Properties CMS and the Application Builder: a
   * submission is never destroyed by a click, it becomes recoverable for a
   * fixed window. What an applicant actually sent is worth keeping.
   */
  deletedAt?: string | null;
};

/** Contract for the Leads data source. */
export type LeadsApiAdapter = {
  fetchLeads: (privateKey: string) => Promise<Lead[]>;
  /**
   * Moves leads to the Trash, or restores them when `deletedAt` is null.
   *
   * Optional, because not every source can write. The GitHub source cannot —
   * its submissions are files in somebody else's repository — and the Leads
   * view hides the delete controls entirely rather than offering a button
   * that would fail. Resolves only when the change is actually stored.
   */
  setDeleted?: (ids: string[], deletedAt: string | null) => Promise<void>;
};
