// Rules for the Leads view: what the Trash holds, and how a submission reads.
//
// Pure functions over data, no React and no network, so the behaviour that
// matters can be tested without either.

import { TRASH_DAYS, daysRemaining, isExpired, isLive, live, trashed, trashedNewestFirst } from "../shared/trash.ts";
import type { Lead, LeadKind } from "./types";

/* Re-exported so the Leads view imports its rules from one place rather than
   reaching across the CMS for the shared half. */
export { TRASH_DAYS, daysRemaining, isExpired, isLive };

export const liveLeads = (leads: Lead[]): Lead[] => live(leads);

export const trashedLeads = (leads: Lead[], now: number): Lead[] =>
  trashed(leads, now);

export const trashedLeadsNewestFirst = (leads: Lead[], now: number): Lead[] =>
  trashedNewestFirst(leads, now);

/* ── reading a submission ────────────────────────────────── */

export type AnswerRow = { label: string; value: string };

/**
 * Turns the stored message into one row per answer.
 *
 * `buildMessage` writes a submission as `key: value` lines, one per question,
 * so an application arrives as a single string like
 *
 *   fullName: Application Test
 *   email: someone@example.com
 *   moveInDate: 2026-10-16
 *
 * The dialog rendered that verbatim, which is a record rather than something
 * anybody would choose to read. Split back into pairs it can be laid out as a
 * proper list, and — because the Application Builder lets an editor add any
 * question they like — it stays correct for fields nobody has seen yet.
 *
 * A line with no colon is not a key/value pair and is kept whole, so a plain
 * contact-form message never gets mangled into a label.
 */
export function answerRows(message: string | undefined): AnswerRow[] {
  if (!message) return [];

  const lines = message.split("\n").map((line) => line.trim()).filter(Boolean);

  /* Every line must look like a pair, or this is prose and not a form. One
     stray line would otherwise be silently dropped from somebody's enquiry. */
  const pairs = lines.map((line) => {
    const at = line.indexOf(":");
    if (at < 1) return null;

    const label = line.slice(0, at).trim();
    const value = line.slice(at + 1).trim();

    return label && value ? { label, value } : null;
  });

  if (pairs.some((pair) => pair === null)) return [];

  return (pairs as AnswerRow[]).map((pair) => ({
    label: humanise(pair.label),
    value: pair.value,
  }));
}

/**
 * "moveInDate" becomes "Move in date"; "full_name" becomes "Full name".
 *
 * The keys come from whatever the form called its fields, which is developer
 * spelling. A label reading "fullName" in front of a letting agent is the kind
 * of detail that makes software feel unfinished.
 */
export function humanise(key: string): string {
  const spaced = key
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim();

  if (!spaced) return key;

  return spaced.charAt(0).toUpperCase() + spaced.slice(1).toLowerCase();
}


/* ── application or enquiry (MTC-KRP-047) ────────────────── */

/**
 * The fields the public contact form asks for.
 *
 * Listed here rather than imported from the primitive on purpose: importing
 * `contactFields` would drag a React component, its template and its image
 * imports into anything that wants to classify a lead — including the test
 * runner, which cannot load a .jpg. `contactFieldsMatch` in the tests asserts
 * this list still matches the real form, so the two cannot drift apart
 * silently.
 */
export const CONTACT_FIELDS = ["fullName", "email", "phone", "reason", "message"];

/**
 * Whether a submission is a rental application or a general enquiry.
 *
 * Two sources, in order of trust:
 *
 *   1. What the form SAID it was. Since MTC-KRP-047 both public forms declare
 *      this, so for anything submitted from now on there is nothing to work
 *      out — it is recorded.
 *
 *   2. For older submissions, which carry no such record: whether the answers
 *      include a question the contact form does not have. The application asks
 *      about the property, the move-in date, occupants and pets; the contact
 *      form asks none of those. A submission containing any of them cannot
 *      have come from the contact form.
 *
 * The fallback is a comparison against the real field list, not a guess at
 * what an application "looks like" — and it only ever applies to submissions
 * received before the kind was recorded.
 */
export function leadKind(lead: Lead): LeadKind {
  if (lead.kind) return lead.kind;

  const answered = answerRows(lead.message).map((row) => row.label.toLowerCase());
  if (answered.length === 0) return "enquiry";

  /* Labels are humanised for display, so the known fields are humanised too
     rather than comparing a raw key against a pretty one. */
  const known = new Set(CONTACT_FIELDS.map((field) => humanise(field).toLowerCase()));

  return answered.some((label) => !known.has(label)) ? "application" : "enquiry";
}
