import React from "react";
import { LuTriangleAlert } from "react-icons/lu";

import type { FieldIssue } from "./validation";

/**
 * One field.
 *
 * Label above, control below, helper text under that — the composition the
 * MTC-KRP-025 QA settled on. It exists as a component rather than as a rule
 * everyone is asked to remember because this ticket adds roughly thirty
 * fields, and the one that forgets is the one the client screenshots.
 *
 * The error message is joined to the control with aria-describedby rather than
 * only being coloured red, so it is announced when the control takes focus and
 * not merely visible to someone already looking at it.
 */
export type FieldProps = {
  id: string;
  label: string;
  help?: React.ReactNode;
  error?: string | null;
  /** Marks the field as safe to leave blank, in words rather than by omission. */
  optional?: boolean;
  children: (aria: {
    id: string;
    "aria-describedby": string | undefined;
    "aria-invalid": true | undefined;
  }) => React.ReactNode;
};

export function Field({ id, label, help, error, optional, children }: FieldProps) {
  const helpId = help ? `${id}-help` : undefined;
  const errorId = error ? `${id}-error` : undefined;

  const described = [errorId, helpId].filter(Boolean).join(" ") || undefined;

  return (
    <div className="kr-wiz__field">
      <label className="kr-props__label" htmlFor={id}>
        {label}
        {optional ? <span className="kr-wiz__optional"> (optional)</span> : null}
      </label>

      {children({
        id,
        "aria-describedby": described,
        "aria-invalid": error ? true : undefined,
      })}

      {error ? (
        <p className="kr-wiz__error" id={errorId}>
          <LuTriangleAlert size={13} aria-hidden="true" />
          <span>{error}</span>
        </p>
      ) : null}

      {help ? (
        <p className="kr-wiz__help" id={helpId}>
          {help}
        </p>
      ) : null}
    </div>
  );
}

/* ── the controls ────────────────────────────────────────────
   Thin on purpose. Each is the Field above plus the one element it wraps, so
   there is no second styling system underneath and nothing to keep in step
   with the plugin sheet. */

type Common = {
  id: string;
  label: string;
  help?: React.ReactNode;
  error?: string | null;
  optional?: boolean;
};

export function TextField({
  value,
  onChange,
  placeholder,
  ...field
}: Common & {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
}) {
  return (
    <Field {...field}>
      {(aria) => (
        <input
          {...aria}
          className="kr-props__input"
          value={value}
          placeholder={placeholder}
          onChange={(event) => onChange(event.target.value)}
        />
      )}
    </Field>
  );
}

export function TextArea({
  value,
  onChange,
  placeholder,
  rows = 4,
  ...field
}: Common & {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  rows?: number;
}) {
  return (
    <Field {...field}>
      {(aria) => (
        <textarea
          {...aria}
          className="kr-props__input"
          rows={rows}
          value={value}
          placeholder={placeholder}
          onChange={(event) => onChange(event.target.value)}
        />
      )}
    </Field>
  );
}

export function SelectField({
  value,
  onChange,
  options,
  placeholder = "Choose one",
  ...field
}: Common & {
  value: string;
  onChange: (value: string) => void;
  options: { value: string; label: string }[];
  placeholder?: string;
}) {
  return (
    <Field {...field}>
      {(aria) => (
        <select
          {...aria}
          className="kr-props__input"
          value={value}
          onChange={(event) => onChange(event.target.value)}
        >
          <option value="">{placeholder}</option>
          {options.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      )}
    </Field>
  );
}

/**
 * A number, or nothing.
 *
 * An empty box is `undefined` rather than 0, which is the distinction the
 * whole validation model rests on: a field nobody has filled in is not a field
 * someone set to zero. Zero bedrooms is a studio and a real answer; zero
 * dollars is never one.
 */
export function NumberField({
  value,
  onChange,
  min,
  max,
  step,
  prefix,
  suffix,
  placeholder,
  ...field
}: Common & {
  value: number | undefined;
  onChange: (value: number | undefined) => void;
  min?: number;
  max?: number;
  step?: number | "any";
  prefix?: string;
  suffix?: string;
  placeholder?: string;
}) {
  return (
    <Field {...field}>
      {(aria) => (
        <span className={`kr-wiz__number${prefix ? " kr-wiz__number--prefixed" : ""}`}>
          {prefix ? (
            <span className="kr-wiz__affix" aria-hidden="true">
              {prefix}
            </span>
          ) : null}

          <input
            {...aria}
            className="kr-props__input"
            type="number"
            inputMode="decimal"
            min={min}
            max={max}
            step={step}
            placeholder={placeholder}
            value={value === undefined || value === null ? "" : String(value)}
            onChange={(event) => {
              const raw = event.target.value.trim();
              if (raw === "") return onChange(undefined);
              const parsed = Number(raw);
              onChange(Number.isNaN(parsed) ? undefined : parsed);
            }}
          />

          {suffix ? (
            <span className="kr-wiz__affix kr-wiz__affix--end" aria-hidden="true">
              {suffix}
            </span>
          ) : null}
        </span>
      )}
    </Field>
  );
}

/**
 * A small set of mutually exclusive choices, as real radios in a fieldset.
 *
 * A group of buttons that looks like this would leave a screen-reader user with
 * no idea the options belong together or how many there are.
 */
export function RadioGroup<T extends string>({
  name,
  legend,
  help,
  value,
  onChange,
  options,
}: {
  name: string;
  legend: string;
  help?: React.ReactNode;
  value: T;
  onChange: (value: T) => void;
  options: { value: T; label: string; help?: string }[];
}) {
  return (
    <fieldset className="kr-wiz__group">
      <legend className="kr-props__label">{legend}</legend>

      <div className="kr-wiz__choices">
        {options.map((option) => (
          <label
            key={option.value}
            className={`kr-wiz__choice${
              value === option.value ? " kr-wiz__choice--on" : ""
            }`}
          >
            <input
              type="radio"
              name={name}
              value={option.value}
              checked={value === option.value}
              onChange={() => onChange(option.value)}
            />
            <span>
              <span className="kr-wiz__choice-label">{option.label}</span>
              {option.help ? (
                <span className="kr-wiz__choice-help">{option.help}</span>
              ) : null}
            </span>
          </label>
        ))}
      </div>

      {help ? <p className="kr-wiz__help">{help}</p> : null}
    </fieldset>
  );
}

/** Turns the first issue for a control into the message that sits under it. */
export function errorFor(issues: FieldIssue[], field: string): string | null {
  const issue = issues.find((item) => item.field === field && item.kind === "error");
  return issue ? issue.message : null;
}
