import React, { useState } from "react";
import { LuArrowLeft, LuChevronRight, LuInfo, LuPlay } from "react-icons/lu";

import { hasTutorial } from "./tutorial/tutorials";

/**
 * Help.
 *
 * The same shape as the Application Builder's Help, deliberately: a chooser
 * rather than a manual. Seven topics expanded at once is more reading than the
 * whole feature needs and buries whichever one the reader actually came for.
 * Pick a topic, get its steps, go back.
 *
 * Topics are data, and each has a stable `id`. Where a walkthrough exists
 * under the same id, the topic offers to run it on the real screen.
 *
 * ── on the topics that have no walkthrough ──────────────────────────────
 * Two of these explain something rather than drive something. "Why can I not
 * open my new property" is the question this CMS actually provokes, and the
 * answer is a fact about how the website is built, not a button to press.
 * Spotlighting a control for it would be theatre. Those topics show their
 * steps and no Show Me button, which is why the button is conditional rather
 * than always rendered.
 */
export type HelpTopic = {
  id: string;
  title: string;
  summary: string;
  steps: string[];
};

