export type PropertiesHelpTabProps = {
  /** Starts a guided walkthrough. Supplied by the view, which owns the overlay. */
  onStartTutorial: (id: string) => void;
  /** Why a walkthrough cannot run yet, keyed by topic id. */
  unavailable: Record<string, string | null>;
};

export default function PropertiesHelpTab({
  onStartTutorial,
  unavailable,
}: PropertiesHelpTabProps) {
  const [openId, setOpenId] = useState<string | null>(null);
  const open = helpTopics.find((topic) => topic.id === openId) ?? null;

  if (open) {
    /* Three states, and they are genuinely different: this topic has no
       walkthrough at all, it has one that cannot run yet, or it has one ready
       to go. Collapsing the first two would tell somebody a walkthrough is
       blocked when none was ever written. */
    const walkthrough = hasTutorial(open.id);
    const blocked = walkthrough ? unavailable[open.id] : null;

    return (
      <div>
        <button
          type="button"
          className="kr-props__btn"
          style={{ marginBottom: 18 }}
          onClick={() => setOpenId(null)}
        >
          <LuArrowLeft size={14} aria-hidden="true" /> All Help Topics
        </button>

        <div className="kr-props__card kr-props__help-card">
          <h2 className="kr-props__help-title">{open.title}</h2>
          <p className="kr-props__hint kr-props__help-summary">{open.summary}</p>

          <ol className="kr-props__steps">
            {open.steps.map((step) => (
              <li key={step}>{step}</li>
            ))}
          </ol>

          {/* The walkthrough does the same thing on the real screen. Said in
              those words, because "start walkthrough" alone does not tell
              somebody they are about to be guided through the actual CMS. */}
          {!walkthrough ? null : blocked ? (
            <p className="kr-props__note kr-tut__start">
              <LuInfo
                size={15}
                className="kr-props__note-icon"
                aria-hidden="true"
              />
              <span>{blocked}</span>
            </p>
          ) : (
            <div className="kr-tut__start">
              <button
                type="button"
                className="kr-props__btn kr-props__btn--primary"
                onClick={() => onStartTutorial(open.id)}
              >
                <LuPlay size={14} aria-hidden="true" /> Show Me on the Screen
              </button>
              <p className="kr-props__hint" style={{ marginTop: 8 }}>
                Walks you through the real Properties screen, one step at a time.
              </p>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 className="kr-props__help-title" style={{ marginBottom: 4 }}>
        What would you like help with?
      </h2>
      <p className="kr-props__hint" style={{ margin: "0 0 18px" }}>
        Choose a topic for step-by-step instructions.
      </p>

      <div className="kr-props__card kr-props__topics">
        {helpTopics.map((topic) => (
          <button
            type="button"
            className="kr-props__topic"
            key={topic.id}
            onClick={() => setOpenId(topic.id)}
          >
            <span className="kr-props__topic-main">
              <span className="kr-props__topic-title">{topic.title}</span>
              <span className="kr-props__topic-summary">{topic.summary}</span>
            </span>
            <LuChevronRight size={17} className="kr-props__topic-arrow" />
          </button>
        ))}
      </div>
    </div>
  );
}
