// @ppm--version--1.0
// Display helpers for lead records. Pure functions — no browser APIs, so these
// are safe to evaluate during the Gatsby SSR build.

/** "Jacob Jones" -> "JJ", "Cher" -> "CH". Falls back to "?" when empty. */
export function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);

  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();

  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/** Stable index into a palette, so a given lead always gets the same tint. */
export function tintIndex(seed: string, buckets: number): number {
  let hash = 0;

  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) | 0;
  }

  return Math.abs(hash) % Math.max(1, buckets);
}

/** Compact absolute stamp — "30 Aug, 14:05". Used before `now` is known. */
export function formatAbsolute(receivedAt: number): string {
  const date = new Date(receivedAt);

  if (!Number.isFinite(receivedAt)) return "Unknown";

  return `${date.toLocaleDateString(undefined, {
    day: "numeric",
    month: "short",
  })}, ${date.toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
  })}`;
}

/**
 * "Just now" / "12 min ago" / "3 hr ago" / "5 days ago", falling back to the
 * absolute stamp beyond a week — or whenever `now` is null, which is the case
 * on the very first render (see `useNow`). Keeping the first paint absolute
 * avoids a server/client mismatch on a value derived from the clock.
 */
export function formatReceived(receivedAt: number, now: number | null): string {
  if (!Number.isFinite(receivedAt)) return "Unknown";
  if (now === null) return formatAbsolute(receivedAt);

  const minutes = Math.floor((now - receivedAt) / 60_000);

  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes} min ago`;

  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} hr ago`;

  const days = Math.floor(hours / 24);
  if (days <= 7) return days === 1 ? "Yesterday" : `${days} days ago`;

  return formatAbsolute(receivedAt);
}

/** Strips formatting so the value is safe inside a tel: URL. */
export function telHref(phone: string): string {
  return `tel:${phone.replace(/[^\d+]/g, "")}`;
}

/** One-line summary used by the "copy details" quick action. */
export function contactSummary(lead: {
  name: string;
  phone: string;
  email: string;
}): string {
  return `${lead.name} · ${lead.phone} · ${lead.email}`;
}
