// Where the Leads view gets its submissions.
//
// Two sources, one interface. The GitHub one pulls encrypted submissions and
// decrypts them in the browser with the site's private key. The Supabase one
// reads rows the public forms inserted directly, and ignores the private key
// it is handed — there is nothing to decrypt, because Row Level Security is
// what keeps those rows unreadable to anybody who is not signed in.
//
// `fetchLeads` keeps its signature either way, so LeadsView, the table, the
// popout and the quick actions are unchanged.

import { decryptObject } from "../../utilities/crypto/decryptSubmission";
import { pullLeadsFromGitHub } from "./githubSource";
import { normalizeLead } from "./normalizeLead";
import { fetchLeadRows, setLeadsDeleted } from "../supabase/leads";
import { usingSupabase } from "../supabase/enabled";
import type { Lead, LeadsApiAdapter } from "./types";

export const supabaseLeadsApi: LeadsApiAdapter = {
  async fetchLeads(): Promise<Lead[]> {
    const result = await fetchLeadRows();

    /* Thrown, because that is what the view already handles. A silent empty
       list would read as "no enquiries yet", which is the worst possible way
       to report a broken connection to somebody waiting on applications. */
    if (!result.ok) throw new Error(result.error.message);

    return result.data;
  },

  async setDeleted(ids: string[], deletedAt: string | null): Promise<void> {
    const result = await setLeadsDeleted(ids, deletedAt);

    /* Thrown, so the view can only show "deleted" after it really happened.
       A delete that silently did nothing is the kind of thing somebody
       discovers a month later when the lead is still sitting there. */
    if (!result.ok) throw new Error(result.error.message);
  },
};

export const githubLeadsApi: LeadsApiAdapter = {
  async fetchLeads(privateKey: string): Promise<Lead[]> {
    const submissions = await pullLeadsFromGitHub();

    const leads = await Promise.all(
      submissions.map(async ({ filename, data }) => {
        try {
          const record = await decryptObject(data, privateKey);

          return normalizeLead(
            filename,
            record as Record<string, unknown>
          );
        } catch (error) {
          console.error(
            `[leads] Could not decrypt submission ${filename}`,
            error
          );

          return null;
        }
      })
    );

    return leads
      .filter((lead): lead is Lead => lead !== null)
      .sort((a, b) => b.receivedAt - a.receivedAt);
  },

  /* No setDeleted. These submissions are files in a content repository this
     CMS can only read, so there is nothing honest to implement. The Leads view
     checks for the method and hides the delete controls rather than offering a
     button that would fail. */
};

export const leadsApi: LeadsApiAdapter = usingSupabase()
  ? supabaseLeadsApi
  : githubLeadsApi;
