// @ppm--version--1.0

import React from "react";
import { FaChevronDown, FaFilter, FaSearch } from "react-icons/fa";
import { LuRefreshCw, LuTrash2 } from "react-icons/lu";

import { LEAD_STATUSES, LEAD_STATUS_LABELS } from "./types";
import type { LeadStatus } from "./types";

import template from "../../config/gh-leads--template";
import { TableToggles } from "../../config/gh-leads--ui-table-settings";

export type StatusFilter = LeadStatus | "all";

const labels = template.labels;

type Props = {
  query: string;
  onQueryChange: (value: string) => void;
  status: StatusFilter;
  onStatusChange: (value: StatusFilter) => void;
  shown: number;
  total: number;
  selectedCount: number;
  loading: boolean;
  /** False when the source cannot write; the controls are then absent. */
  /** Re-reads the list from the database. */
  onRefresh: () => void;
  refreshing: boolean;
  canDelete: boolean;
  selecting: boolean;
  busy: boolean;
  onStartSelecting: () => void;
  onCancelSelecting: () => void;
  onDelete: () => void;
};

/**
 * Restrained by design: this is a viewer for leads the customer's site
 * produced, so it carries search, a status filter and a count. Since
 * MTC-KRP-041 it also carries the delete control, and nothing else — there is
 * still no create or export here, because nothing creates a lead but a
 * visitor filling in a form.
 */
export default function LeadsToolbar({
  query,
  onQueryChange,
  status,
  onStatusChange,
  shown,
  total,
  selectedCount,
  loading,
  onRefresh,
  refreshing,
  canDelete,
  selecting,
  busy,
  onStartSelecting,
  onCancelSelecting,
  onDelete,
}: Props) {
  return (
    <div className="leads-toolbar">
      <div className="leads-toolbar__left">
        <div className="leads-search">
          <span className="leads-search__icon">
            <FaSearch size={12} />
          </span>

          <input
            className="leads-search__input"
            type="search"
            value={query}
            onChange={(event) => onQueryChange(event.target.value)}
            placeholder={labels.searchPlaceholder}
            aria-label="Search leads by name, email or phone"
          />
        </div>


        { !TableToggles.STATUS ? <></> :
          <div className="leads-filter">
            <span className="leads-filter__icon">
              <FaFilter size={11} />
            </span>

            <select
              className="leads-filter__select"
              value={status}
              onChange={(event) => onStatusChange(event.target.value as StatusFilter)}
              aria-label="Filter leads by status"
            >
              <option value="all">{labels.allStatuses}</option>
              {LEAD_STATUSES.map((value) => (
                <option key={value} value={value}>
                  {LEAD_STATUS_LABELS[value]}
                </option>
              ))}
            </select>

            <span className="leads-filter__caret">
              <FaChevronDown size={10} />
            </span>
          </div>
        }

      </div>

      <div className="leads-toolbar__right">
        {/* Leads arrive while somebody is looking at the list, and nothing
            pushes them to the screen - so without this the only way to find
            out was to reload the whole CMS. Hidden during selection: a list
            that reorders itself under a half-made selection is worse than no
            refresh at all. */}
        {selecting ? null : (
          <button
            type="button"
            className="leads-detail__btn"
            onClick={onRefresh}
            disabled={refreshing}
          >
            <LuRefreshCw
              size={14}
              aria-hidden="true"
              className={refreshing ? "leads-spin" : undefined}
            />
            {refreshing ? labels.refreshing : labels.refresh}
          </button>
        )}

        {/* ── delete ────────────────────────────────────
            Out of selection mode the red button ARMS the mode; in it, the same
            button is the delete and needs something chosen. Cancel sits to its
            left, which is where the Properties CMS puts it. */}
        {canDelete ? (
          <div className="leads-toolbar__actions">
            {selecting ? (
              <button
                type="button"
                className="leads-detail__btn"
                onClick={onCancelSelecting}
                disabled={busy}
              >
                {labels.cancel}
              </button>
            ) : null}

            <button
              type="button"
              className="leads-detail__btn leads-detail__btn--danger"
              disabled={busy || (selecting && selectedCount === 0)}
              onClick={selecting ? onDelete : onStartSelecting}
            >
              <LuTrash2 size={14} aria-hidden="true" />
              {labels.delete}
            </button>
          </div>
        ) : null}

      </div>
    </div>
  );
}
