// One submission, as a page (MTC-KRP-042).
//
// Replaces LeadPopout. The content is the same — the same fields, the same
// toggles, the same quick actions — but it is no longer trapped in an overlay.
//
// ── why a page beats the dialog it replaces ──────────────────────────────
// A rental application is not a tooltip. It is the thing the person opened the
// CMS to read, often several screens of answers, and the dialog gave it a
// fixed box in the middle of a greyed-out list: it scrolled inside itself,
// could not be printed, locked the page behind it, and on a laptop showed
// about a third of a long application at a time.
//
// The route already existed — /dashboard/leads/<id>, since MTC-KRP-030 — so a
// submission was already linkable and refreshable. This just stops covering
// the page with it.

import React from "react";
import { LuArrowLeft, LuDownload, LuTrash2 } from "react-icons/lu";

import template from "../../templates/gh-leads/default-template";
import LeadQuickActions from "./LeadQuickActions";
import { formatAbsolute } from "./format";
import { answerRows, leadKind } from "./leadRules";
import type { Lead } from "./types";
import { LeadPopoutToggles } from "../../config/gh-leads--ui-table-settings";
import { BUSINESS_NAME } from "../../config/profile--business-name";

const labels = template.labels;
const fields = labels.popoutFields;

type Props = {
  lead: Lead;
  /** Back to the list. */
  onBack: () => void;
  /** Absent when the source cannot write, which hides the control. */
  onDelete?: () => void;
  /** True while this lead is in the Trash; it is then restored, not deleted. */
  trashed?: boolean;
  onRestore?: () => void;
  busy?: boolean;
};

/** One label/value row. Renders nothing when the value is absent. */
function Field({
  toggle,
  label,
  value,
  href,
  className,
}: {
  toggle?: boolean;
  label: string;
  value?: string;
  href?: string;
  className?: string;
}) {
  if (!value) return null;
  if (toggle === false) return null;

  return (
    <div className="leads-field">
      <span className="leads-field__label">{label}</span>
      <span
        className={
          className ? `leads-field__value ${className}` : "leads-field__value"
        }
      >
        {href ? <a href={href}>{value}</a> : value}
      </span>
    </div>
  );
}

export default function LeadDetail({
  lead,
  onBack,
  onDelete,
  trashed = false,
  onRestore,
  busy = false,
}: Props) {
  const received = lead.receivedAt ? formatAbsolute(lead.receivedAt) : "";

  /* The submitted answers, one per row, rather than the single run-on string
     the message field holds. Same data; the dialog showed it as a paragraph
     of "fullName: ... email: ..." which is a record, not something to read. */
  const rows = answerRows(lead.message);

  /**
   * Hands the page to the browser's print dialog, where "Save as PDF" is the
   * default destination on every current browser.
   *
   * Deliberately not a PDF library. A print stylesheet produces a PDF with
   * real selectable, searchable text at the printer's resolution; html2canvas
   * plus jsPDF would produce a screenshot of a screen — fuzzy when printed,
   * impossible to copy an email address out of, and several hundred kilobytes
   * of dependency to do it. The trade is one extra click in the print dialog.
   */
  const downloadPdf = () => {
    /* The title becomes the suggested filename in the save dialog, so it is
       worth it being the applicant's name rather than "dashboard". Restored
       afterwards so the tab does not keep the lead's name. */
    const previous = document.title;
    const name = (lead.name || "lead").replace(/[^\w -]+/g, "").trim();

    document.title = `${name} — ${received || "submission"}`;

    const restore = () => {
      document.title = previous;
      window.removeEventListener("afterprint", restore);
    };

    window.addEventListener("afterprint", restore);
    window.print();

    /* Safari does not always fire afterprint. A timer is the backstop so the
       tab title cannot get stuck on a lead's name. */
    window.setTimeout(restore, 1000);
  };

  return (
    <div className="leads-detail">
      {/* ── the bar above the record ───────────────────────
          Back on the left because that is where people look for it, actions on
          the right. Excluded from print: a printed page has no buttons. */}
      <div className="leads-detail__bar leads-no-print">
        <button type="button" className="leads-detail__back" onClick={onBack}>
          <LuArrowLeft size={15} aria-hidden="true" />
          {labels.detailBack}
        </button>

        <div className="leads-detail__bar-actions">
          <button
            type="button"
            className="leads-detail__btn"
            onClick={downloadPdf}
          >
            <LuDownload size={15} aria-hidden="true" />
            {labels.detailDownload}
          </button>

          {trashed && onRestore ? (
            <button
              type="button"
              className="leads-detail__btn"
              onClick={onRestore}
              disabled={busy}
            >
              {labels.restore}
            </button>
          ) : null}

          {!trashed && onDelete ? (
            <button
              type="button"
              className="leads-detail__btn leads-detail__btn--danger"
              onClick={onDelete}
              disabled={busy}
            >
              <LuTrash2 size={15} aria-hidden="true" />
              {labels.delete}
            </button>
          ) : null}
        </div>
      </div>

      {/* ── the record itself ──────────────────────────────
          This is what prints. */}
      <article className="leads-detail__sheet">
        {/* Print only. On screen the page already says whose CMS this is and
            what is being looked at; on paper none of that survives, and what
            came out instead was the navigation furniture - a menu button and
            the words "Content Management System". A printed enquiry should
            say who it is from and what it is. */}
        <div className="leads-print-head" aria-hidden="true">
          <p className="leads-print-head__business">{BUSINESS_NAME}</p>
          <p className="leads-print-head__kind">
            {leadKind(lead) === "application"
              ? "Rental Application"
              : "Contact Lead"}
          </p>
        </div>

        <header className="leads-detail__head">
          <h1 className="leads-detail__title">{lead.name || "Lead"}</h1>

          <span className={`leads-kind leads-kind--${leadKind(lead)}`}>
            {leadKind(lead) === "application"
              ? labels.kindApplication
              : labels.kindEnquiry}
          </span>
          {received && <p className="leads-detail__sub">{received}</p>}

          <div className="leads-no-print">
            <LeadQuickActions
              lead={lead}
              toggle={{ phone: false, submenu: false, email: false }}
            />
          </div>
        </header>

        {trashed ? (
          <p className="leads-detail__trashed leads-no-print">
            {labels.detailTrashed}
          </p>
        ) : null}

        <div className="leads-detail__panes">
          <section className="leads-detail__pane">
            <h2 className="leads-detail__section">{labels.popoutMessage}</h2>

            {rows.length > 0 ? (
              <dl className="leads-answers">
                {rows.map((row) => (
                  <div className="leads-answers__row" key={row.label}>
                    <dt className="leads-answers__label">{row.label}</dt>
                    <dd className="leads-answers__value">{row.value}</dd>
                  </div>
                ))}
              </dl>
            ) : lead.message ? (
              <p className="leads-detail__message">{lead.message}</p>
            ) : (
              <p className="leads-detail__message leads-detail__message--empty">
                {labels.popoutNoMessage}
              </p>
            )}
          </section>

          {/* `--repeat` marks this pane as saying nothing the pane beside it
              does not already say, which is true exactly when the submission
              parsed into answers. Print drops it on that basis; on screen it
              stays, because side by side the repetition is useful. */}
          <aside
            className={`leads-detail__pane leads-detail__pane--details${
              rows.length > 0 ? " leads-detail__pane--repeat" : ""
            }`}
          >
            <h2 className="leads-detail__section">{labels.popoutDetails}</h2>

            <Field label={fields.name} value={lead.name} />
            <Field
              label={fields.email}
              value={lead.email}
              href={lead.email ? `mailto:${lead.email}` : undefined}
            />
            <Field
              label={fields.phone}
              value={lead.phone}
              href={
                lead.phone ? `tel:${lead.phone.replace(/[^\d+]/g, "")}` : undefined
              }
            />
            <Field
              label={fields.form}
              value={lead.form}
              toggle={LeadPopoutToggles.FORM_ID}
            />
            <Field
              label={fields.site}
              value={lead.siteId}
              toggle={LeadPopoutToggles.SITE_ID}
            />
            <Field
              label={fields.tag}
              value={lead.tag}
              toggle={LeadPopoutToggles.SITE_TAG}
            />
            <Field label={fields.received} value={received} />
            <Field
              label={fields.submissionId}
              value={lead.id}
              className="leads-field__value--id leads-field__value--muted"
              toggle={LeadPopoutToggles.SUBMISSION_ID}
            />
          </aside>
        </div>
      </article>
    </div>
  );
}
