// @ppm--version--1.1
//
// Container for the full Leads page: owns loading, search, filter, selection
// and deletion state, and composes the toolbar with the table. All presentation
// lives in LeadsToolbar / LeadsTable / LeadDetail and the styling in
// templates/gh-leads.
//
// MTC-KRP-041 added deletion, MTC-KRP-042 turned the submission dialog into a
// page. Both follow conventions this CMS already has rather than inventing
// new ones: the delete flow is the Properties CMS's (red Delete arms a
// selection, Cancel appears beside it, a toast counts, a confirm names the
// consequence, a Trash tab holds it for 30 days), and the tab strip is the
// same shared component the Properties CMS and the Application Builder use.

import React, { useCallback, useEffect, useMemo, useState } from "react";

import CmsTabs from "../shared/CmsTabs";
import SelectionToast from "../shared/SelectionToast";
import LeadDetail from "./LeadDetail";
import LeadsTrashTab from "./LeadsTrashTab";
import { openLeadIdFrom } from "./types";
import LeadsTable from "./LeadsTable";
import LeadsToolbar from "./LeadsToolbar";
import { useNow } from "./useNow";
import { TRASH_DAYS, liveLeads, trashedLeads } from "./leadRules";
import type { StatusFilter } from "./LeadsToolbar";
import type { Lead, LeadsApiAdapter } from "./types";
import { getPrivateKey } from "./getPrivateKey";
import template from "../../config/gh-leads--template";

const labels = template.labels;

type Props = {
  api: LeadsApiAdapter;
  /** The full pathname, so the open submission can live in the URL. */
  pathname: string;
  /** Navigates to a submission, or back to the list when given null. */
  onOpenLead: (id: string | null) => void;
};

type TabKey = "leads" | "trash";

function matches(lead: Lead, needle: string): boolean {
  if (!needle) return true;

  const haystack = `${lead.name} ${lead.email} ${lead.phone}`.toLowerCase();

  // Digits-only comparison as well, so "3105553890" finds "+1 (310) 555-3890".
  const digits = needle.replace(/\D/g, "");
  const phoneDigits = lead.phone.replace(/\D/g, "");

  return (
    haystack.includes(needle.toLowerCase()) ||
    (digits.length >= 3 && phoneDigits.includes(digits))
  );
}

export default function LeadsView({ api, pathname, onOpenLead }: Props) {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [failed, setFailed] = useState(false);

  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<StatusFilter>("all");
  const [tab, setTab] = useState<TabKey>("leads");

  /* ── delete mode ──────────────────────────────────────
     What is selected is something the user is doing right now, not a fact
     about the lead, so it is not persisted and a refresh clears it.
     `deletedAt` IS lead data and goes through the adapter like everything. */
  const [selecting, setSelecting] = useState(false);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);

  /* Whether this source can write at all. The GitHub source reads files from
     a repository it does not own, so the delete controls are hidden rather
     than offered and then failing. */
  const canDelete = typeof api.setDeleted === "function";

  /* The open lead is named by the URL rather than held in local state.
     MTC-KRP-030 moved submissions here from the Application Builder, and the
     one thing that view did better was this: a colleague could be sent
     straight to a submission, and a refresh came back to it. Local state
     cannot do either. */
  const openId = openLeadIdFrom(pathname);
  const openLead = useMemo(
    () => leads.find((lead) => lead.id === openId) ?? null,
    [leads, openId]
  );

  const setOpenLead = useCallback(
    (lead: Lead | null) => onOpenLead(lead ? lead.id : null),
    [onOpenLead]
  );

  const now = useNow();

  const load = useCallback(async () => {
    try {
      const key = await getPrivateKey();
      const records = await api.fetchLeads(key);

      setLeads(records);
      setFailed(false);
    } catch (error) {
      // Detail goes to the console for developers; the UI gets one plain
      // sentence. Never surface transport or crypto details to the user.
      console.error("[leads] Unable to load leads", error);

      setLeads([]);
      setFailed(true);
    } finally {
      setLoading(false);
    }
  }, [api]);

  useEffect(() => {
    let cancelled = false;

    const run = async () => {
      await load();
      if (cancelled) return;
    };

    run();

    return () => {
      cancelled = true;
    };
  }, [load]);

  /* The two halves. Everything below reads one or the other, never the
     unfiltered list — a trashed lead must not appear anywhere it could be
     mistaken for a live one. */
  const active = useMemo(() => liveLeads(leads), [leads]);
  const inTrash = useMemo(
    () => (now === null ? [] : trashedLeads(leads, now)),
    [leads, now]
  );

  const visible = useMemo(() => {
    const needle = query.trim();

    return active.filter(
      (lead) =>
        matches(lead, needle) && (status === "all" || lead.status === status)
    );
  }, [active, query, status]);

  // Drop selections the current filter hides, so the count never claims more
  // than the user can see.
  const visibleIds = useMemo(() => new Set(visible.map((l) => l.id)), [visible]);
  const activeSelection = selectedIds.filter((id) => visibleIds.has(id));

  const toggle = (id: string) =>
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((value) => value !== id) : [...prev, id]
    );

  const toggleAll = () =>
    setSelectedIds((prev) => {
      const allSelected =
        visible.length > 0 && visible.every((l) => prev.includes(l.id));

      return allSelected
        ? prev.filter((id) => !visibleIds.has(id))
        : [...new Set([...prev, ...visible.map((l) => l.id)])];
    });

  const leaveSelection = useCallback(() => {
    setSelecting(false);
    setSelectedIds([]);
    setConfirming(false);
  }, []);

  /**
   * Writes the change, then reports whether it actually happened.
   *
   * Reloads from the source afterwards rather than patching local state, so
   * what the screen shows is what is stored. A list that says "deleted" while
   * the database disagrees is worse than an error.
   */
  const applyDeletion = useCallback(
    async (ids: string[], deletedAt: string | null) => {
      if (!api.setDeleted || ids.length === 0) return;

      setBusy(true);
      setProblem(null);

      try {
        await api.setDeleted(ids, deletedAt);
        await load();
        leaveSelection();
      } catch (error) {
        setProblem(
          error instanceof Error
            ? error.message
            : "That could not be saved. Nothing was changed."
        );
      } finally {
        setBusy(false);
      }
    },
    [api, load, leaveSelection]
  );

  /* Deliberately the same `load` the first render uses, so a refresh cannot
     drift into fetching something slightly different from the initial list. */
  const refresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await load();
    } finally {
      setRefreshing(false);
    }
  }, [load]);

  const filtered = Boolean(query.trim()) || status !== "all";

  /* ── one submission, full page ──────────────────────────
     Rendered INSTEAD of the list, not on top of it. */
  if (openLead) {
    return (
      <LeadDetail
        lead={openLead}
        onBack={() => setOpenLead(null)}
        busy={busy}
        trashed={Boolean(openLead.deletedAt)}
        onDelete={
          canDelete
            ? () => void applyDeletion([openLead.id], new Date().toISOString())
            : undefined
        }
        onRestore={
          canDelete ? () => void applyDeletion([openLead.id], null) : undefined
        }
      />
    );
  }

  return (
    <div className="leads-card">
      <CmsTabs<TabKey>
        tabs={[
          { key: "leads", label: labels.tabLeads, count: active.length },
          { key: "trash", label: labels.tabTrash, count: inTrash.length },
        ]}
        active={tab}
        onChange={(key) => {
          setTab(key);
          leaveSelection();
        }}
        idPrefix="leads"
        label={labels.tabsLabel}
        classPrefix="leads"
        /* On the tab row, beside the tab it is counting - it used to sit in
           the toolbar underneath, describing the list from a second place. */
        trailing={
          tab === "leads" ? (
            <span className="leads-count" aria-live="polite">
              {loading ? (
                labels.loading
              ) : (
                <>
                  Showing <strong>{visible.length}</strong> of{" "}
                  <strong>{active.length}</strong>
                  {active.length === 1 ? " lead" : " leads"}
                </>
              )}
            </span>
          ) : null
        }
      />

      {problem ? (
        <p className="leads-problem" role="alert">
          {problem}
        </p>
      ) : null}

      {tab === "trash" ? (
        <LeadsTrashTab
          leads={inTrash}
          now={now}
          busy={busy}
          onRestore={(id) => void applyDeletion([id], null)}
          onOpenLead={setOpenLead}
        />
      ) : (
        <>
          <LeadsToolbar
            query={query}
            onQueryChange={setQuery}
            status={status}
            onStatusChange={setStatus}
            shown={visible.length}
            total={active.length}
            selectedCount={activeSelection.length}
            loading={loading}
            onRefresh={() => void refresh()}
            refreshing={refreshing}
            /* Hidden entirely when the source cannot write. */
            canDelete={canDelete}
            selecting={selecting}
            busy={busy}
            onStartSelecting={() => setSelecting(true)}
            onCancelSelecting={leaveSelection}
            onDelete={() => setConfirming(true)}
          />

          <LeadsTable
            leads={visible}
            loading={loading}
            now={now}
            selecting={selecting}
            selectedIds={activeSelection}
            onToggle={toggle}
            onToggleAll={toggleAll}
            onOpenLead={setOpenLead}
            emptyTitle={
              failed
                ? labels.errorTitle
                : filtered
                  ? labels.noMatchTitle
                  : labels.emptyTitle
            }
            emptyText={
              failed
                ? labels.errorText
                : filtered
                  ? labels.noMatchText
                  : labels.emptyText
            }
          />
        </>
      )}

      {selecting ? (
        <SelectionToast
          count={activeSelection.length}
          noun="lead"
          classPrefix="leads"
        />
      ) : null}

      {/* ── the confirm ────────────────────────────────────
          Names the number, and says plainly that it is recoverable. The
          Properties CMS says the same sentence for the same reason: somebody
          deleting four applications deserves to know they are not gone. */}
      {confirming ? (
        <div
          className="leads-confirm-overlay"
          onClick={() => (busy ? null : setConfirming(false))}
        >
          <div
            className="leads-confirm"
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="leads-confirm-title"
            onClick={(event) => event.stopPropagation()}
          >
            <h2 className="leads-confirm__title" id="leads-confirm-title">
              {labels.confirmTitle(activeSelection.length)}
            </h2>
            <p className="leads-confirm__text">
              {labels.confirmText(activeSelection.length, TRASH_DAYS)}
            </p>

            <div className="leads-confirm__actions">
              <button
                type="button"
                className="leads-detail__btn"
                onClick={() => setConfirming(false)}
                disabled={busy}
              >
                {labels.cancel}
              </button>
              <button
                type="button"
                className="leads-detail__btn leads-detail__btn--danger"
                disabled={busy}
                onClick={() =>
                  void applyDeletion(activeSelection, new Date().toISOString())
                }
              >
                {busy ? labels.deleting : labels.delete}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}
