// @ppm--version--1.0
// @ppm--dependency--config.template--leads
//
// Compact dashboard card listing the most recent leads.
//
// Registered into the "dashboard" slot. PluginSlot renders slot components
// with no props at all, so this owns its own data loading — the same shape as
// gh-image's GhImageDashboardSlot.

import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { FaArrowRight, FaClipboardList } from "react-icons/fa";

import LeadAvatar from "./LeadAvatar";
import { leadsApi } from "./leadsApi";
import { formatReceived } from "./format";
import { useNow } from "./useNow";
import { LEADS_ROUTE } from "./types";
import type { Lead } from "./types";
import template from "../../templates/gh-leads/default-template";
import { getPrivateKey } from "./getPrivateKey";

const s = template.preview;
const labels = template.labels;



export default function LeadsPreview() {
  const [recent, setRecent] = useState<Lead[]>([]);
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");

  const now = useNow();

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      try {
        const key = await getPrivateKey()
        const records = await leadsApi.fetchLeads( key );
        if (cancelled) return;

        // The service already returns newest first, so the preview is simply
        // the head of the same normalized list the full view renders.
        setRecent(records.slice(0, template.previewRows));
        setState("ready");
      } catch (error) {
        if (cancelled) return;

        console.error("[leads] Unable to load leads", error);

        setRecent([]);
        setState("error");
      }
    };

    load();

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <section style={s.card}>
      <div style={s.header}>
        <div style={s.headingWrap}>
          <div style={s.icon}>
            <FaClipboardList size={18} />
          </div>

          <div>
            <h2 style={s.title}>{labels.previewTitle}</h2>
            <p style={s.sub}>{labels.previewSubtitle}</p>
          </div>
        </div>

        <Link to={LEADS_ROUTE} style={s.link}>
          {labels.previewLink} <FaArrowRight size={11} />
        </Link>
      </div>

      {state === "loading" && <div style={s.empty}>{labels.previewLoading}</div>}

      {state === "error" && <div style={s.empty}>{labels.previewError}</div>}

      {state === "ready" && recent.length === 0 && (
        <div style={s.empty}>{labels.previewEmpty}</div>
      )}

      {recent.length > 0 && (
        <div style={s.list}>
          {recent.map((lead) => (
            <div key={lead.id} style={s.row}>
              <LeadAvatar name={lead.name} size="lg" />

              <div style={s.rowText}>
                <p style={s.rowName} title={lead.name}>
                  {lead.name}
                </p>
                <p style={s.rowDetail} title={lead.email}>
                  {lead.email}
                </p>
              </div>

              <span style={s.rowTime}>{formatReceived(lead.receivedAt, now)}</span>
            </div>
          ))}
        </div>
      )}
    </section>
  );
}
