// How long a deleted thing stays recoverable.
//
// One number, one meaning, site-wide. It was already written out twice — once
// in the Application Builder's rules and once in the Properties CMS's — and
// MTC-KRP-041 brings Leads into the same model, which would have made three.
// Three is the number at which somebody changes one of them.
//
// The date arithmetic lives here too, because "is this expired" is the same
// question wherever it is asked and the two existing copies had already drifted
// into different shapes while agreeing on the answer by luck.

/** The recovery window, in days, for anything the CMS deletes. */
export const TRASH_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

/** Anything carrying the soft-delete marker: a lead, a property, a form. */
export type Deletable = { deletedAt?: string | null };

/** Nothing has deleted it. An absent marker is the normal state. */
export const isLive = (item: Deletable): boolean => !item.deletedAt;

export function live<T extends Deletable>(items: T[]): T[] {
  return items.filter(isLive);
}

/**
 * How long a deleted item has left.
 *
 * Derived from `deletedAt` on every read rather than stored and counted down,
 * so it is right whenever the CMS is opened rather than right only if
 * something kept ticking while nobody was looking.
 */
export function daysRemaining(deletedAt: string, now: number): number {
  const elapsed = now - new Date(deletedAt).getTime();
  return Math.max(0, TRASH_DAYS - Math.floor(elapsed / DAY_MS));
}

export function isExpired(deletedAt: string, now: number): boolean {
  return daysRemaining(deletedAt, now) <= 0;
}

/**
 * What a Trash shows: deleted, and still inside its window.
 *
 * An expired item stops being listed and stops being restorable. It is NOT
 * removed from storage here — purging is a separate act against the stored
 * data, and pretending a render performs it would be a lie about where the
 * data lives.
 */
export function trashed<T extends Deletable>(items: T[], now: number): T[] {
  return items.filter((item) => item.deletedAt && !isExpired(item.deletedAt, now));
}

/** Newest first — the thing you just deleted is the thing you want back. */
export function trashedNewestFirst<T extends Deletable>(items: T[], now: number): T[] {
  return [...trashed(items, now)].sort(
    (a, b) => new Date(b.deletedAt as string).getTime() - new Date(a.deletedAt as string).getTime()
  );
}
