import type { Property } from "./types";

export type SearchableProperty = Pick<Property, "title" | "location" | "type">;

/** Free-text match on a property's title, location or type. Empty matches all. */
export const matchesTerm = (property: SearchableProperty, term: string) => {
  if (!term.trim()) return true;
  const needle = term.trim().toLowerCase();
  return (
    property.title.toLowerCase().includes(needle) ||
    property.location.toLowerCase().includes(needle) ||
    property.type.toLowerCase().includes(needle)
  );
};
