// Which other properties appear at the bottom of this one.
//
// The automatic scoring already exists (findSimilar.ts) and the rule for
// applying an author's adjustments already exists (derive.applySimilarOverrides)
// — both shipped with MTC-KRP-024 and both are what the public page runs. This
// file does not re-implement either. It resolves the two into the three lists
// the editor needs to show, and owns the small pure operations that change a
// manager's choices, so the page can be a view and nothing more.
//
// The order the public carousel receives, and therefore the order this must
// produce:
//
//   1. pinned properties, in the order the manager put them
//   2. automatic matches, filling whatever is left
//   3. nothing excluded, ever, however well it scores
//   4. never the property being edited
//   5. no duplicates
//
// Rules 3 to 5 are enforced by applySimilarOverrides rather than repeated
// here, which is why they cannot drift apart from what the website does.

import { applySimilarOverrides } from "../../property/derive.ts";
import findSimilarProperties from "../../property/findSimilar.ts";
import type { PropertyRecord, SimilarPropertyRefs } from "../../property/types";
import type { PropertyDraft } from "./draft";

/** The public carousel's own limit. Not a number invented for the CMS. */
export const MAX_SIMILAR = 6;

export type SimilarResolution = {
  /** Chosen by hand, in the manager's order. */
  pinned: PropertyRecord[];
  /** Chosen by the scoring, filling the remaining places. */
  automatic: PropertyRecord[];
  /** Exactly what the website would show, in order. */
  shown: PropertyRecord[];
  /** Kept out by hand. */
  excluded: PropertyRecord[];
};

/**
 * The draft as the scorer needs to see it.
 *
 * A property being created has no id yet, so it gets one that cannot collide
 * with a real record — which keeps "never suggest yourself" true from the very
 * first keystroke rather than only after the first save.
 */
function asRecord(draft: PropertyDraft): PropertyRecord {
  return {
    id: draft.id ?? "__draft__",
    slug: draft.slug ?? "__draft__",
    title: draft.title ?? "",
    type: draft.type ?? "",
    location: draft.location ?? "",
    imageKey: draft.imageKey ?? "",
    imageAlt: draft.imageAlt ?? "",
    bedrooms: draft.bedrooms ?? 0,
    bathrooms: draft.bathrooms ?? 0,
    area: draft.area ?? 0,
    rent: draft.rent ?? 0,
  };
}

const bySlug = (records: PropertyRecord[], slugs: string[] | undefined) => {
  const index = new Map(records.map((record) => [record.slug, record]));
  return (slugs ?? [])
    .map((slug) => index.get(slug))
    .filter((record): record is PropertyRecord => Boolean(record));
};

/**
 * Everything the Similar Properties step needs to render, and everything the
 * review screen needs to describe.
 *
 * `candidates` excludes the property being edited by both id and slug. The id
 * check is what findSimilarProperties already does; the slug check covers the
 * moment before a new property has an id, where an id comparison would let it
 * suggest itself.
 */
export function resolveSimilar(
  draft: PropertyDraft,
  all: PropertyRecord[],
  limit: number = MAX_SIMILAR
): SimilarResolution {
  const current = asRecord(draft);

  const candidates = all.filter(
    (record) => record.id !== current.id && record.slug !== current.slug
  );

  const automatic = findSimilarProperties(current, candidates, limit);

  const shown = applySimilarOverrides(
    automatic,
    candidates,
    draft.similar,
    limit
  );

  const pinnedSlugs = new Set((draft.similar?.pinned ?? []));

  return {
    pinned: shown.filter((record) => pinnedSlugs.has(record.slug)),
    automatic: shown.filter((record) => !pinnedSlugs.has(record.slug)),
    shown,
    excluded: bySlug(candidates, draft.similar?.excluded),
  };
}

/* ── the manager's adjustments ───────────────────────────────
   Small, total, and returning a fresh object each time, so the wizard can
   treat them like any other draft change and the undo story is the same as
   for typing in a box. */

const without = (list: string[] | undefined, slug: string) =>
  (list ?? []).filter((item) => item !== slug);

const clean = (refs: SimilarPropertyRefs): SimilarPropertyRefs => {
  const next: SimilarPropertyRefs = {};
  if (refs.pinned?.length) next.pinned = refs.pinned;
  if (refs.excluded?.length) next.excluded = refs.excluded;
  return next;
};

/** Pinning something that was excluded un-excludes it: you cannot mean both. */
export function pin(refs: SimilarPropertyRefs | undefined, slug: string): SimilarPropertyRefs {
  const pinned = without(refs?.pinned, slug);

  return clean({
    pinned: [...pinned, slug],
    excluded: without(refs?.excluded, slug),
  });
}

export function unpin(
  refs: SimilarPropertyRefs | undefined,
  slug: string
): SimilarPropertyRefs {
  return clean({ pinned: without(refs?.pinned, slug), excluded: refs?.excluded });
}

/** Excluding something that was pinned unpins it, for the same reason. */
export function exclude(
  refs: SimilarPropertyRefs | undefined,
  slug: string
): SimilarPropertyRefs {
  const excluded = without(refs?.excluded, slug);

  return clean({
    pinned: without(refs?.pinned, slug),
    excluded: [...excluded, slug],
  });
}

export function allowAgain(
  refs: SimilarPropertyRefs | undefined,
  slug: string
): SimilarPropertyRefs {
  return clean({ pinned: refs?.pinned, excluded: without(refs?.excluded, slug) });
}

/**
 * Moves a pinned property one place up or down.
 *
 * The keyboard-reachable equivalent of dragging, and the baseline the dragging
 * is built on rather than an afterthought beside it — an order that can only be
 * changed with a mouse is an order some people cannot change.
 */
export function movePinned(
  refs: SimilarPropertyRefs | undefined,
  slug: string,
  direction: -1 | 1
): SimilarPropertyRefs {
  const pinned = [...(refs?.pinned ?? [])];
  const from = pinned.indexOf(slug);
  if (from === -1) return clean({ pinned, excluded: refs?.excluded });

  const to = from + direction;
  if (to < 0 || to >= pinned.length) return clean({ pinned, excluded: refs?.excluded });

  pinned.splice(to, 0, pinned.splice(from, 1)[0]);
  return clean({ pinned, excluded: refs?.excluded });
}

/** Drops `slug` at `to`, which is what a drag actually means. */
export function reorderPinned(
  refs: SimilarPropertyRefs | undefined,
  slug: string,
  to: number
): SimilarPropertyRefs {
  const pinned = [...(refs?.pinned ?? [])];
  const from = pinned.indexOf(slug);
  if (from === -1 || to < 0 || to >= pinned.length || from === to) {
    return clean({ pinned, excluded: refs?.excluded });
  }

  pinned.splice(to, 0, pinned.splice(from, 1)[0]);
  return clean({ pinned, excluded: refs?.excluded });
}

export const isPinned = (refs: SimilarPropertyRefs | undefined, slug: string) =>
  (refs?.pinned ?? []).includes(slug);

export const isExcluded = (refs: SimilarPropertyRefs | undefined, slug: string) =>
  (refs?.excluded ?? []).includes(slug);
