// Route resolution for the CMS, as a pure function.
//
// Split out of CmsRouter so it can be tested without React, a DOM or a router,
// and so the matching rules are stated in one place rather than inline in a
// component.
//
// The rule the CMS had until now was exact string equality, which meant a view
// could only ever be a single leaf page: /dashboard/leads worked, and anything
// below it fell through to "not installed". A view that owns sub-pages — a set
// of tabs, or a detail page for one record — needs to claim its own subtree.
//
// So: exact match first, unchanged, so no existing route can shift. Only if
// nothing matches exactly does a view get to claim a deeper path, and then only
// at a segment boundary. That boundary is the whole point. A naive startsWith
// would let a view registered at "applications" swallow "applications-archive",
// which is a different view that may not even exist yet.

/** The part of a registration this resolver needs. */
export type RoutableView = {
  path: string;
};

export type ResolvedView<T extends RoutableView> = {
  view: T;
  /**
   * Whatever followed the view's own path, with no leading or trailing slash.
   * Empty for an exact match. The view is handed the full pathname anyway and
   * is free to parse this itself; it is returned because the resolver has
   * already done the work.
   */
  tail: string;
};

/** Strips query, hash and surrounding slashes. */
export function cleanPath(value: string): string {
  return value
    .split("?")[0]
    .split("#")[0]
    .replace(/^\/+|\/+$/g, "");
}

/**
 * Turns a browser pathname into a route relative to the dashboard.
 *
 * Accepts a full pathname ("/dashboard/leads"), a dashboard-prefixed view path
 * ("dashboard/leads") or a bare view path ("leads"), because plugin
 * registrations in this codebase use both of the latter two.
 */
export function toDashboardRoute(value: string): string {
  const clean = cleanPath(value);

  if (clean === "dashboard") return "";
  if (clean.startsWith("dashboard/")) return clean.slice("dashboard/".length);

  return clean;
}

/**
 * Finds the view that owns a route.
 *
 * Exact matches win outright. Failing that, the longest view path that is a
 * whole-segment prefix of the route wins, so a more specific view always beats
 * a more general one that happens to share a prefix.
 */
export function resolveCmsView<T extends RoutableView>(
  views: T[],
  pathname: string
): ResolvedView<T> | null {
  const relative = toDashboardRoute(pathname);

  for (const view of views) {
    if (toDashboardRoute(view.path) === relative) {
      return { view, tail: "" };
    }
  }

  // No exact owner. Offer the route to any view that owns the subtree above it.
  let best: ResolvedView<T> | null = null;
  let bestLength = -1;

  for (const view of views) {
    const base = toDashboardRoute(view.path);

    // An empty base would match everything, which is the dashboard root's job,
    // not a view's.
    if (!base) continue;

    // The trailing slash is what makes this segment-aware: "applications" can
    // claim "applications/builder" but never "applications-archive".
    if (!relative.startsWith(`${base}/`)) continue;

    if (base.length > bestLength) {
      bestLength = base.length;
      best = { view, tail: relative.slice(base.length + 1) };
    }
  }

  return best;
}
