// Deleted leads, and how long is left to change your mind (MTC-KRP-041).
//
// The same shape as the Properties CMS's Trash, deliberately: a short line
// explaining the window, then one row per item with the days remaining and a
// Restore. Somebody who has used one Trash in this CMS has used all three.

import React from "react";
import { LuTrash2 } from "react-icons/lu";

import LeadAvatar from "./LeadAvatar";
import { TRASH_DAYS, daysRemaining, trashedLeadsNewestFirst } from "./leadRules";
import { formatAbsolute } from "./format";
import template from "../../config/gh-leads--template";
import type { Lead } from "./types";

const labels = template.labels;

type Props = {
  leads: Lead[];
  /** Null until the clock has started on the client; see useNow. */
  now: number | null;
  busy: boolean;
  onRestore: (id: string) => void;
  onOpenLead: (lead: Lead) => void;
};

export default function LeadsTrashTab({
  leads,
  now,
  busy,
  onRestore,
  onOpenLead,
}: Props) {
  /* Newest first — the thing you just deleted is the thing you want back. */
  const rows = now === null ? [] : trashedLeadsNewestFirst(leads, now);

  if (rows.length === 0) {
    return (
      <div className="leads-empty">
        <span className="leads-empty__icon" aria-hidden="true">
          <LuTrash2 size={20} />
        </span>
        <h2 className="leads-empty__title">{labels.trashEmptyTitle}</h2>
        <p className="leads-empty__text">{labels.trashEmptyText}</p>
      </div>
    );
  }

  return (
    <div className="leads-trash">
      <p className="leads-trash__note">
        {labels.trashNote(TRASH_DAYS)}
      </p>

      <ul className="leads-trash__list">
        {rows.map((lead) => {
          /* `now` is non-null here: rows is empty when it is not. */
          const left = daysRemaining(lead.deletedAt as string, now as number);

          return (
            <li className="leads-trash__item" key={lead.id}>
              <LeadAvatar name={lead.name} />

              <button
                type="button"
                className="leads-trash__subject"
                onClick={() => onOpenLead(lead)}
              >
                <span className="leads-trash__name">{lead.name || "Lead"}</span>
                <span className="leads-trash__meta">
                  {lead.email || lead.phone || ""}
                  {lead.receivedAt
                    ? ` · ${formatAbsolute(lead.receivedAt)}`
                    : ""}
                </span>
              </button>

              <span className="leads-trash__countdown">
                {labels.trashCountdown(left)}
              </span>

              <button
                type="button"
                className="leads-detail__btn"
                onClick={() => onRestore(lead.id)}
                disabled={busy}
              >
                {labels.restore}
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
