// Where the Properties CMS actually reads and writes.
//
// The screens above this file read the catalogue SYNCHRONOUSLY — `catalogue`
// is a useMemo, and the card list, the Trash countdowns and the wizard's
// starting draft are all computed during render. Supabase is not synchronous.
// Rather than make every one of those async, this module keeps the catalogue
// in memory and fills it once, when the CMS mounts:
//
//   hydrateProperties()   async, once. Fetches the document.
//   savedProperties()     sync, any time. Reads what was fetched.
//   writeProperties()     async. Writes, and updates the cache ONLY if the
//                         write actually succeeded.
//
// That last line is the whole point. A cache updated before the network call
// returns would show the property as saved whether or not it was, which is
// precisely the failure Nate ruled out at the start of this workflow.
//
// In demo mode none of this applies: the functions pass straight through to
// localStorage, which really is synchronous, and hydrate does nothing.

import { properties as samples } from "../../../primitives/property/property-data.ts";
import type { PropertyRecord } from "../../property/types";
import type { WriteResult } from "../../shared/localStore";
import {
  loadPropertiesDocument,
  loadVersionedProperties,
  savePropertiesIfUnchanged,
} from "../../supabase/propertiesSupabase.ts";
import { usingSupabase } from "../../supabase/enabled.ts";
import { loadSavedProperties, saveProperty as saveLocalProperty } from "./propertiesStore.ts";
import type { SavedProperties } from "./propertiesStore";
import type { PropertyDraft } from "./draft";
import { mergeProperties } from "./propertiesStore.ts";
import { catalogueRecords } from "../../property/catalogueRules.ts";

/**
 * The catalogue as Supabase last told us it was.
 *
 * `null` has a specific meaning and is not the same as an empty array: it
 * means this browser has not fetched yet, OR the site has never saved a
 * catalogue. Both fall back to the bundled samples. An EMPTY array means
 * somebody deleted every property, and must not be quietly repopulated.
 */
let cache: PropertyRecord[] | null = null;

/**
 * The version the cache was read at, or null if the document did not exist.
 *
 * Every write is conditional on this. Without it, saving meant overwriting
 * the whole catalogue with a merge onto whatever this browser happened to
 * have fetched when the CMS was opened - so if somebody else added a property
 * in the meantime, theirs disappeared. That is not a theoretical race: the
 * window is however long the tab has been open.
 */
let cacheVersion: string | null = null;

/** True once a fetch has completed, whatever it found. */
let hydrated = false;

export type HydrateResult = { ok: true } | { ok: false; reason: string };

/**
 * Fetches the catalogue. Called once when the Properties CMS mounts.
 *
 * A failure is returned rather than thrown, and the caller shows it. The CMS
 * still opens — on the bundled samples — because a property manager who
 * cannot reach the database should still see the site they manage, as long as
 * they are told that what they are looking at is not live.
 */
export async function hydrateProperties(): Promise<HydrateResult> {
  if (!usingSupabase()) {
    hydrated = true;
    return { ok: true };
  }

  const result = await loadVersionedProperties();

  if (!result.ok) return { ok: false, reason: result.error.message };

  cache = result.data.properties;
  cacheVersion = result.data.updatedAt;
  hydrated = true;
  return { ok: true };
}

/** Whether a fetch has finished, so a screen can wait rather than flash. */
export const propertiesHydrated = (): boolean => !usingSupabase() || hydrated;

/** Full remote documents are authoritative, including an intentionally empty list. */
export function currentProperties(): PropertyRecord[] {
  return usingSupabase()
    ? catalogueRecords(cache, samples)
    : mergeProperties(samples, loadSavedProperties());
}

/**
 * The saved records, keyed by slug, in the shape `mergeProperties` expects.
 *
 * Deliberately identical between the two backends, so PropertiesView calls
 * `mergeProperties(records, savedProperties())` and never learns which one it
 * is talking to.
 */
export function savedProperties(): SavedProperties {
  if (!usingSupabase()) return loadSavedProperties();
  if (!cache) return {};

  const out: SavedProperties = {};
  for (const record of cache) {
    if (record?.slug) out[record.slug] = record as PropertyDraft;
  }
  return out;
}

/**
 * The full catalogue that would result from applying these records.
 *
 * Built on the fetched document where there is one and on the bundled samples
 * where there is not — the first ever save has to write a complete catalogue,
 * or it would store one property and silently drop the other twelve.
 *
 * A Map keyed by slug does the merge: replacing a record keeps its original
 * position, and a new one is appended. The list must not reorder itself under
 * somebody between visits.
 */
function catalogueWith(records: PropertyRecord[]): PropertyRecord[] {
  const base = cache ?? samples;
  const bySlug = new Map(base.map((record) => [record.slug, record]));

  for (const record of records) bySlug.set(record.slug, record);

  return [...bySlug.values()];
}

/**
 * Writes one or more properties.
 *
 * Takes a list rather than a single record because deleting four properties
 * should be ONE write, not four — four sequential read-modify-writes of the
 * same document is both slower and a chance for the third to fail after the
 * second succeeded.
 */
export async function writeProperties(
  records: PropertyDraft[]
): Promise<WriteResult> {
  if (!usingSupabase()) {
    for (const record of records) {
      const outcome = saveLocalProperty(record);
      if (!outcome.ok) return outcome;
    }
    return { ok: true };
  }

  const unaddressed = records.find((record) => !record.slug);
  if (unaddressed) {
    return { ok: false, reason: "This property has no web address yet." };
  }

  /* Re-read, merge onto THAT, and write only over the version just read.
     Three attempts, because each losing attempt means somebody else's save
     landed first - and that is a thing that happens twice in a row far less
     often than once.

     Merging onto a fresh read rather than onto the cache is what makes the
     retry meaningful: the records being written are re-applied over their
     work, not instead of it. */
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const fresh = await loadVersionedProperties();
    if (!fresh.ok) return { ok: false, reason: fresh.error.message };

    cache = fresh.data.properties;
    cacheVersion = fresh.data.updatedAt;

    const next = catalogueWith(records as PropertyRecord[]);
    const result = await savePropertiesIfUnchanged(next, cacheVersion);

    if (!result.ok) return { ok: false, reason: result.error.message };

    if (result.data.applied) {
      /* Only now. Before the write returned, this would have been a guess.
         The version is deliberately NOT guessed either - the next write
         re-reads it, because the trigger sets it and only the database knows
         what it became. */
      cache = next;
      cacheVersion = null;
      return { ok: true };
    }
  }

  /* Three conflicts in a row is not somebody else being quick; it is
     something wrong. Said plainly, and nothing was saved. */
  return {
    ok: false,
    reason:
      "Somebody else is saving at the same time, so this could not be stored. Nothing was lost - try again in a moment.",
  };
}

/** Convenience for the wizard, which saves exactly one property at a time. */
export const writeProperty = (record: PropertyDraft): Promise<WriteResult> =>
  writeProperties([record]);

/** Test seam. Nothing in the app calls this. */
export function resetPropertiesCache(): void {
  cache = null;
  cacheVersion = null;
  hydrated = false;
}
