import type { PropertyRecord } from "./types";

/** City is the part of "Eagle, Idaho" a buyer actually shops by. */
const city = (location: string) => location.split(",")[0].trim().toLowerCase();

/**
 * Scores how well `candidate` matches `current`.
 *
 * Weighted by what a renter is actually choosing on: where it is first, then
 * what kind of home it is, then how big, then what it costs. A property in the
 * same city but a different size beats a same-size property an hour away.
 */
function score(current: PropertyRecord, candidate: PropertyRecord): number {
  let total = 0;

  if (city(candidate.location) === city(current.location)) total += 4;
  if (candidate.type === current.type) total += 3;

  const bedroomGap = Math.abs(candidate.bedrooms - current.bedrooms);
  if (bedroomGap === 0) total += 3;
  else if (bedroomGap === 1) total += 1;

  if (current.rent > 0) {
    const drift = Math.abs(candidate.rent - current.rent) / current.rent;
    if (drift <= 0.15) total += 2;
    else if (drift <= 0.3) total += 1;
  }

  return total;
}

/**
 * Properties a visitor viewing `current` might also consider.
 *
 * Always excludes the current property by id — never by title, which two
 * properties could plausibly share. Where too few genuine matches exist the
 * list is topped up with other available properties rather than left short,
 * because an almost-empty carousel looks broken; the top-ups still cannot
 * introduce a duplicate or the current property.
 */
export function findSimilarProperties(
  current: PropertyRecord,
  all: PropertyRecord[],
  limit = 6
): PropertyRecord[] {
  const others = all.filter((item) => item.id !== current.id);

  const ranked = others
    .map((item) => ({ item, value: score(current, item) }))
    .sort((a, b) => b.value - a.value);

  const matched = ranked.filter((entry) => entry.value > 0).map((entry) => entry.item);

  if (matched.length >= limit) return matched.slice(0, limit);

  // Top up, skipping anything already included.
  const chosen = new Set(matched.map((item) => item.id));
  const filler = others.filter((item) => !chosen.has(item.id));

  return [...matched, ...filler].slice(0, limit);
}

export default findSimilarProperties;
