import React, { useState } from "react";
import { LuArrowLeft, LuChevronRight, LuInfo, LuPlay } from "react-icons/lu";

/**
 * Help.
 *
 * A chooser rather than a manual: seven topics expanded at once was more
 * reading than the whole feature needs, and buried whichever one the reader
 * actually came for. Pick a topic, get its steps, go back.
 *
 * Topics and their steps are data. MTC-KRP-018 adds guided walkthroughs, and
 * this is shaped so it can — each topic already has a stable `id` and an
 * ordered list of steps, and the chooser row is the natural place to launch
 * one from. Nothing here anticipates that further: no overlay, no spotlight,
 * no animation, and no dependency for one.
 */
export type HelpTopic = {
  id: string;
  title: string;
  summary: string;
  steps: string[];
};

