export type HelpTabProps = {
  /** Starts a guided walkthrough. Supplied by the view, which owns the overlay. */
  onStartTutorial: (id: string) => void;
  /** Why a walkthrough cannot run yet, keyed by topic id. */
  unavailable: Record<string, string | null>;
};

export default function HelpTab({ onStartTutorial, unavailable }: HelpTabProps) {
  const [openId, setOpenId] = useState<string | null>(null);
  const open = helpTopics.find((topic) => topic.id === openId) ?? null;
  const blocked = open ? unavailable[open.id] : null;

  if (open) {
    return (
      <div>
        <button
          type="button"
          className="kr-apply-cms__btn"
          style={{ marginBottom: 18 }}
          onClick={() => setOpenId(null)}
        >
          <LuArrowLeft size={14} /> All Help Topics
        </button>

        <div className="kr-apply-cms__card" style={{ padding: "24px 26px" }}>
          <h2 className="kr-apply-cms__section-title" style={{ fontSize: 18 }}>
            {open.title}
          </h2>
          <p className="kr-apply-cms__hint" style={{ margin: "6px 0 20px" }}>
            {open.summary}
          </p>

          <ol className="kr-apply-cms__steps">
            {open.steps.map((step) => (
              <li key={step}>{step}</li>
            ))}
          </ol>

          {/* The walkthrough does the same thing on the real screen. Said in
              those words, because "start walkthrough" alone does not tell
              somebody they are about to be guided through the actual CMS. */}
          {blocked ? (
            <p className="kr-apply-cms__note kr-tut__start">
              <LuInfo size={15} className="kr-apply-cms__note-icon" aria-hidden="true" />
              <span>{blocked}</span>
            </p>
          ) : (
            <div className="kr-tut__start">
              <button
                type="button"
                className="kr-apply-cms__btn kr-apply-cms__btn--primary"
                onClick={() => onStartTutorial(open.id)}
              >
                <LuPlay size={14} aria-hidden="true" /> Show Me on the Screen
              </button>
              <p className="kr-apply-cms__hint" style={{ marginTop: 8 }}>
                Walks you through the real Application Builder, one step at a time.
              </p>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 className="kr-apply-cms__section-title" style={{ marginBottom: 4 }}>
        What would you like help with?
      </h2>
      <p className="kr-apply-cms__hint" style={{ margin: "0 0 18px" }}>
        Choose a topic for step-by-step instructions.
      </p>

      <div className="kr-apply-cms__card kr-apply-cms__topics">
        {helpTopics.map((topic) => (
          <button
            type="button"
            className="kr-apply-cms__topic"
            key={topic.id}
            onClick={() => setOpenId(topic.id)}
          >
            <span className="kr-apply-cms__topic-main">
              <span className="kr-apply-cms__topic-title" style={{ display: "block" }}>
                {topic.title}
              </span>
              <span
                className="kr-apply-cms__topic-summary"
                style={{ display: "block" }}
              >
                {topic.summary}
              </span>
            </span>
            <LuChevronRight size={17} className="kr-apply-cms__topic-arrow" />
          </button>
        ))}
      </div>
    </div>
  );
}
