import React from "react";

import BasicsStep from "./steps/BasicsStep";
import ContentStep from "./steps/ContentStep";
import ImagesStep from "./steps/ImagesStep";
import ReviewStep from "./steps/ReviewStep";
import SimilarStep from "./steps/SimilarStep";
import type { StepProps } from "./steps/types";

/**
 * Which step is showing.
 *
 * A lookup and nothing else. The steps themselves are five separate files
 * because they are five separate screens, and one component holding all of
 * them would be the first thing anybody working on this ticket had to scroll
 * past.
 */
const STEPS: Record<string, React.ComponentType<StepProps>> = {
  basics: BasicsStep,
  content: ContentStep,
  images: ImagesStep,
  similar: SimilarStep,
  review: ReviewStep,
};

export function WizardStepContent({
  stepId,
  ...props
}: StepProps & { stepId: string }) {
  const Step = STEPS[stepId] ?? BasicsStep;
  return <Step {...props} />;
}

export default WizardStepContent;
