import React from "react";
import { LuCheck, LuGlobe, LuEyeOff, LuTriangleAlert } from "react-icons/lu";

import { canPublish, publishBlockers } from "./validation";
import type { PropertyDraft, SaveIntent } from "./draft";

export type PublicationBarProps = {
  draft: PropertyDraft;
  saving: SaveIntent | null;
  saveError: string | null;
  savedAt: SaveIntent | null;
  onSave: (intent: SaveIntent) => void;
};

/**
 * The property-level publication status strip.
 *
 * Placed between the breadcrumb bar and the wizard layout so it reads as
 * belonging to the whole property, not to any individual step. Compact by
 * design — it answers two questions at a glance:
 *
 *   1. Is this property published right now?
 *   2. Can I change that from here?
 *
 * It does NOT replace the Review & Publish step. Both exist and both show the
 * same canonical state, because they read from the same draft.publication
 * field.
 *
 * Publish path: calls onSave("publish") — the same function Step 5 uses,
 * subject to the same canPublish() validation gate.
 *
 * Unpublish path: calls onSave("unpublish") — sets publication back to
 * "draft" through the same save API. No data is deleted or reset.
 *
 * MTC-KRP-032 baseline: because onSave() calls setSaved(next) on success, a
 * successful publish/unpublish here advances the clean baseline exactly as it
 * does from Step 5. The leave-warning will not fire for the change that was
 * just persisted.
 */
export default function PublicationBar({
  draft,
  saving,
  saveError,
  savedAt,
  onSave,
}: PublicationBarProps) {
  const published = draft.publication === "published";
  const ready = canPublish(draft);
  const blockers = publishBlockers(draft);

  /* Only shown for the last interaction that involved THIS bar.
     saveError and savedAt are reset to null by the wizard whenever onSave is
     called, so stale messages from Step 5 never bleed into this strip. */
  const isBusy = saving !== null;

  return (
    <div
      className={`kr-pub-bar${published ? " kr-pub-bar--published" : " kr-pub-bar--draft"}`}
      role="region"
      aria-label="Publication status"
    >
      {/* ── left: status indicator ───────────────────────── */}
      <div className="kr-pub-bar__status">
        <span className="kr-pub-bar__icon" aria-hidden="true">
          {published ? <LuGlobe size={15} /> : <LuEyeOff size={15} />}
        </span>

        <span className="kr-pub-bar__label">
          {published ? "Published" : "Unpublished"}
        </span>

        <span className="kr-pub-bar__detail">
          {published
            ? "This property is visible on the website."
            : "This property is not visible on the website."}
        </span>
      </div>

      {/* ── right: action ────────────────────────────────── */}
      <div className="kr-pub-bar__actions" data-tutorial="publish-actions">
        {/* Inline feedback — tight to the button, not a separate banner */}
        {saveError && (saving === null) ? (
          <span className="kr-pub-bar__feedback kr-pub-bar__feedback--error" role="alert">
            <LuTriangleAlert size={13} aria-hidden="true" />
            {saveError}
          </span>
        ) : null}

        {savedAt && !saveError && (saving === null) ? (
          <span className="kr-pub-bar__feedback kr-pub-bar__feedback--ok" role="status">
            <LuCheck size={13} aria-hidden="true" />
            {savedAt === "publish" ? "Published." : savedAt === "unpublish" ? "Unpublished." : "Saved."}
          </span>
        ) : null}

        {published ? (
          /* Unpublish — always available for a published property, no validation needed */
          <button
            type="button"
            className="kr-props__btn"
            disabled={isBusy}
            onClick={() => onSave("unpublish")}
          >
            <LuEyeOff size={14} aria-hidden="true" />
            {saving === "unpublish" ? "Unpublishing…" : "Unpublish"}
          </button>
        ) : (
          /* Publish — gated by the same canPublish() check as Step 5 */
          <button
            type="button"
            className="kr-props__btn kr-props__btn--primary"
            /* Disabled when the property is not publishable, matching Step 5.
               `save()` checks again regardless — this is the affordance, not
               the gate, and the two must not be confused. */
            disabled={isBusy || !ready}
            aria-describedby={!ready ? "kr-pub-bar-blockers" : undefined}
            onClick={() => onSave("publish")}
          >
            <LuGlobe size={14} aria-hidden="true" />
            {saving === "publish" ? "Publishing…" : "Publish"}
          </button>
        )}
      </div>

      {/* Validation message — shown only when trying to publish an incomplete property */}
      {!published && !ready ? (
        <p className="kr-pub-bar__blockers" id="kr-pub-bar-blockers">
          {blockers.length === 1
            ? `1 required field is missing — go to Review & Publish for details.`
            : `${blockers.length} required fields are missing — go to Review & Publish for details.`}
        </p>
      ) : null}
    </div>
  );
}
