import React from "react";
import { LuRotateCcw, LuTrash2 } from "react-icons/lu";

import {
  daysRemaining,
  restoreApplication,
  trashedApplications,
} from "./applicationRules";
import type { ApplicationsDocument } from "./types";

export type TrashTabProps = {
  doc: ApplicationsDocument;
  onChange: (next: ApplicationsDocument, description: string) => void;
  saving: boolean;
  /** Passed in so the list and the countdown agree, and so tests can fix it. */
  now: number;
};

const dateFormat = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

/**
 * Trash.
 *
 * The countdown is derived from each record's `deletedAt` every render rather
 * than stored, so it is right whenever the CMS is opened. Worth being precise
 * about what this does and does not do: an expired application stops being
 * listed and stops being restorable, but nothing here removes it from the
 * stored document. Actually purging the data is a scheduled job against the
 * repository, and pretending a React render does it would be a lie about where
 * the data lives.
 */
export default function TrashTab({ doc, onChange, saving, now }: TrashTabProps) {
  const trashed = trashedApplications(doc, now);

  if (trashed.length === 0) {
    return (
      <div className="kr-apply-cms__card">
        <div className="kr-apply-cms__empty">
          <span className="kr-apply-cms__empty-icon" aria-hidden="true">
            <LuTrash2 size={20} />
          </span>
          <p className="kr-apply-cms__empty-title">Trash is empty</p>
          <p className="kr-apply-cms__empty-text">
            Deleted applications remain here for 30 days.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="kr-apply-cms__card">
      <table className="kr-apply-cms__table">
        <thead>
          <tr>
            <th scope="col">Application</th>
            <th scope="col">Deleted</th>
            <th scope="col">Remaining</th>
            <th scope="col">
              <span className="kr-sr-only">Actions</span>
            </th>
          </tr>
        </thead>
        <tbody>
          {trashed.map((application) => {
            const days = daysRemaining(application.deletedAt as string, now);

            return (
              <tr key={application.id}>
                <td data-label="Application">
                  <strong>{application.name}</strong>
                  <div style={{ opacity: 0.6, fontSize: 12, marginTop: 2 }}>
                    {application.questions.length}{" "}
                    {application.questions.length === 1 ? "question" : "questions"}
                  </div>
                </td>
                <td data-label="Deleted">
                  {dateFormat.format(Date.parse(application.deletedAt as string))}
                </td>
                <td data-label="Remaining">
                  {days} {days === 1 ? "day" : "days"}
                </td>
                <td style={{ textAlign: "right" }}>
                  <button
                    type="button"
                    className="kr-apply-cms__btn"
                    data-tutorial={
                      trashed[0].id === application.id
                        ? "restore-application"
                        : undefined
                    }
                    disabled={saving}
                    onClick={() =>
                      onChange(
                        restoreApplication(doc, application.id, now),
                        `"${application.name}" restored`
                      )
                    }
                  >
                    <LuRotateCcw size={14} /> Restore
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
