import React, { useEffect, useState } from "react";
import { Link } from "gatsby";
import { LuArrowRight, LuClipboardList } from "react-icons/lu";

import theme from "../../config/opencms--theme";
import { activeApplication, liveApplications } from "./applicationRules";
import { applicationsApi } from "./applicationsApi";
import { dashCard } from "./dashboardCardStyles";
import { APPLY_ROUTE } from "./types";
import type { ApplicationsDocument } from "./types";

/**
 * The PVST Preview — the Application Builder's card on the CMS dashboard.
 *
 * Not to be confused with previewing an application: this is the plugin's own
 * sneak peek, showing which application is live and how much there is.
 *
 * Self-loading rather than fed, because PluginSlot renders slot components with
 * no props at all. Styled from the shared dashboard card rules so it sits at the
 * same rhythm as Images and Leads; width and outer spacing belong to the
 * dashboard grid, not to this file.
 */
export default function ApplyPreview() {
  const [doc, setDoc] = useState<ApplicationsDocument | null>(null);
  const [state, setState] = useState<"loading" | "ready" | "failed">("loading");

  useEffect(() => {
    let cancelled = false;

    applicationsApi
      .load()
      .then((result) => {
        if (cancelled) return;
        setDoc(result.doc);
        setState("ready");
      })
      .catch(() => {
        if (!cancelled) setState("failed");
      });

    return () => {
      cancelled = true;
    };
  }, []);

  const header = (
    <div style={dashCard.header}>
      <div style={dashCard.headingWrap}>
        <span style={dashCard.icon}>
          <LuClipboardList size={19} />
        </span>
        <div style={{ minWidth: 0 }}>
          <h2 style={dashCard.title}>Application Builder</h2>
          <p style={dashCard.subtitle}>The form applicants fill in.</p>
        </div>
      </div>

      <Link to={APPLY_ROUTE} style={dashCard.action}>
        Open
        <LuArrowRight size={14} aria-hidden="true" />
      </Link>
    </div>
  );

  if (state === "loading" || state === "failed" || !doc) {
    return (
      <div style={dashCard.card}>
        {header}
        <div style={dashCard.body}>
          <p style={{ margin: 0, color: theme.textMuted, fontSize: 13 }}>
            {state === "failed"
              ? "Applications could not be loaded right now."
              : "Loading…"}
          </p>
        </div>
      </div>
    );
  }

  const active = activeApplication(doc);
  const total = liveApplications(doc).length;

  return (
    <div style={dashCard.card}>
      {header}

      <div style={dashCard.body}>
        <p style={dashCard.eyebrow}>Active Application</p>
        <p style={dashCard.lead}>{active ? active.name : "None"}</p>
        {/* Only counts that are real. Applicant numbers stay out until the
            submissions pipeline is provisioned — a zero would read as "nobody
            has applied" rather than "this is not connected". */}
        <p style={dashCard.meta}>
          {total} {total === 1 ? "application" : "applications"}
        </p>
      </div>
    </div>
  );
}
