// Soft deletion for properties.
//
// Deliberately the same model the Application Builder has used since
// MTC-KRP-017: a record is deleted by gaining a `deletedAt` timestamp, not by
// being removed. Nate's wording for this ticket — "deletions are final but can
// be recovered for 30 days in the trash" — is exactly that behaviour, and
// building a second mechanism for it would mean two Trashes with two rules.
//
// What deletion does NOT do, and this is the point of the model: it does not
// touch one other field. The content, the images, the floor plans, the
// amenities, the similar-property choices and the publication state are all
// still there, because a property in the Trash is the property, waiting. That
// is what makes Restore honest — it returns the record rather than rebuilding
// something that resembles it.
//
// No React, no DOM, no storage: these are the rules, so they are testable on
// their own and the view renders decisions rather than making them.

import type { PropertyRecord } from "../property/types";

/** Matches the Application Builder. One number, one meaning, site-wide. */
export const TRASH_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

/** A property nobody has deleted. Absent `deletedAt` is the normal state. */
export const isLive = (property: { deletedAt?: string | null }): boolean =>
  !property.deletedAt;

export function liveProperties<T extends { deletedAt?: string | null }>(
  properties: T[]
): T[] {
  return properties.filter(isLive);
}

/**
 * How long a deleted property has left.
 *
 * Derived from `deletedAt` on every read rather than stored and counted down,
 * so it is correct whenever the CMS is opened rather than correct only if
 * something kept ticking.
 */
export function daysRemaining(deletedAt: string, now: number): number {
  const elapsed = now - new Date(deletedAt).getTime();
  return Math.max(0, TRASH_DAYS - Math.floor(elapsed / DAY_MS));
}

export function isExpired(deletedAt: string, now: number): boolean {
  return daysRemaining(deletedAt, now) <= 0;
}

/**
 * What the Trash shows: deleted, and still inside its window.
 *
 * An expired property stops being listed and stops being restorable. It is NOT
 * removed from storage here — purging is a separate act against the stored
 * document, and pretending a render does it would be a lie about where the
 * data lives. The Application Builder's Trash says the same thing for the same
 * reason.
 */
export function trashedProperties<T extends { deletedAt?: string | null }>(
  properties: T[],
  now: number
): T[] {
  return properties.filter(
    (property) => property.deletedAt && !isExpired(property.deletedAt, now)
  );
}

/** Newest first — the thing you just deleted is the thing you want back. */
export function trashedNewestFirst<T extends { deletedAt?: string | null }>(
  properties: T[],
  now: number
): T[] {
  return [...trashedProperties(properties, now)].sort(
    (a, b) =>
      new Date(b.deletedAt as string).getTime() -
      new Date(a.deletedAt as string).getTime()
  );
}

/**
 * Marks properties deleted.
 *
 * Returns new records; nothing is mutated. Already-deleted properties keep
 * their ORIGINAL timestamp rather than having the clock reset — deleting
 * something twice should not buy it another thirty days.
 */
export function deleteProperties<T extends { slug?: string; deletedAt?: string | null }>(
  properties: T[],
  slugs: string[],
  now: number
): T[] {
  const target = new Set(slugs);
  const stamp = new Date(now).toISOString();

  return properties.map((property) =>
    property.slug && target.has(property.slug) && !property.deletedAt
      ? { ...property, deletedAt: stamp }
      : property
  );
}

/**
 * Brings one property back.
 *
 * Clearing the timestamp is the whole operation, because losing it was the
 * whole deletion. The property returns with its publication state as it was —
 * a published property that was deleted comes back published, which is what
 * "restore" has to mean if the word is to be worth anything.
 */
export function restoreProperty<T extends { slug?: string; deletedAt?: string | null }>(
  properties: T[],
  slug: string
): T[] {
  return properties.map((property) =>
    property.slug === slug ? { ...property, deletedAt: null } : property
  );
}

/**
 * Whether the public website may show this property.
 *
 * Two independent reasons to withhold it, and both have to be checked. A
 * deleted property whose `publication` still reads "published" is the trap
 * this function exists to close: it is in the Trash, the CMS no longer lists
 * it, and nothing about that should leave it on the website.
 */
export function isPubliclyVisible(
  property: { publication?: "published" | "draft"; deletedAt?: string | null }
): boolean {
  return isLive(property) && property.publication !== "draft";
}

/** Convenience for callers holding full records. */
export const livePropertyRecords = (records: PropertyRecord[]): PropertyRecord[] =>
  liveProperties(records);
