import React from "react";
import { FaHome } from "react-icons/fa";
import CmsLayout from "./CmsLayout";
import PluginSlot from "./PluginSlot";
import theme from "../../../config/opencms--theme";

export function DashboardView() {
  return (
    <div className="opencms-dash">
      <style>{css}</style>

      <div style={s.welcomeCard} className="opencms-dash__welcome">
        <div style={s.welcomeIcon}>
          <FaHome size={20} />
        </div>

        <div>
          <h2 style={s.cardTitle}>Welcome to your dashboard</h2>
          <p style={s.cardText}>
  Here’s a quick preview of your business and website, with everything you need to manage it in one place.
</p>
        </div>
      </div>

      <PluginSlot name="dashboard" />
    </div>
  );
}

/**
 * The dashboard owns the layout; the plugins own their content.
 *
 * Each preview used to size and space itself, so they disagreed: three capped
 * at 680px while the newer two ran the full width, and the vertical gaps came
 * from whatever margin each card happened to set. The grid settles all of it in
 * one place, and the reset on its children means a plugin cannot opt out of the
 * layout by accident — a card that hardcodes a width simply fills its cell.
 *
 * Columns are sized rather than counted, so the number of them follows the
 * space available instead of a breakpoint.
 *
 * align-items: start rather than stretch, so a short card stays short instead
 * of being pulled to the height of the tallest in its row. That is as close to
 * masonry as is worth having here: real CSS masonry is still Firefox-only, and
 * the CSS-columns trick that fakes it reorders the cards down each column,
 * which would scramble both the reading order and the tab order.
 */
const css = `
.opencms-dash {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 20px;
  align-items: start;
}

/* Cards fill the cell they are given. */
.opencms-dash > * {
  max-width: none !important;
  margin: 0 !important;
  width: 100%;
  min-width: 0;
}

/* The welcome note is an introduction, not a tile, so it spans the row. */
.opencms-dash__welcome { grid-column: 1 / -1; }

@media (max-width: 720px) {
  .opencms-dash { grid-template-columns: minmax(0, 1fr); gap: 16px; }
}
`;

const OpenCmsDashboard: React.FC = () => (
  <CmsLayout title="Dashboard" pathname="/dashboard">
    <DashboardView />
  </CmsLayout>
);

export default OpenCmsDashboard;

const s: Record<string, React.CSSProperties> = {
  welcomeCard: { maxWidth: 680, padding: theme.cardPadding || 24, borderRadius: theme.cardRadius || 14, border: `1px solid ${theme.border}`, background: "#fff", display: "flex", alignItems: "center", gap: 16, boxShadow: "0 1px 3px rgba(15,23,42,.04)" },
  welcomeIcon: { width: 46, height: 46, flex: "0 0 46px", borderRadius: 11, background: `${theme.primary}14`, color: theme.primary, display: "flex", alignItems: "center", justifyContent: "center" },
  cardTitle: { margin: 0, color: theme.text, fontSize: 17, fontWeight: 800 },
  cardText: { margin: "6px 0 0", maxWidth: 520, color: theme.textMuted, fontSize: 13, lineHeight: 1.6 },
};
