// Generated by CMS / PPM template loader
// Styling for the OpenCMS Leads plugin. Swap this module (via
// config/template--leads.ts) to restyle Leads without touching a component.
//
// Layering mirrors the gh-image plugin: a class-based stylesheet string for the
// full view (like `ghImageStyles`) and inline style objects for the dashboard
// card (like `dashboardStyles`), both derived from the shared CMS theme.

import type React from "react";
import theme from "../../config/opencms--theme";

export type LeadsTint = { bg: string; fg: string };

/**
 * Presentation copy. Swappable per customer — a client who calls these
 * "Enquiries" changes this block, not a component.
 *
 * Status names are NOT here: they are the domain vocabulary of the LeadStatus
 * union and live beside it in the plugin's types.ts.
 */
export type LeadsLabels = {
  /** Sidebar/nav entry and page heading for the full view. */
  navLabel: string;

  columns: {
    name: string;
    kind: string;
    actions: string;
    phone: string;
    email: string;
    received: string;
    status: string;
  };

  searchPlaceholder: string;
  allStatuses: string;

  loading: string;
  emptyTitle: string;
  emptyText: string;
  noMatchTitle: string;
  noMatchText: string;
  errorTitle: string;
  errorText: string;

  previewTitle: string;
  previewSubtitle: string;
  previewLink: string;
  previewLoading: string;
  previewEmpty: string;
  previewError: string;

  /** Detail popout. */
  popoutMessage: string;
  popoutNoMessage: string;
  popoutDetails: string;
  popoutClose: string;
  popoutFields: {
    name: string;
    email: string;
    phone: string;
    form: string;
    site: string;
    tag: string;
    submissionId: string;
    received: string;
  };

  /* ── tabs, deletion and the full submission view ───────
     MTC-KRP-041 (delete) and MTC-KRP-042 (full view, PDF). */

  tabsLabel: string;
  tabLeads: string;
  tabTrash: string;

  refresh: string;
  refreshing: string;
  delete: string;
  deleting: string;
  cancel: string;
  restore: string;

  /** Written as functions so the count and the window are never hardcoded. */
  confirmTitle: (count: number) => string;
  confirmText: (count: number, days: number) => string;

  trashNote: (days: number) => string;
  trashCountdown: (days: number) => string;
  trashEmptyTitle: string;
  trashEmptyText: string;

  kindApplication: string;
  kindEnquiry: string;

  detailBack: string;
  detailDownload: string;
  detailTrashed: string;
};

export type LeadsTemplate = {
  /** Class-based stylesheet for LeadsView. Injected via <style>. */
  css: string;
  /** Inline styles for the dashboard preview card. */
  preview: Record<string, React.CSSProperties>;
  /**
   * Inline styles for the initials avatar. Inline rather than class-based
   * because LeadAvatar also renders inside the dashboard preview, where the
   * `css` stylesheet above is not mounted.
   */
  avatar: Record<"base" | "lg", React.CSSProperties>;
  /** Avatar tints, picked deterministically from the lead name. */
  avatarPalette: LeadsTint[];
  /** Status badge colours, keyed by Lead["status"]. */
  status: Record<string, LeadsTint & { border: string }>;
  /** How many leads the dashboard preview lists. */
  previewRows: number;
  /** All user-facing copy. */
  labels: LeadsLabels;
};

const labels: LeadsLabels = {
  navLabel: "Leads",

  columns: {
    name: "Lead Name",
    kind: "Type",
    actions: "Quick Actions",
    phone: "Phone",
    email: "Email",
    received: "Received",
    status: "Status",
  },

  searchPlaceholder: "Search name, email or phone",
  allStatuses: "All statuses",

  loading: "Loading leads...",
  emptyTitle: "No leads yet.",
  emptyText: "Leads submitted through your website will appear here.",
  noMatchTitle: "No matching leads",
  noMatchText: "Try a different search term or clear the status filter.",
  errorTitle: "Unable to load leads.",
  errorText: "Please try again shortly.",

  previewTitle: "Recent Leads",
  previewSubtitle: "Enquiries submitted through your website.",
  previewLink: "View All",
  previewLoading: "Loading leads...",
  previewEmpty: "No leads yet.",
  previewError: "Unable to load leads.",

  popoutMessage: "Lead Message",
  popoutNoMessage: "This submission did not include a message.",
  popoutDetails: "Lead Details",
  popoutClose: "Close lead details",
  popoutFields: {
    name: "Name",
    email: "Email",
    phone: "Phone",
    form: "Form",
    site: "Site",
    tag: "Tag",
    submissionId: "Submission ID",
    received: "Received",
  },

  tabsLabel: "Leads sections",
  tabLeads: "Leads",
  tabTrash: "Trash",

  refresh: "Refresh",
  refreshing: "Refreshing...",
  delete: "Delete",
  deleting: "Deleting...",
  cancel: "Cancel",
  restore: "Restore",

  confirmTitle: (count) =>
    count === 1 ? "Delete this lead?" : `Delete ${count} leads?`,

  /* Says what actually happens. "Permanently delete" would be false - the
     lead is recoverable - and "are you sure?" tells somebody nothing they did
     not already know when they clicked. */
  confirmText: (count, days) =>
    `${count === 1 ? "This lead" : `These ${count} leads`} will be removed from ` +
    `your list. Deletions are final, but you can restore ` +
    `${count === 1 ? "it" : "them"} from the Trash for ${days} days.`,

  trashNote: (days) =>
    `Deleted leads stay here for ${days} days, so you can put one back if you ` +
    `change your mind. After that they stop being listed.`,

  trashCountdown: (days) =>
    days === 1 ? "1 day left" : `${days} days left`,

  trashEmptyTitle: "Nothing in the Trash",
  trashEmptyText: "Leads you delete will wait here before they go for good.",

  kindApplication: "Application",
  kindEnquiry: "Enquiry",

  detailBack: "All leads",
  detailDownload: "Download PDF",
  detailTrashed:
    "This lead is in the Trash. Restore it to bring it back to your list.",
};

/* ── status badges ──────────────────────────────────────────────
   Deliberately restrained. "qualified" reuses the exact green of the
   "Authenticated" badge in CmsLayout so the two read as one system. */
const status: LeadsTemplate["status"] = {
  new:       { bg: `${theme.primary}14`, fg: theme.primary, border: `${theme.primary}33` },
  contacted: { bg: "#fffbeb",            fg: "#b45309",     border: "#fde68a" },
  qualified: { bg: "#f0fdf4",            fg: "#15803d",     border: "#bbf7d0" },
};

/* ── avatar tints ───────────────────────────────────────────────
   Low-saturation only: enough variation to scan a column of rows,
   not enough to turn the table into a colour chart. */
const avatarPalette: LeadsTint[] = [
  { bg: "#eff6ff", fg: "#1d4ed8" },
  { bg: "#f1f5f9", fg: "#475569" },
  { bg: "#f0fdfa", fg: "#0f766e" },
  { bg: "#faf5ff", fg: "#7e22ce" },
  { bg: "#fff7ed", fg: "#c2410c" },
  { bg: "#f7fee7", fg: "#4d7c0f" },
];

const css = `
.leads-card {
  border: 1px solid ${theme.border};
  border-radius: ${theme.cardRadius || 14}px;
  background: #fff;
  box-shadow: 0 1px 3px rgba(15,23,42,.04);
  overflow: hidden;
}

/* ── toolbar ─────────────────────────────────────────── */
.leads-toolbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 14px; flex-wrap: wrap;
  padding: 16px 18px;
  border-bottom: 1px solid ${theme.border};
}
.leads-toolbar__left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.leads-toolbar__right { display: flex; align-items: center; gap: 12px; }

.leads-search { position: relative; display: flex; align-items: center; }
.leads-search__icon {
  position: absolute; left: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}
.leads-search__input {
  width: 260px; max-width: 100%;
  box-sizing: border-box;
  padding: 9px 12px 9px 32px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font-size: 13px; font-family: inherit;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.leads-search__input::placeholder { color: ${theme.textMuted}; }
.leads-search__input:focus {
  border-color: ${theme.primary};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}

.leads-filter { position: relative; display: flex; align-items: center; }
.leads-filter__icon {
  position: absolute; left: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}
.leads-filter__select {
  appearance: none; -webkit-appearance: none;
  box-sizing: border-box;
  padding: 9px 30px 9px 32px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font-size: 13px; font-weight: 600; font-family: inherit;
  cursor: pointer; outline: none;
  transition: border-color .15s, box-shadow .15s;
}
.leads-filter__select:focus {
  border-color: ${theme.primary};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}
.leads-filter__caret {
  position: absolute; right: 11px; display: flex;
  color: ${theme.textMuted}; pointer-events: none;
}

.leads-count { color: ${theme.textMuted}; font-size: 12px; white-space: nowrap; }
.leads-count strong { color: ${theme.text}; font-weight: 700; }
.leads-selected {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px; border-radius: 999px;
  background: ${theme.primary}14; color: ${theme.primary};
  font-size: 12px; font-weight: 700; white-space: nowrap;
}

/* ── table ───────────────────────────────────────────── */
.leads-table-wrap { width: 100%; overflow-x: auto; }
.leads-table {
  width: 100%; min-width: 760px;
  border-collapse: collapse; table-layout: fixed;
}
.leads-table th {
  padding: 11px 14px;
  text-align: left;
  background: ${theme.background};
  border-bottom: 1px solid ${theme.border};
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .07em; text-transform: uppercase;
  white-space: nowrap;
}
.leads-table td {
  padding: 11px 14px;
  border-bottom: 1px solid ${theme.border};
  color: ${theme.text};
  font-size: 13px;
  vertical-align: middle;
}
.leads-table tbody tr:last-child td { border-bottom: none; }

.leads-row { cursor: pointer; transition: background .12s; }
.leads-row:hover { background: ${theme.background}; }
.leads-row:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: -2px;
}
.leads-row--selected { background: ${theme.primary}0d; }
.leads-row--selected:hover { background: ${theme.primary}14; }

.leads-truncate {
  display: block;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-muted { color: ${theme.textMuted}; }
.leads-tabular { font-variant-numeric: tabular-nums; }

/* Column sizing. One class per column, set on both the th and the td, so a
   responsive rule can drop a whole column with a single selector. Widths are
   read off the header row under table-layout: fixed. */
.leads-c-check    { width: 42px; }
.leads-c-name     { width: 23%; }
.leads-c-actions  { width: 132px; }
.leads-c-phone    { width: 16%; }
.leads-c-email    { width: 21%; }
.leads-c-received { width: 15%; }
.leads-c-status   { width: 112px; }

/* ── name cell ───────────────────────────────────────── */
.leads-name { display: flex; align-items: center; gap: 10px; min-width: 0; }
.leads-name__text { min-width: 0; }
.leads-name__label { font-weight: 700; color: ${theme.text}; }

/* ── checkbox ────────────────────────────────────────── */
.leads-check {
  width: 15px; height: 15px;
  accent-color: ${theme.primary};
  cursor: pointer;
  display: block;
}

/* ── quick actions ───────────────────────────────────── */
.leads-actions { display: flex; align-items: center; gap: 6px; }
.leads-action {
  width: 27px; height: 27px;
  flex: 0 0 27px;
  padding: 0;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid ${theme.border};
  border-radius: 50%;
  background: #fff;
  color: ${theme.textMuted};
  cursor: pointer;
  text-decoration: none;
  transition: color .12s, border-color .12s, background .12s;
}
.leads-action:hover {
  color: ${theme.primary};
  border-color: ${theme.primary}66;
  background: ${theme.primary}0d;
}
.leads-action:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 1px;
}
.leads-action--done {
  color: #15803d;
  border-color: #bbf7d0;
  background: #f0fdf4;
}

/* ── status badge ────────────────────────────────────── */
.leads-badge {
  display: inline-flex; align-items: center;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 11px; font-weight: 700;
  white-space: nowrap;
}

/* ── empty / loading ─────────────────────────────────── */
.leads-empty {
  display: flex; flex-direction: column; align-items: center;
  gap: 8px; padding: 56px 20px;
  text-align: center;
}
.leads-empty__icon { color: ${theme.border}; }
.leads-empty__title { color: ${theme.text}; font-size: 14px; font-weight: 700; }
.leads-empty__text  { color: ${theme.textMuted}; font-size: 13px; margin: 0; }

.leads-skeleton {
  height: 11px; border-radius: 6px;
  background: ${theme.background};
  animation: leads-pulse 1.3s ease-in-out infinite;
}
@keyframes leads-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }

/* ── detail popout ───────────────────────────────────── */
.leads-popout-overlay {
  position: fixed; inset: 0;
  background: rgba(15,23,42,.55);
  z-index: 10000;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  animation: leads-fade .18s ease-out;
}
.leads-popout {
  background: #fff;
  border-radius: ${theme.cardRadius || 14}px;
  width: 100%; max-width: 940px;
  max-height: calc(100vh - 48px);
  display: flex; flex-direction: column;
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(15,23,42,.28);
  animation: leads-pop .2s ease-out;
}
@keyframes leads-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes leads-pop {
  from { opacity: 0; transform: translateY(8px) scale(.99); }
  to   { opacity: 1; transform: none; }
}

.leads-popout__header {
  display: flex; align-items: center; gap: 14px;
  padding: 16px 20px;
  border-bottom: 1px solid ${theme.border};
  flex-shrink: 0;
}
.leads-popout__heading { min-width: 0; flex: 1; }
.leads-popout__title {
  margin: 0; color: ${theme.text};
  font-size: 16px; font-weight: 800; line-height: 1.25;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-popout__sub {
  margin: 3px 0 0; color: ${theme.textMuted};
  font-size: 12px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-popout__close {
  width: 32px; height: 32px; flex: 0 0 32px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid ${theme.border}; border-radius: 8px;
  background: #fff; color: ${theme.textMuted};
  cursor: pointer;
  transition: color .12s, border-color .12s, background .12s;
}
.leads-popout__close:hover {
  color: ${theme.text}; background: ${theme.background};
}
.leads-popout__close:focus-visible {
  outline: 2px solid ${theme.primary}; outline-offset: 1px;
}

.leads-popout__body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  min-height: 0;
  overflow: hidden;
}
.leads-popout__pane {
  padding: 20px;
  overflow-y: auto;
  min-width: 0;
}
.leads-popout__pane--details {
  border-left: 1px solid ${theme.border};
  background: ${theme.background};
}
.leads-popout__section {
  margin: 0 0 12px;
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .07em; text-transform: uppercase;
}
.leads-popout__message {
  margin: 0;
  color: ${theme.text};
  font-size: 14px; line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.leads-popout__message--empty { color: ${theme.textMuted}; font-style: italic; }

.leads-field { padding: 11px 0; border-top: 1px solid ${theme.border}; }
.leads-field:first-of-type { border-top: none; padding-top: 0; }
.leads-field__label {
  display: block; margin-bottom: 3px;
  color: ${theme.textMuted};
  font-size: 10px; font-weight: 800;
  letter-spacing: .06em; text-transform: uppercase;
}
.leads-field__value {
  display: block; color: ${theme.text};
  font-size: 13px; line-height: 1.5;
  overflow-wrap: anywhere;
}
.leads-field__value a { color: ${theme.primary}; text-decoration: none; }
.leads-field__value a:hover { text-decoration: underline; }
.leads-field__value--muted { color: ${theme.textMuted}; }
.leads-field__value--id { font-size: 12px; font-variant-numeric: tabular-nums; }

@media (max-width: 820px) {
  .leads-popout__body { grid-template-columns: minmax(0, 1fr); }
  .leads-popout__pane--details { border-left: none; border-top: 1px solid ${theme.border}; }
}

/* ── responsive ──────────────────────────────────────── */
@media (max-width: 1180px) {
  .leads-c-phone { display: none; }
  .leads-table { min-width: 620px; }
}
@media (max-width: 900px) {
  .leads-c-received { display: none; }
  .leads-table { min-width: 520px; }
  .leads-search__input { width: 200px; }
}
@media (max-width: 720px) {
  .leads-toolbar { padding: 14px; }
  .leads-toolbar__right { width: 100%; justify-content: space-between; }
}

/* The table keeps a min-width so its remaining columns stay readable, which
   means something has to scroll. Containing it here keeps that scroll inside
   the table rather than making the whole CMS page slide sideways. */
@media (max-width: 900px) {
  .leads-table-wrap,
  .leads-card { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .leads-search__input { width: 100%; min-height: 44px; }
  .leads-toolbar__right { flex-wrap: wrap; gap: 10px; }
}

@media (max-width: 640px) {
  /* Touch targets, and a dialog measured against the visible viewport rather
     than 100vh, which mobile browser chrome makes taller than the screen. */
  .leads-popout { max-height: 88dvh; }
  .leads-row td { padding-top: 14px; padding-bottom: 14px; }
  .leads-popout__close { min-width: 44px; min-height: 44px; }
}

/* == tabs (MTC-KRP-041) ==================================
   The shared CmsTabs strip, styled from here. Same shape as the Properties
   CMS and the Application Builder, so the three read as one product. */
.leads__tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 18px;
  border-bottom: 1px solid ${theme.border};
}
/* Pushed to the far end of the strip, so the tabs stay left and the count
   sits where the eye already goes for "how many". */
.leads__tabs-trailing { margin-left: auto; }
.leads__tab {
  appearance: none;
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  padding: 13px 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  color: ${theme.textMuted};
  cursor: pointer;
  transition: color .15s, border-color .15s;
}
.leads__tab:hover { color: ${theme.text}; }
.leads__tab[aria-selected="true"] {
  color: ${theme.text};
  border-bottom-color: ${theme.primary};
}
.leads__tab:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: -3px;
  border-radius: 4px;
}
.leads__tab-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 11.5px;
  font-weight: 600;
}
.leads__tab[aria-selected="true"] .leads__tab-count {
  background: ${theme.primary}14;
  color: ${theme.text};
}

/* == buttons =============================================
   One button for the whole Leads view: the toolbar, the Trash and the detail
   page all use it, so a Delete looks the same wherever it appears. */
.leads-detail__btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, border-color .15s, color .15s;
}
.leads-detail__btn:hover:not(:disabled) {
  background: ${theme.background};
  border-color: ${theme.textMuted};
}
.leads-detail__btn:focus-visible {
  outline: 2px solid ${theme.primary};
  outline-offset: 3px;
}
.leads-detail__btn:disabled { opacity: .5; cursor: not-allowed; }

/* Destructive: filled red with white text, as MTC-KRP-035 settled for the
   whole CMS. Colour is never the only signal - the word says Delete too. */
.leads-detail__btn--danger {
  background: ${theme.danger};
  border-color: ${theme.danger};
  color: #fff;
}
.leads-detail__btn--danger:hover:not(:disabled) {
  background: #B91C1C;
  border-color: #B91C1C;
  color: #fff;
}

.leads-toolbar__actions { display: flex; align-items: center; gap: 8px; }

/* Turns while a refresh is in flight. The label changes too - the spin alone
   is decoration, the word is what tells somebody it is working. */
@keyframes leads-spin { to { transform: rotate(360deg); } }
.leads-spin { animation: leads-spin 900ms linear infinite; }
@media (prefers-reduced-motion: reduce) {
  .leads-spin { animation: none; }
}

/* == application or enquiry (MTC-KRP-047) ================
   A pill rather than plain text, because this is the column the eye scans to
   find the applications among the questions. Shape and wording carry the
   difference as well as colour - the two tints are deliberately quiet, and a
   reader who cannot tell them apart still reads the word. */
.leads-c-kind { width: 120px; }
.leads-kind {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: .02em;
  white-space: nowrap;
}
.leads-kind--application {
  background: ${theme.primary}14;
  border-color: ${theme.primary}33;
  color: ${theme.text};
}
.leads-kind--enquiry {
  background: ${theme.background};
  border-color: ${theme.border};
  color: ${theme.textMuted};
}

/* A failure the user can act on, never swallowed. */
.leads-problem {
  margin: 0;
  padding: 12px 18px;
  background: ${theme.danger}0F;
  border-bottom: 1px solid ${theme.danger}33;
  color: ${theme.danger};
  font-size: 13px;
  font-weight: 500;
}

/* == selection mode ====================================== */
.leads-row--selectable { cursor: pointer; }
.leads-row--selectable:hover td { background: ${theme.danger}0D; }
.leads-row--selected td {
  background: ${theme.danger}14;
  box-shadow: inset 0 0 0 1px ${theme.danger}55;
}

.leads__toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 10001;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: #fff;
  border: 1px solid ${theme.border};
  border-radius: 11px;
  box-shadow: 0 8px 30px rgba(15,23,42,.14);
  font-size: 13.5px;
  font-weight: 600;
  color: ${theme.text};
}
.leads__toast-icon { display: inline-flex; color: ${theme.primary}; }
.leads__toast-text { white-space: nowrap; }

/* == the confirm ========================================= */
.leads-confirm-overlay {
  position: fixed; inset: 0;
  background: rgba(15,23,42,.55);
  z-index: 10002;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  animation: leads-fade .18s ease-out;
}
.leads-confirm {
  background: #fff;
  border-radius: ${theme.cardRadius || 14}px;
  width: 100%; max-width: 440px;
  padding: 26px;
  box-shadow: 0 20px 60px rgba(15,23,42,.25);
}
.leads-confirm__title {
  margin: 0 0 10px;
  font-size: 18px;
  font-weight: 700;
  color: ${theme.text};
}
.leads-confirm__text {
  margin: 0 0 22px;
  font-size: 14px;
  line-height: 1.6;
  color: ${theme.textMuted};
}
.leads-confirm__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

/* == the Trash =========================================== */
.leads-trash { padding: 18px; }
.leads-trash__note {
  margin: 0 0 16px;
  font-size: 13px;
  line-height: 1.6;
  color: ${theme.textMuted};
}
.leads-trash__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.leads-trash__item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid ${theme.border};
  border-radius: 11px;
  background: #fff;
}
.leads-trash__subject {
  appearance: none;
  background: none;
  border: 0;
  padding: 0;
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  text-align: left;
  font: inherit;
  cursor: pointer;
}
.leads-trash__name {
  font-size: 14px; font-weight: 600; color: ${theme.text};
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-trash__meta {
  font-size: 12.5px; color: ${theme.textMuted};
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.leads-trash__countdown {
  flex: none;
  font-size: 12.5px;
  font-weight: 600;
  color: ${theme.textMuted};
}

/* == one submission, as a page (MTC-KRP-042) ============= */
.leads-detail { display: block; }
.leads-detail__bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.leads-detail__back {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 14px 0 11px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: #fff;
  color: ${theme.text};
  font: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}
.leads-detail__back:hover { background: ${theme.background}; border-color: ${theme.textMuted}; }
.leads-detail__back:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 3px; }
.leads-detail__bar-actions { margin-left: auto; display: flex; gap: 8px; flex-wrap: wrap; }

.leads-detail__sheet {
  background: #fff;
  border: 1px solid ${theme.border};
  border-radius: ${theme.cardRadius || 14}px;
  overflow: hidden;
}
.leads-detail__head {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 24px 26px;
  border-bottom: 1px solid ${theme.border};
}
.leads-detail__title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  color: ${theme.text};
}
.leads-detail__sub {
  margin: 0;
  flex: 1;
  font-size: 13px;
  color: ${theme.textMuted};
}
.leads-detail__trashed {
  margin: 0;
  padding: 12px 26px;
  background: ${theme.background};
  border-bottom: 1px solid ${theme.border};
  font-size: 13px;
  color: ${theme.textMuted};
}

.leads-detail__panes {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  align-items: start;
}
.leads-detail__pane { padding: 24px 26px; min-width: 0; }
.leads-detail__pane--details {
  /* White, like the rest of the sheet. The grey was doing the separating, and
     the border already does that - two signals for one division made the
     column read as a different kind of content rather than the same record
     seen from the side. */
  background: #fff;
  border-left: 1px solid ${theme.border};
  align-self: stretch;
}
.leads-detail__section {
  margin: 0 0 16px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: ${theme.textMuted};
}
.leads-detail__message {
  margin: 0;
  font-size: 14px;
  line-height: 1.7;
  color: ${theme.text};
  white-space: pre-wrap;
}
.leads-detail__message--empty { color: ${theme.textMuted}; font-style: italic; }

/* The answers, one row each, instead of the run-on block the dialog showed. */
.leads-answers { margin: 0; display: grid; gap: 2px; }
.leads-answers__row {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  gap: 16px;
  padding: 11px 0;
  border-bottom: 1px solid ${theme.border};
}
.leads-answers__row:last-child { border-bottom: 0; }
.leads-answers__label {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: ${theme.textMuted};
}
.leads-answers__value {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: ${theme.text};
  overflow-wrap: anywhere;
}

@media (max-width: 900px) {
  .leads-detail__panes { grid-template-columns: minmax(0, 1fr); }
  .leads-detail__pane--details { border-left: 0; border-top: 1px solid ${theme.border}; }
  .leads-answers__row { grid-template-columns: minmax(0, 1fr); gap: 2px; }
}

/* == print, which is how Download PDF works ==============
   Deliberately a print stylesheet rather than a PDF library: this produces
   real selectable text at printer resolution, where a canvas screenshot would
   produce a fuzzy picture nobody can copy an email address out of. */
/* The printed heading. Hidden on screen - the page itself already says all
   of this, far better than a letterhead would. */
.leads-print-head { display: none; }

@media print {
  .leads-no-print { display: none !important; }

  /* The CMS furniture is not part of the document. The sidebar, the header,
     the menu button and the signed-in badge all printed, so the first thing
     on the page was a hamburger icon and the words Content Management
     System. */
  .opencms-sidebar,
  .opencms-header,
  .opencms-menu-button,
  .opencms-auth-badge,
  .opencms-scrim { display: none !important; }

  /* Every one of these paints a grey, and together they put a tint behind the
     whole sheet - which a printer renders as a dull wash over the page and,
     on a colour printer, wastes ink saying nothing. */
  html, body,
  .opencms-content,
  .leads-card,
  .leads-detail,
  .leads-detail__sheet {
    background: #fff !important;
    background-image: none !important;
    box-shadow: none !important;
  }

  /* The shell positions its content beside a sidebar that is no longer there. */
  .opencms-content { margin: 0 !important; padding: 0 !important; }

  .leads-print-head {
    display: block;
    margin: 0 0 18px;
    padding-bottom: 12px;
    border-bottom: 2px solid #111;
  }
  .leads-print-head__business {
    margin: 0;
    font-size: 15pt;
    font-weight: 700;
    color: #000;
  }
  .leads-print-head__kind {
    margin: 2px 0 0;
    font-size: 10.5pt;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: #444;
  }

  .leads-detail__sheet { border: 0; border-radius: 0; }
  .leads-detail__head { padding: 0 0 10px; gap: 8px; }

  /* The shell reserves a full viewport of height and lays out beside a
     sidebar that print has removed. On paper that is a screen of blank space
     before anything starts, and it was pushing the record onto later pages
     by itself. */
  html, body,
  .opencms-page,
  .opencms-content,
  .leads-card,
  .leads-detail,
  .leads-detail__sheet {
    min-height: 0 !important;
    height: auto !important;
    display: block !important;
    margin: 0 !important;
  }

  /* One enquiry is one page. The type scale below is set for paper rather
     than for a screen - a record of a dozen short answers does not need
     14px of body text and 24px of padding to be legible in the hand. */
  @page { margin: 14mm; }

  .leads-detail__title { font-size: 16pt; }
  .leads-detail__sub { font-size: 9pt; }
  .leads-detail__section { margin: 0 0 8px; font-size: 8pt; }
  .leads-answers__row { padding: 5px 0; gap: 10px; }
  .leads-answers__label { font-size: 9pt; }
  .leads-answers__value { font-size: 9.5pt; line-height: 1.35; }
  .leads-field { margin-bottom: 6px; }
  .leads-field__label { font-size: 8pt; }
  .leads-field__value { font-size: 9.5pt; }
  .leads-detail__message { font-size: 9.5pt; line-height: 1.4; }

  /* On paper the two panes run one after the other, and when the submission
     parsed into answers the second is a repeat of what the first already
     shows - name, email, phone - with the date that is in the heading. That
     repeat is what turned one page into three, so it goes.

     ONLY when it is a repeat. A submission that did not parse into answers
     has its contact details nowhere else, and the component says which case
     it is rather than this guessing. */
  .leads-detail__pane--repeat { display: none !important; }
  .leads-detail__panes { grid-template-columns: minmax(0, 1fr); }
  /* No break-inside here. Two panes that each refuse to be split cannot
     share a page, so a one-page record was forced onto three. Only the
     individual answer rows avoid breaking, which is the thing that actually
     looks broken when it splits. */
  .leads-detail__pane { padding: 10px 0; }
  .leads-detail__pane--details { background: none; border-left: 0; border-top: 1px solid #ddd; }

  /* A row split across a page break is the thing that makes a printed form
     look broken, so each answer is kept whole. */
  .leads-answers__row { break-inside: avoid; }

  .leads-detail__title { font-size: 20pt; }
  .leads-answers__value, .leads-detail__message { color: #000; }
  .leads-field__value a { color: #000; text-decoration: none; }
}
`;

