// The contract between this CMS and whatever stores properties.
//
// Nate's instruction was "you decide and I will make the backend to fit what
// you decide", so this file is the decision. It is deliberately types plus
// one builder rather than prose: the payload the frontend sends is defined
// here, it is what `propertyDraftApi.save` actually posts, and it is what the
// tests assert on — so the document and the behaviour cannot drift apart.
//
// The full list of endpoints — every one this site needs, not just this one —
// is in BACKEND.md at the repository root and in src/ppm/contracts/.
//
// Note the endpoint: a property document is saved through the SAME
// POST /api/save-json the Application Builder uses, with
// path "properties/properties.json". An earlier draft of this file specified a
// dedicated /api/property; merging them means one endpoint to build rather
// than two, and the path allow-list is what stops it being a general file
// writer.
//
// Two rules the backend must be able to rely on, because the CMS guarantees
// them before anything is sent:
//
//   1. The payload is a canonical PropertyRecord. Not a wizard shape, not a
//      form submission — the same object the public site reads. There is no
//      translation layer to keep in step.
//
//   2. `publication` is the only thing that decides whether a property is on
//      the website. It is never inferred from availability, and the backend
//      must not infer it either.

import type { PropertyRecord } from "../../property/types";
import type { PropertyDraft, SaveIntent } from "./draft";

/** Bumped if the shape below ever changes incompatibly. */
export const PROPERTY_CONTRACT_VERSION = 1;

/**
 * What gets sent to save a property.
 *
 * `intent` is separate from `property.publication` on purpose. The publication
 * state travels inside the record because that is where it lives
 * canonically; the intent says what the person pressed, which is what the
 * backend should log, rate-limit or require permission for. A backend that
 * only reads one of them still behaves correctly — they never disagree.
 */
export type PropertySavePayload = {
  version: number;
  intent: SaveIntent;
  /**
   * The canonical record.
   *
   * Complete for a publish; possibly partial for a draft, because a draft is
   * by definition unfinished. The backend should store a draft as given and
   * must not fill in defaults of its own — an invented value would appear to
   * the manager as something they typed.
   */
  property: PropertyDraft;
};

export type PropertySaveResponse =
  | {
      ok: true;
      /**
       * The record as stored.
       *
       * Echoed back rather than assumed, so the CMS shows what was actually
       * saved. If the backend assigned an id or adjusted a slug to avoid a
       * collision, this is how the editor finds out.
       */
      property: PropertyRecord;
    }
  | {
      ok: false;
      /**
       * Plain English, shown to a property manager as written.
       *
       * It must not contain a repository name, a commit sha, a bearer token, a
       * worker URL or a JSON path. "Somebody else saved this property while
       * you were editing it" is a message. "409 conflict on refs/heads/main"
       * is not.
       */
      message: string;
      /** Optional machine code for the CMS to branch on. */
      code?: "unauthorised" | "conflict" | "invalid" | "unavailable";
    };

export function buildSavePayload(
  property: PropertyDraft,
  intent: SaveIntent
): PropertySavePayload {
  return { version: PROPERTY_CONTRACT_VERSION, intent, property };
}

/**
 * The fields a property must have before it may be published.
 *
 * Listed here as well as enforced in validation.ts so the backend can reject
 * an incomplete publish independently. A server that trusts the client to have
 * validated is a server that stores whatever a stale tab sends it.
 */
export const REQUIRED_TO_PUBLISH = [
  "title",
  "slug",
  "location",
  "type",
  "bedrooms",
  "bathrooms",
  "area",
  "availability",
  "summary",
] as const;

/**
 * Fields the backend must never accept from this CMS.
 *
 * `photoCount` is derived from the images — it was a hand-typed number that
 * disagreed with reality on most of the bundled listings. The two editing-only
 * fields are stripped by `toRecord`, and their presence in a payload means
 * something bypassed it.
 */
export const REJECTED_FIELDS = ["photoCount", "priceDisplay", "slugLocked"] as const;
