
import { GH_IMAGE_REPO } from "../../config/gh-image--repo";
import { GH_IMAGE_WORKER } from "../../config/gh-image--worker-url";
import { getToken } from "../../config/opencms--useAuth";
import { STATIC_IMAGES } from "../../config/profile--static-images";
import { supabaseImageApi } from "../supabase/images";
import { usingSupabase } from "../supabase/enabled";


const GH_IMAGE_WORKER_UPLOAD_IMAGE = `${GH_IMAGE_WORKER}/api/upload-image`;
const FILES_JSON_URL: string = `${GH_IMAGE_REPO}/images/files.json`;
const GH_IMAGE_WORKER_UPDATE_IMAGE = `${GH_IMAGE_WORKER}/api/update-image`;

// imageApi.ts
// Single source of truth for all gallery images.

export type ImageRecord = {
  id: string;
  path: string;
  name: string;
  isStatic?: boolean;
  meta?: Record<string, any>;
};

export type UploadResult = {
  webpUrl?: string;
  downloadUrl?: string;
  pagesUrl?: string;
  originalPath?: string;
  originalFileName?: string;
};

export type ImageChange =
  | { action: "delete"; id: string }
  | { action: "rename"; id: string; value: string }
  | { action: "update"; id: string; attribute: string; value: any };

export type ImageApiAdapter = {
  fetchFiles: () => Promise<ImageRecord[]>;
  uploadImage: (file: File, onProgress: (msg: string) => void) => Promise<UploadResult>;
  applyChanges: (changes: ImageChange[]) => Promise<void>;
  deleteImage: (id: string) => Promise<void>;
  renameImage: (id: string, newName: string) => Promise<void>;
  updateMeta: (id: string, meta: Record<string, any>) => Promise<void>;
};

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result ?? "");
      resolve(result.split(",")[1]);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function sortByIdDesc(a: ImageRecord, b: ImageRecord): number {
  const aTime = Number(String(a.id).split("-")[0]);
  const bTime = Number(String(b.id).split("-")[0]);
  return bTime - aTime;
}

/**
 * The GitHub + Cloudflare Worker library.
 *
 * Renamed from `imageApi` when Supabase arrived; the name below now picks
 * between the two. Nothing else about this adapter changed.
 */
export const ghImageApi: ImageApiAdapter = {
  async fetchFiles(): Promise<ImageRecord[]> {
    let cmsRecords: ImageRecord[] = [];

    try {
      const res = await fetch(`${FILES_JSON_URL}?v=${Date.now()}`, {
        headers: { Accept: "application/json" },
      });

      if (res.ok) {
        const json = await res.json();
        cmsRecords = Object.entries(json ?? {}).map(([id, value]: [string, any]) => ({
          id,
          path: value?.path ?? "",
          name: value?.name ?? id,
          isStatic: false,
          meta: value?.meta ?? {},
        }));
        cmsRecords.sort(sortByIdDesc);
      }
    } catch {
      // Network failure — fall through and return static images only
    }

    return [...cmsRecords, ...STATIC_IMAGES];
  },

  async uploadImage(file: File, onProgress: (msg: string) => void): Promise<UploadResult> {
    onProgress(`Uploading ${file.name}…`);

    const token = getToken();

    if (!token) {
      throw new Error("No auth token found");
    }

    const now = Date.now();

    const safeOriginalName =
      file.name
        .replace(/[^\w.\-]+/g, "-")
        .replace(/-+/g, "-")
        .replace(/^-|-$/g, "") || `upload-${now}`;

    const storedOriginalName = `${now}-${safeOriginalName}`;
    const originalPath = `originals/${storedOriginalName}`;
    const queuePath = `upload-queue/batch-${now}.json`;

    const queuePayload = {
      uploads: [
        {
          source: originalPath,
          name: file.name,
          meta: {},
        },
      ],
    };

    const base64 = await fileToBase64(file);

    const uploadBody = {
      fileName: file.name,
      base64,
      originalPath,
      queuePath,
      queuePayload,
    };

    console.log("[gh-image upload] endpoint:", GH_IMAGE_WORKER_UPLOAD_IMAGE);
    console.log("[gh-image upload] file:", {
      name: file.name,
      type: file.type,
      size: file.size,
    });
    console.log("[gh-image upload] paths:", {
      originalPath,
      queuePath,
    });
    console.log("[gh-image upload] queuePayload:", queuePayload);
    console.log("[gh-image upload] body preview:", {
      ...uploadBody,
      base64: `[base64 omitted: ${base64.length} chars]`,
    });

    const res = await fetch(GH_IMAGE_WORKER_UPLOAD_IMAGE, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(uploadBody),
    });

    const text = await res.text();

    console.log("[gh-image upload] response:", {
      ok: res.ok,
      status: res.status,
      statusText: res.statusText,
      text,
    });

    if (!res.ok) {
      let json: any = null;
      try {
        json = JSON.parse(text);
      } catch {}

      throw new Error(
        json?.error ??
          text ??
          `Upload failed (HTTP ${res.status})`
      );
    }

    onProgress("Upload success!");

    let json: any = null;
    try {
      json = JSON.parse(text);
    } catch {}

    // The client created the exact GitHub originals/ path, so return it
    // alongside the worker response. No filename reconstruction downstream.
    return {
      ...(json ?? {}),
      originalPath,
      originalFileName: storedOriginalName,
    };
  },

  async applyChanges(changes: ImageChange[]): Promise<void> {
    if (changes.length === 0) return;

    const token = getToken();
    if (!token) throw new Error("No auth token found");

    const res = await fetch(GH_IMAGE_WORKER_UPDATE_IMAGE, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ changes }),
    });

    const text = await res.text();

    if (!res.ok) {
      let json: any = null;
      try {
        json = JSON.parse(text);
      } catch {}

      throw new Error(
        json?.error ??
          json?.githubResponse?.message ??
          json?.githubResponse?.error ??
          text ??
          `Update failed (HTTP ${res.status})`
      );
    }
  },

  async deleteImage(id: string): Promise<void> {
    return ghImageApi.applyChanges([{ action: "delete", id }]);
  },

  async renameImage(id: string, newName: string): Promise<void> {
    return ghImageApi.applyChanges([{ action: "rename", id, value: newName }]);
  },

  async updateMeta(id: string, meta: Record<string, any>): Promise<void> {
    return ghImageApi.applyChanges([
      { action: "update", id, attribute: "meta", value: meta },
    ]);
  },
};


/**
 * The one the CMS uses.
 *
 * Supabase Storage when the project is configured, the GitHub/Worker pipeline
 * otherwise. The picker, the property wizard's image step and the upload
 * notifications all hold this and none of them know which it is.
 */
export const imageApi: ImageApiAdapter = usingSupabase()
  ? supabaseImageApi
  : ghImageApi;
