import React, { useState, useEffect, useRef, useCallback } from "react";
import {
  FaImages, FaTrash, FaExpand, FaUpload, FaCloudUploadAlt,
  FaTimes, FaChevronLeft, FaChevronRight, FaSyncAlt, FaTag,
} from "react-icons/fa";
import { type ImageApiAdapter, type ImageRecord } from "./imageApi";
import { useImageSyncQueue } from "./useImageSyncQueue";
import { createThumbnail } from "./createThumbnail";
import Image from "../../primitives/gh-image/Image";
import { ghImageTheme as theme } from "../../config/gh-image--theme";

// PPM_DECOUPLE


function withAlpha(color: string, alpha: number): string {
  if (color.startsWith("#") && (color.length === 4 || color.length === 7)) {
    const hex = color.length === 4
      ? color.slice(1).split("").map(c => c + c).join("")
      : color.slice(1);
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }
  return color;
}

const C : any = {
  dark: theme.text,
  yellow: theme.primary,
  white: "#ffffff",
  lightGray: theme.background,
  textMuted: theme.textMuted,
  textSub: theme.textMuted,
  border: theme.border,
  dangerBg: withAlpha(theme.danger, 0.10),
  dangerBorder: withAlpha(theme.danger, 0.30),
  dangerText: theme.danger,
};

type Img = {
  id: string;
  src: string;
  name: string;
  isNew?: boolean;
  isStatic?: boolean;
  pendingUrl?: string;
  stage?: "thumbnail" | "raw" | "final";
  meta?: Record<string, any>;
};

// ── Image Card ───────────────────────────────────────────────────────────────
const ImageCard: React.FC<{
  img: Img;
  onView: () => void;
  onDelete: () => void;
  onSeo: () => void;
  onNotFound: () => void;
}> = ({ img, onView, onDelete, onSeo, onNotFound }) => {
  const isThumbnailStage = img.stage === "thumbnail";

  return (
    <div className="grid-item">
      <Image
        src={img.src}
        alt={img.name}
        className="grid-item__img"
        onError={onNotFound}
      />
      {isThumbnailStage && (
        <div className="grid-item__processing" aria-label="Processing image">
          <div className="grid-item__spinner" />
        </div>
      )}
      <div className="grid-item__overlay">
        <div className="grid-item__actions">
          {!isThumbnailStage && (
            <button className="overlay-btn" onClick={onView} title="View full size">
              <FaExpand size={14} />
              <span>View</span>
            </button>
          )}
          {!img.isStatic && (
            <>
              <button className="overlay-btn overlay-btn--seo" onClick={onSeo} title="Edit SEO metadata">
                <FaTag size={13} />
                <span>SEO</span>
              </button>
              <button className="overlay-btn overlay-btn--danger" onClick={onDelete} title="Delete image">
                <FaTrash size={13} />
                <span>Delete</span>
              </button>
            </>
          )}
        </div>
      </div>
      <div className="grid-item__name">
        {img.name}
        {img.isStatic && <span className="grid-item__badge">Built-in</span>}
      </div>
    </div>
  );
};



const getThumbnailAndShowWithSpinner = async (
  file: File,
  tempId: string,
  createThumbnailFn: (file: File) => Promise<string>,
  showThumbnailFn: (
    id: string,
    src: string,
    name: string
  ) => void,
  showSpinnerFn: (id: string) => void
): Promise<string | undefined> => {
  let thumb: string | undefined;

  try {
    thumb = await createThumbnailFn(file);
  } catch {
    return undefined;
  }

  showThumbnailFn(tempId, thumb, file.name);
  showSpinnerFn(tempId);

  return thumb;
};


// ── Images View (rendered at /dashboard/images) ──────────────────────────────
export const ImagesView: React.FC<{
  api: ImageApiAdapter;
}> = ({ api }) => {
  const [images, setImages] = useState<Img[]>([]);
  const [pageLoading, setPageLoading] = useState(true);
  const [pageError, setPageError] = useState("");
  const [errorMsg, setErrorMsg] = useState("");
  const [successMsg, setSuccessMsg] = useState("");
  const [dragging, setDragging] = useState(false);
  const [loadingIds, setLoadingIds] = useState<Set<string>>(new Set());
  const [lightboxIdx, setLightboxIdx] = useState<number | null>(null);
  const [seoTarget, setSeoTarget] = useState<Img | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const {
    queueDelete,
    clearEntry,
    reconcile,
    queueUpload,
    getUploads,
    subscribeQueue,
  } = useImageSyncQueue();

  const sortById = (a: Img, b: Img) => {
    const aTime = Number(String(a.id).split("-")[0]);
    const bTime = Number(String(b.id).split("-")[0]);

    if (isNaN(aTime)) return 1;
    if (isNaN(bTime)) return -1;

    return bTime - aTime;
  };

  const loadImages = async () => {
    setPageLoading(true);
    setPageError("");

    try {
      const records = await api.fetchFiles();

      const imgs: Img[] = records.map(r => ({
        id: r.id,
        src: r.path,
        name: r.name,
        isStatic: r.isStatic,
        meta: r.meta,
      }));

      const { filteredRows } = reconcile(imgs);
      const existingIds = new Set(filteredRows.map(img => img.id));

      const restoredUploads: Img[] = getUploads()
        .filter(upload => !existingIds.has(upload.id))
        .map(upload => ({
          id: upload.id,
          src: upload.currentUrl || upload.thumb || "",
          name: upload.fileName,
          isNew: true,
          pendingUrl:
            upload.stage === "final"
              ? undefined
              : upload.webpUrl,
          stage: upload.stage,
        }))
        .filter(upload => !!upload.src);

      setImages(
        [...restoredUploads, ...filteredRows].sort(sortById)
      );

      setLoadingIds(
        new Set(
          restoredUploads
            .filter(upload => upload.stage === "thumbnail")
            .map(upload => upload.id)
        )
      );
    } catch (err: any) {
      setPageError(err?.message ?? "Failed to load images");
    } finally {
      setPageLoading(false);
    }
  };

  useEffect(() => {
    loadImages();
  }, []);

  useEffect(() => {
    return subscribeQueue(() => {
      const uploads = getUploads();

      setImages(prev => {
        const next = [...prev];

        for (const upload of uploads) {
          const src =
            upload.currentUrl ||
            upload.thumb ||
            "";

          if (!src) {
            continue;
          }

          const index = next.findIndex(
            img => img.id === upload.id
          );

          const stagedImage: Img = {
            id: upload.id,
            src,
            name: upload.fileName,
            isNew: true,
            pendingUrl:
              upload.stage === "final"
                ? undefined
                : upload.webpUrl,
            stage: upload.stage,
          };

          if (index === -1) {
            next.push(stagedImage);
          } else {
            next[index] = {
              ...next[index],
              ...stagedImage,
            };
          }
        }

        return next.sort(sortById);
      });

      setLoadingIds(
        new Set(
          uploads
            .filter(
              upload =>
                upload.stage === "thumbnail"
            )
            .map(upload => upload.id)
        )
      );
    });
  }, []);

  const removeImage = async (id: string) => {
    const img = images.find(i => i.id === id);

    if (!img || img.isStatic) return;
    if (!window.confirm(`Delete "${img.name}"?`)) return;

    queueDelete(id);
    setImages(prev => prev.filter(i => i.id !== id));

    if (lightboxIdx !== null) {
      setLightboxIdx(null);
    }

    try {
      await api.deleteImage(img.id);
    } catch (err: any) {
      clearEntry(id);
      setImages(prev => [img, ...prev].sort(sortById));
      setErrorMsg(err?.message ?? "Delete failed");
    }
  };

  const storedNameFromUrl = (
    webpUrl: string,
    fallback: string
  ): string => {
    const filename = webpUrl
      .split("/")
      .pop()
      ?.split("?")[0];

    return filename || fallback;
  };

  const processFiles = useCallback(
    async (files: FileList | null) => {
      if (!files || files.length === 0) return;

      const imageFiles = Array.from(files).filter(
        file => file.type.startsWith("image/")
      );

      if (imageFiles.length === 0) return;

      const file = imageFiles[0];

      if (imageFiles.length > 1) {
        setSuccessMsg(
          `Uploading "${file.name}" only — one upload at a time.`
        );
      }

      setErrorMsg("");

      const tempId =
        `u-${Date.now()}-${Math.random()}`;

      /*
       * STAGE 1
       *
       * Generate the canvas thumbnail, put that actual thumbnail
       * into the gallery, then mark it as processing.
       */
      const thumb = await getThumbnailAndShowWithSpinner(
        file,
        tempId,
        createThumbnail,

        (id, src, name) => {
          setImages(prev => [
            {
              id,
              src,
              name,
              isNew: true,
            },
            ...prev,
          ]);
        },

        id => {
          setLoadingIds(prev => {
            const next = new Set(prev);
            next.add(id);
            return next;
          });
        }
      );

      /*
       * If canvas thumbnail generation fails, don't leave the user
       * staring into the void. Use the local image as the processing
       * preview while allowing the real upload to continue.
       */
      if (!thumb) {
        const localPreview = URL.createObjectURL(file);

        setImages(prev => [
          {
            id: tempId,
            src: localPreview,
            name: file.name,
            isNew: true,
          },
          ...prev,
        ]);

        setLoadingIds(prev => {
          const next = new Set(prev);
          next.add(tempId);
          return next;
        });
      }

      try {
        const result = await api.uploadImage(
          file,
          () => {}
        );

        if (result.webpUrl) {
          const storedName =
            storedNameFromUrl(
              result.webpUrl,
              file.name
            );

          setImages(prev =>
            prev.map(img =>
              img.id === tempId
                ? {
                    ...img,
                    name: storedName,
                    isNew: true,
                    pendingUrl: result.webpUrl,
                  }
                : img
            )
          );

          queueUpload(tempId, {
            fileName: storedName,
            originalFileName: result.originalFileName ?? file.name,
            webpUrl: result.webpUrl,
            thumb,
          });

          /*
           * IMPORTANT:
           * Do NOT remove tempId from loadingIds here.
           *
           * The canvas thumbnail remains visible with the spinner
           * until UploadNotifications finds the RAW GitHub image.
           */
        } else {
          setImages(prev =>
            prev.filter(img => img.id !== tempId)
          );

          setLoadingIds(prev => {
            const next = new Set(prev);
            next.delete(tempId);
            return next;
          });

          setSuccessMsg(
            `"${file.name}" uploaded — click Refresh once GitHub Actions finishes (usually ~30 s).`
          );
        }
      } catch (err: any) {
        setImages(prev =>
          prev.filter(img => img.id !== tempId)
        );

        setLoadingIds(prev => {
          const next = new Set(prev);
          next.delete(tempId);
          return next;
        });

        setErrorMsg(
          err?.message ?? "Upload failed"
        );
      }
    },
    [api, images]
  );

  const handleSeo = (id: string) => {
    const img = images.find(i => i.id === id);

    if (!img || img.isStatic) return;

    setSeoTarget(img);
  };

  const handleImageNotFound =
    useCallback((id: string) => {
      setImages(prev =>
        prev.filter(i => i.id !== id)
      );
    }, []);

  const onDrop = async (
    e: React.DragEvent
  ) => {
    e.preventDefault();
    setDragging(false);

    await processFiles(
      e.dataTransfer.files
    );
  };

  const visibleImages =
    images.filter(
      img => !loadingIds.has(img.id)
    );

  const loadingImages =
    images.filter(
      img => loadingIds.has(img.id)
    );

  const prev = () =>
    setLightboxIdx(i =>
      i !== null
        ? (
            i -
            1 +
            visibleImages.length
          ) %
          visibleImages.length
        : 0
    );

  const next = () =>
    setLightboxIdx(i =>
      i !== null
        ? (
            i +
            1
          ) %
          visibleImages.length
        : 0
    );

  useEffect(() => {
    const handler = (
      e: KeyboardEvent
    ) => {
      if (lightboxIdx === null) {
        return;
      }

      if (e.key === "ArrowLeft") {
        prev();
      }

      if (e.key === "ArrowRight") {
        next();
      }

      if (e.key === "Escape") {
        setLightboxIdx(null);
      }
    };

    window.addEventListener(
      "keydown",
      handler
    );

    return () =>
      window.removeEventListener(
        "keydown",
        handler
      );
  }, [
    lightboxIdx,
    visibleImages.length,
  ]);
  if (pageLoading) {
    return (
      <div className="view-wrap">
        <div
          style={{
            padding: "40px 0",
            textAlign: "center",
            color: "#aaa",
            fontSize: 14,
          }}
        >
          Loading images…
        </div>
      </div>
    );
  }

  if (pageError) {
    return (
      <div className="view-wrap">
        <div
          style={{
            padding: "12px 16px",
            background: C.dangerBg,
            border:
              `1px solid ${C.dangerBorder}`,
            borderRadius: 10,
            color: C.dangerText,
            fontSize: 14,
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          {pageError}

          <button
            onClick={loadImages}
            style={{
              fontSize: 12,
              textDecoration: "underline",
              background: "none",
              border: "none",
              color: C.dangerText,
              cursor: "pointer",
              padding: 0,
            }}
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="view-wrap">
      {successMsg && (
        <div
          style={{
            marginBottom: 16,
            padding: "10px 14px",
            background:
              "rgba(34,197,94,0.12)",
            border:
              "1px solid rgba(34,197,94,0.35)",
            borderRadius: 10,
            color: "#16a34a",
            fontSize: 13,
            display: "flex",
            justifyContent:
              "space-between",
            alignItems: "center",
          }}
        >
          {successMsg}

          <button
            onClick={() =>
              setSuccessMsg("")
            }
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              color: "#16a34a",
              fontSize: 18,
              lineHeight: 1,
              padding: 0,
            }}
          >
            ×
          </button>
        </div>
      )}

      {errorMsg && (
        <div
          style={{
            marginBottom: 16,
            padding: "10px 14px",
            background: C.dangerBg,
            border:
              `1px solid ${C.dangerBorder}`,
            borderRadius: 10,
            color: C.dangerText,
            fontSize: 13,
            display: "flex",
            justifyContent:
              "space-between",
            alignItems: "center",
          }}
        >
          {errorMsg}

          <button
            onClick={() =>
              setErrorMsg("")
            }
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              color: C.dangerText,
              fontSize: 18,
              lineHeight: 1,
              padding: 0,
            }}
          >
            ×
          </button>
        </div>
      )}

      <div
        className={`drop-zone ${
          dragging
            ? "drop-zone--active"
            : ""
        }`}
        onDragOver={e => {
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() =>
          setDragging(false)
        }
        onDrop={onDrop}
        onClick={() =>
          inputRef.current?.click()
        }
      >
        <FaCloudUploadAlt
          size={40}
          color={
            dragging
              ? C.yellow
              : "#bbb"
          }
        />

        <p className="drop-zone__title">
          Drag &amp; drop an image here
        </p>

        <p className="drop-zone__sub">
          or click to browse — PNG, JPG,
          WEBP — one at a time
        </p>

        <div className="drop-zone__btn">
          <FaUpload size={13} />
          Choose File
        </div>

        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          hidden
          onChange={e =>
            processFiles(
              e.target.files
            )
          }
        />
      </div>

      {loadingImages.length > 0 && (
        <div className="grid">
          {loadingImages.map(img => (
            <div
              key={img.id}
              className="grid-item"
            >
              <Image
                src={img.src}
                alt={img.name}
                className="grid-item__img"
              />

              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  background:
                    "rgba(0,0,0,0.18)",
                  pointerEvents: "none",
                }}
              >
                <div
                  style={{
                    width: 28,
                    height: 28,
                    border:
                      "3px solid rgba(255,255,255,0.45)",
                    borderTopColor: "#fff",
                    borderRadius: "50%",
                    animation:
                      "gh-image-spin 0.8s linear infinite",
                  }}
                />
              </div>

              <div className="grid-item__name">
                {img.name}
              </div>
            </div>
          ))}
        </div>
      )}

      {visibleImages.length > 0 ? (
        <>
          <div className="gallery-header">
            <span className="gallery-header__count">
              {visibleImages.length}{" "}
              {visibleImages.length === 1
                ? "image"
                : "images"}
            </span>

            <button
              className="gallery-header__refresh"
              onClick={loadImages}
              title="Refresh from backend"
            >
              <FaSyncAlt size={12} />
              <span>Refresh</span>
            </button>
          </div>

          <div className="grid">
            {visibleImages.map(
              (img, idx) => (
                <ImageCard
                  key={img.id}
                  img={img}
                  // @PPM_ERROR
                  // @ts-ignore
                  loading={false}
                  onView={() =>
                    setLightboxIdx(idx)
                  }
                  onDelete={() =>
                    removeImage(img.id)
                  }
                  onSeo={() =>
                    handleSeo(img.id)
                  }
                  onNotFound={() =>
                    handleImageNotFound(
                      img.id
                    )
                  }
                />
              )
            )}
          </div>
        </>
      ) : (
        loadingImages.length === 0 && (
          <div className="empty-state">
            <FaImages
              size={48}
              color="#ddd"
            />

            <p className="empty-state__text">
              No images yet. Upload your
              first one above.
            </p>
          </div>
        )
      )}

      {lightboxIdx !== null &&
        visibleImages[
          lightboxIdx
        ] && (
          <div
            className="lb-overlay"
            onClick={() =>
              setLightboxIdx(null)
            }
          >
            <div
              className="lb-box"
              onClick={e =>
                e.stopPropagation()
              }
            >
              <button
                className="lb-close"
                onClick={() =>
                  setLightboxIdx(null)
                }
              >
                <FaTimes size={16} />
              </button>

              <button
                className="lb-nav lb-nav--left"
                onClick={prev}
              >
                <FaChevronLeft
                  size={18}
                />
              </button>

              <img
                src={
                  visibleImages[
                    lightboxIdx
                  ].src
                }
                alt={
                  visibleImages[
                    lightboxIdx
                  ].name
                }
                className="lb-img"
              />

              <button
                className="lb-nav lb-nav--right"
                onClick={next}
              >
                <FaChevronRight
                  size={18}
                />
              </button>

              <div className="lb-footer">
                <span className="lb-footer__name">
                  {
                    visibleImages[
                      lightboxIdx
                    ].name
                  }
                </span>

                <span className="lb-footer__counter">
                  {lightboxIdx + 1} /{" "}
                  {
                    visibleImages
                      .length
                  }
                </span>
              </div>
            </div>
          </div>
        )}

      {seoTarget && (
        <SeoModal
          img={seoTarget}
          api={api}
          onClose={() =>
            setSeoTarget(null)
          }
          onSaved={patch => {
            setImages(prev =>
              prev.map(i =>
                i.id === seoTarget.id
                  ? {
                      ...i,
                      ...patch,
                    }
                  : i
              )
            );

            setSeoTarget(null);
          }}
        />
      )}
    </div>
  );
};


// ── SEO modal ────────────────────────────────────────────────────────────────
// Pre-fills from img.name + img.meta?.alt. Save batches whatever changed
// (rename, meta, or both) into a single applyChanges() call on the unified
// /api/update-image endpoint (MTC-BRI-18). Locks body scroll while open.
const SeoModal: React.FC<{
  img: Img;
  api: ImageApiAdapter;
  onClose: () => void;
  onSaved: (patch: Partial<Img>) => void;
}> = ({ img, api, onClose, onSaved }) => {
  const initialAlt = (img.meta?.alt as string | undefined) ?? "";
  const [name, setName] = useState(img.name);
  const [alt, setAlt] = useState(initialAlt);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState("");

  useEffect(() => {
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape" && !saving) onClose(); };
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = previous;
      window.removeEventListener("keydown", onKey);
    };
  }, [onClose, saving]);

  const trimmedName = name.trim();
  const nameChanged = trimmedName.length > 0 && trimmedName !== img.name;
  const altChanged  = alt !== initialAlt;
  const dirty = nameChanged || altChanged;

  const handleSave = async () => {
    if (!dirty || saving) return;
    setSaving(true);
    setErr("");

    // Batch into a single POST — whatever fields changed.
    const changes: Parameters<typeof api.applyChanges>[0] = [];
    if (nameChanged) {
      changes.push({ action: "rename", id: img.id, value: trimmedName });
    }
    if (altChanged) {
      const nextMeta = { ...(img.meta ?? {}), alt };
      changes.push({ action: "update", id: img.id, attribute: "meta", value: nextMeta });
    }

    try {
      await api.applyChanges(changes);
      const patch: Partial<Img> = {};
      if (nameChanged) patch.name = trimmedName;
      if (altChanged)  patch.meta = { ...(img.meta ?? {}), alt };
      onSaved(patch);
    } catch (e: any) {
      setErr(e?.message ?? "Save failed");
      setSaving(false);
    }
  };

  return (
    <div className="seo-modal-overlay" onClick={() => !saving && onClose()}>
      <div className="seo-modal" onClick={e => e.stopPropagation()} role="dialog" aria-modal="true">
        <div className="seo-modal__header">
          <div>
            <h3 className="seo-modal__title">SEO Settings</h3>
            <p className="seo-modal__filename">{img.name}</p>
          </div>
          <button className="seo-modal__close" onClick={onClose} aria-label="Close" disabled={saving}>
            <FaTimes size={14} />
          </button>
        </div>

        <div className="seo-modal__body">
          <div className="seo-modal__field">
            <label htmlFor="seo-name">Image Name</label>
            <input
              id="seo-name"
              type="text"
              className="seo-modal__input"
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder="descriptive-file-name.webp"
              disabled={saving}
            />
          </div>

          <div className="seo-modal__field">
            <label htmlFor="seo-alt">Alt Text</label>
            <textarea
              id="seo-alt"
              className="seo-modal__textarea"
              value={alt}
              onChange={e => setAlt(e.target.value)}
              placeholder="Describe this image for screen readers and search engines."
              rows={3}
              disabled={saving}
            />
          </div>

          {err && (
            <div style={{
              padding: "8px 12px", borderRadius: 8, fontSize: 12,
              background: "rgba(220,53,69,0.1)",
              border: "1px solid rgba(220,53,69,0.35)",
              color: "#dc2626",
            }}>
              {err}
            </div>
          )}
        </div>

        <div className="seo-modal__footer">
          <button
            className="seo-modal__save"
            disabled={!dirty || saving}
            onClick={handleSave}
          >
            {saving ? "Saving…" : "Save"}
          </button>
        </div>
      </div>
    </div>
  );
};

