// The Application Builder's walkthrough logic.
//
// The engine moved to modules/shared/tutorial for MTC-KRP-048. Everything
// generic is re-exported from there unchanged; what stays here is the one
// thing that is genuinely this CMS's own — what its prerequisites mean.

export {
  start,
  currentStep,
  isFirstStep,
  isLastStep,
  stepLabel,
  next,
  back,
  markMissing,
  findResumeStep,
} from "../../shared/tutorial/tutorialMachine.ts";

export type { TutorialState } from "../../shared/tutorial/tutorialMachine";

import { canRun as canRunWith } from "../../shared/tutorial/tutorialMachine.ts";
import type { Tutorial } from "../../shared/tutorial/types";
import type { Prerequisite } from "./types";

export type TutorialContext = {
  /** How many applications are in the trash right now. */
  trashCount: number;
  /** How many live applications exist. */
  applicationCount: number;
};

/**
 * Whether a walkthrough has anything to show.
 *
 * Checked before starting rather than discovered three steps in, so the reader
 * gets an explanation instead of a spotlight over nothing.
 */
export function checkPrerequisite(
  requires: Prerequisite | undefined,
  context: TutorialContext
): boolean {
  if (!requires || requires === "none") return true;
  if (requires === "hasTrash") return context.trashCount > 0;
  if (requires === "hasTwoApplications") return context.applicationCount > 1;
  return true;
}

/** The signature ApplyView and the tests already use, kept deliberately. */
export function canRun(tutorial: Tutorial, context: TutorialContext): boolean {
  return canRunWith(tutorial, (requires) =>
    checkPrerequisite(requires as Prerequisite, context)
  );
}
