// The property workflow's own furniture: field groups, choices, photographs,
// floor plans, the similar-property rows and the review screen.
//
// Split from wizard-css.ts because that file is the SHELL — the step list, the
// panel, the dots — and this one is what goes inside it. Keeping them apart
// means the approved MTC-KRP-025 navigation is not being edited every time a
// field arrives.
//
// Nothing here introduces a colour. Every value comes from the CMS theme, and
// state is carried by a word or a shape as well as by tone, so the screens
// still read for someone who cannot separate the charcoal from the gold.

import theme from "../../config/opencms--theme";

const radius = theme.cardRadius ?? 14;
const ease = "cubic-bezier(.22, 1, .36, 1)";

export const wizardFormsCss = `
/* ── the publication bar ─────────────────────────────────
   MTC-KRP-033. A property-level strip above the wizard, so publication reads
   as a fact about the PROPERTY rather than as the last step of a form.

   It shipped with no stylesheet at all — the classes below were used in the
   component and defined nowhere, so it rendered as bare text and two default
   buttons. Every test still passed, because none of them render it. The same
   failure as the leave-dialog in MTC-KRP-029, and the same fix: write the
   rules the markup is already asking for.

   Built from the card system rather than beside it: same white surface, same
   border, same radius as every wizard card, so it belongs to the page instead
   of decorating it. Status is carried by an icon AND a word, never by colour
   alone. */
/* No max-width. This bar and .kr-wiz__layout are siblings, so leaving it
   unconstrained is what makes its right edge land exactly on the right edge of
   the step card below it. A 720px cap stopped it two-thirds of the way across
   and left the panel looking like it belonged to something else. */
.kr-pub-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
  padding: 14px 18px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
}
/* A published property gets a quiet gold edge — the one place the accent is
   used as state, and it is reinforced by the icon and the word beside it. */
.kr-pub-bar--published { border-left: 3px solid ${theme.primary}; }
.kr-pub-bar--draft { border-left: 3px solid ${theme.border}; }

.kr-pub-bar__status {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 10px;
  flex: 1;
  min-width: 0;
}
.kr-pub-bar__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  align-self: center;
  border-radius: 50%;
  background: ${theme.background};
  color: ${theme.textMuted};
}
.kr-pub-bar--published .kr-pub-bar__icon {
  background: ${theme.primary}14;
  color: ${theme.primary};
}
.kr-pub-bar__label {
  color: ${theme.text};
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.kr-pub-bar__detail {
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.5;
}

.kr-pub-bar__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}
.kr-pub-bar__actions .kr-props__btn { min-height: 44px; }

.kr-pub-bar__feedback {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13.5px;
  font-weight: 600;
}
.kr-pub-bar__feedback--ok { color: ${theme.text}; }
.kr-pub-bar__feedback--error { color: ${theme.danger}; font-weight: 500; }

/* Sits under the whole strip rather than beside the button, so a long list of
   missing fields cannot squeeze the action off the row. */
.kr-pub-bar__blockers {
  flex-basis: 100%;
  margin: 0;
  color: ${theme.textMuted};
  font-size: 13px;
  line-height: 1.55;
}

@media (max-width: 760px) {
  .kr-pub-bar { align-items: flex-start; }
  .kr-pub-bar__actions { margin-left: 0; width: 100%; }
  .kr-pub-bar__actions .kr-props__btn { flex: 1; justify-content: center; }
  /* The message goes above the button on a phone: it explains why the button
     is unavailable, and explaining after the fact is no explanation. */
  .kr-pub-bar__feedback { flex-basis: 100%; }
}

/* ── inside a card ───────────────────────────────
   Two or more fields sharing one card. The card supplies the frame; this only
   supplies the rhythm between them. */
.kr-wiz__stack { display: grid; gap: 22px; }

/* ── no cards inside cards ───────────────────────
   Several of these were built as bordered boxes back when the whole step lived
   in one big card and a border was the only way to separate anything. Now that
   each of them IS a card, that border would be a second frame 24px inside the
   first — the card soup the brief warns about. They keep the card frame and
   drop their own. */
.kr-wiz__fields > .kr-wiz__note { border-left: 2px solid ${theme.primary}; }
.kr-wiz__fields > .kr-wiz__drop { border-style: dashed; }
.kr-wiz__fields > .kr-wiz__trouble { border-color: ${theme.danger}40; }

/* A photograph is one row - a thumbnail, a caption, a couple of controls - so
   a rule between siblings separates them without boxing every line. */
.kr-wiz__photos > .kr-wiz__photo {
  border: 0;
  border-radius: 0;
  background: none;
  padding: 22px 0 0;
  border-top: 1px solid ${theme.border};
}
.kr-wiz__photos > .kr-wiz__photo:first-child { border-top: 0; padding-top: 0; }
.kr-wiz__photos { gap: 22px; }

/* A floor plan is not a row. It is a name, a description, beds, baths, size,
   availability, price and a drawing - a small form each. Separated by a hair
   line they ran together, and it was genuinely hard to see where one unit
   ended and the next began. So each keeps the card the base rule gives it,
   with the grey of the step showing between them: the same thing the fields
   above them do, rather than a second idea of what a group looks like. */
.kr-wiz__plans { gap: 16px; }
.kr-wiz__plans > .kr-wiz__plan { padding: 20px; }

/* ── small pieces ─────────────────────────────────────── */
.kr-wiz__optional { color: ${theme.textMuted}; font-weight: 500; font-size: 13.5px; }
.kr-wiz__help--above { margin: -4px 0 16px; }
.kr-wiz__code {
  padding: 1px 5px;
  border-radius: 4px;
  background: ${theme.background};
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11.5px;
}

.kr-wiz__error {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 9px 0 0;
  color: ${theme.danger};
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
}
.kr-wiz__error svg { flex-shrink: 0; margin-top: 2px; }
.kr-wiz__error--block {
  padding: 10px 12px;
  border: 1px solid ${theme.danger}40;
  border-radius: 8px;
  background: ${theme.danger}0d;
}
.kr-wiz__field:has(> .kr-wiz__error) .kr-props__input { border-color: ${theme.danger}; }

.kr-wiz__blocked {
  max-width: 640px;
  margin: 10px 0 0;
  color: ${theme.danger};
  font-size: 12.5px;
}

.kr-wiz__saved {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 12px 0 0;
  color: ${theme.text};
  font-size: 13px;
  font-weight: 600;
}

.kr-wiz__link {
  appearance: none;
  padding: 0;
  border: 0;
  background: none;
  color: ${theme.text};
  font: inherit;
  font-weight: 600;
  text-decoration: underline;
  cursor: pointer;
}
.kr-wiz__link:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 2px; }

.kr-props__btn--quiet { border-color: transparent; color: ${theme.textMuted}; }
.kr-props__btn--quiet:hover:not(:disabled) { border-color: ${theme.border}; color: ${theme.text}; }

.kr-wiz__icon-btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: none;
  color: ${theme.textMuted};
  cursor: pointer;
}
.kr-wiz__icon-btn:hover:not(:disabled) { border-color: ${theme.border}; color: ${theme.text}; }
.kr-wiz__icon-btn:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 1px; }
.kr-wiz__icon-btn:disabled { opacity: .35; cursor: default; }

.kr-wiz__note--tight { margin: 0; }

/* ── several short fields on one line ─────────────────────
   Sized rather than counted, so they wrap when the column is narrow instead of
   waiting for a breakpoint to be told to. */
.kr-wiz__row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 16px;
}

/* ── a number with a symbol beside it ─────────────────────
   The symbol sits inside the control's frame rather than in the label, so what
   the manager is typing reads as "$1,995 / month" while they type it. */
.kr-wiz__number { position: relative; display: block; }
.kr-wiz__number--prefixed .kr-props__input { padding-left: 27px; }
.kr-wiz__affix {
  position: absolute;
  top: 50%;
  left: 12px;
  transform: translateY(-50%);
  color: ${theme.textMuted};
  font-size: 13.5px;
  pointer-events: none;
}
.kr-wiz__affix--end { left: auto; right: 14px; }
.kr-wiz__number:has(.kr-wiz__affix--end) .kr-props__input { padding-right: 78px; }

/* ── grouped controls ─────────────────────────────────────
   A real fieldset, so the group has a name a screen reader announces once
   rather than a heading it has no relationship to.

   Nested groups reset fieldset chrome. The shared outer card rule in
   wizard-css.ts owns the frame and responsive padding of top-level groups. */
.kr-wiz__group {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
/* Keep the semantic legend inside the padded box, rather than straddling its
   top border as native fieldset legends do. */
.kr-wiz__group > legend { float: left; width: 100%; }
.kr-wiz__group > legend + * { clear: both; }
.kr-wiz__group > .kr-props__label,
.kr-wiz__group > legend { padding: 0; margin-bottom: 8px; }
.kr-wiz__group + .kr-wiz__group { margin-top: 4px; }

.kr-wiz__choices { display: grid; gap: 8px; }
.kr-wiz__choice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid ${theme.border};
  border-radius: 9px;
  background: ${theme.sidebar};
  cursor: pointer;
  transition: border-color 140ms ${ease}, background 140ms ${ease};
}
.kr-wiz__choice:hover { border-color: ${theme.textMuted}55; }
.kr-wiz__choice--on { border-color: ${theme.primary}; background: ${theme.background}; }
.kr-wiz__choice input { margin-top: 2px; accent-color: ${theme.primary}; }
.kr-wiz__choice:focus-within { outline: 2px solid ${theme.primary}; outline-offset: 1px; }
.kr-wiz__choice-label { display: block; font-size: 15px; font-weight: 600; }
.kr-wiz__choice-help { display: block; margin-top: 3px; color: ${theme.textMuted}; font-size: 13.5px; }

/* ── checklists ───────────────────────────────────────── */
.kr-wiz__checks {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 6px 14px;
}
.kr-wiz__check {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 44px;
  padding: 5px 7px;
  border-radius: 7px;
  font-size: 15px;
  cursor: pointer;
}
.kr-wiz__check:hover { background: ${theme.background}; }
.kr-wiz__check input { accent-color: ${theme.primary}; width: 18px; height: 18px; }
.kr-wiz__check:focus-within { outline: 2px solid ${theme.primary}; outline-offset: 1px; }

.kr-wiz__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}
.kr-wiz__tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 6px 5px 11px;
  border: 1px solid ${theme.border};
  border-radius: 999px;
  background: ${theme.background};
  font-size: 13.5px;
  font-weight: 600;
}
.kr-wiz__tag-remove {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: none;
  color: ${theme.textMuted};
  cursor: pointer;
}
.kr-wiz__tag-remove:hover { background: ${theme.sidebar}; color: ${theme.text}; }
.kr-wiz__tag-remove:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 1px; }

.kr-wiz__inline { display: flex; align-items: flex-start; gap: 10px; margin-top: 14px; }
.kr-wiz__inline .kr-props__input { flex: 1; min-width: 0; }
.kr-wiz__inline .kr-props__btn { min-height: 44px; flex-shrink: 0; }

/* ── facts shown rather than asked for ──────────────────── */
.kr-wiz__derived {
  padding: 14px 16px;
  border: 1px solid ${theme.border};
  border-radius: 10px;
  background: ${theme.sidebar};
}
.kr-wiz__derived-head {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 0;
  color: ${theme.textMuted};
  font-size: 14px;
  line-height: 1.6;
}
.kr-wiz__derived-head svg { flex-shrink: 0; margin-top: 1px; }
.kr-wiz__derived-head strong { color: ${theme.text}; }
.kr-wiz__derived-list { margin: 12px 0 0; display: grid; gap: 1px; }
.kr-wiz__derived-list > div {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  padding: 9px 0;
  border-top: 1px solid ${theme.border};
  font-size: 14.5px;
}
.kr-wiz__derived-list dt { min-width: 140px; color: ${theme.textMuted}; }
.kr-wiz__derived-list dd { margin: 0; font-weight: 600; }

/* ── uploading ────────────────────────────────────────── */
.kr-wiz__drop--over { border-color: ${theme.primary}; background: ${theme.primary}0a; }
.kr-wiz__drop-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 14px;
}
.kr-wiz__drop-actions .kr-props__btn { min-height: 44px; }

.kr-wiz__trouble {
  padding: 13px 15px;
  border: 1px solid ${theme.danger}40;
  border-radius: 10px;
  background: ${theme.danger}0a;
  font-size: 14.5px;
  line-height: 1.65;
}
.kr-wiz__trouble-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  color: ${theme.danger};
  font-weight: 700;
}
.kr-wiz__trouble ul { margin: 0; padding-left: 18px; }
.kr-wiz__trouble .kr-props__btn { margin-top: 10px; }

/* ── the photographs ──────────────────────────────────── */
.kr-wiz__photos {
  display: grid;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-wiz__photo {
  display: grid;
  grid-template-columns: 168px minmax(0, 1fr);
  gap: 16px;
  padding: 14px;
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
  background: ${theme.sidebar};
}
.kr-wiz__photo--featured { border-color: ${theme.primary}; }
.kr-wiz__photo-media { position: relative; }
.kr-wiz__photo-media img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 9px;
  background: ${theme.background};
}
.kr-wiz__photo-flag {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 8px 0 0;
  color: ${theme.text};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.kr-wiz__photo-fields { display: grid; gap: 14px; min-width: 0; }
.kr-wiz__photo-actions { display: flex; flex-wrap: wrap; gap: 8px; }

/* ── floor plans ──────────────────────────────────────── */
.kr-wiz__plans {
  display: grid;
  gap: 14px;
  margin: 0 0 14px;
  padding: 0;
  list-style: none;
}
.kr-wiz__plan {
  padding: 16px;
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
  background: ${theme.sidebar};
}
.kr-wiz__plan-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 14px;
}
.kr-wiz__plan-title { margin: 0; font-size: 16px; font-weight: 700; }
.kr-wiz__plan-image {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 13px;
  border: 1px dashed ${theme.border};
  border-radius: 9px;
  background: ${theme.background};
}
.kr-wiz__plan-image img {
  width: 92px;
  height: 92px;
  flex-shrink: 0;
  object-fit: contain;
  border-radius: 7px;
  background: ${theme.sidebar};
}
.kr-wiz__plan-image-empty {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 8px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  color: ${theme.textMuted};
}
.kr-wiz__plan-image-title { margin: 0 0 3px; font-size: 13.5px; font-weight: 600; }
.kr-wiz__plan-image .kr-props__btn { margin-top: 9px; }

/* ── the leave-without-saving dialog ──────────
   Narrow, centred and unmistakably on top of the page. This is the one thing
   in the workflow that stands between somebody and losing their work, so it is
   not a strip of text with two default buttons under it. The SAFE action is
   the filled one: the eye lands on "Stay here" first, and the destructive
   choice has to be aimed at. */
.kr-wiz__ask {
  width: min(440px, 100%);
  padding: 24px;
  border-radius: ${radius}px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  box-shadow: 0 24px 60px rgba(15, 23, 42, .26);
  text-align: left;
}
.kr-wiz__ask-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  margin-bottom: 15px;
  border-radius: 50%;
  background: ${theme.background};
  border: 1px solid ${theme.border};
  color: ${theme.textMuted};
}
.kr-wiz__ask-icon--danger {
  background: ${theme.danger}0f;
  border-color: ${theme.danger}33;
  color: ${theme.danger};
}
.kr-wiz__ask-title {
  margin: 0 0 8px;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: ${theme.text};
}
.kr-wiz__ask-text {
  margin: 0 0 20px;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.65;
}
/* The second, quieter line — what can be undone. Separated from the question
   rather than appended to it, so the question stays a question. */
.kr-wiz__ask-note {
  margin: -12px 0 20px;
  padding: 10px 12px;
  border-radius: 8px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 13px;
  line-height: 1.6;
}

.kr-wiz__ask-actions { display: flex; flex-wrap: wrap; gap: 10px; }
.kr-wiz__ask-actions .kr-props__btn { min-height: 44px; flex: 1; justify-content: center; }

/* Filled red, white text — MTC-KRP-035. I had this outlined, on the reasoning
   that the destructive option should not be the loudest thing in a dialog
   whose safe answer is the filled button. Nate asked for red with white text
   while looking at the actual screen, so filled it is; the safe action stays
   distinct by being the OUTLINED one beside it. */
.kr-props__btn--danger {
  background: ${theme.danger};
  border-color: ${theme.danger};
  color: #fff;
}
.kr-props__btn--danger:hover:not(:disabled) {
  background: #B91C1C;
  border-color: #B91C1C;
  color: #fff;
}
.kr-props__btn--danger:active:not(:disabled) {
  background: #991B1B;
  border-color: #991B1B;
}
.kr-props__btn--danger:focus-visible { outline-color: ${theme.danger}; }

/* ── the library dialog ───────────────────────────────── */
.kr-wiz__scrim {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(15, 23, 42, .42);
}
.kr-wiz__dialog {
  display: flex;
  flex-direction: column;
  width: min(760px, 100%);
  max-height: min(84dvh, 720px);
  border-radius: ${radius}px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  box-shadow: 0 24px 60px rgba(15, 23, 42, .22);
  overflow: hidden;
}
.kr-wiz__dialog-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
  border-bottom: 1px solid ${theme.border};
}
.kr-wiz__dialog-title { margin: 0; flex: 1; font-size: 15px; font-weight: 700; }
.kr-wiz__dialog-search {
  position: relative;
  display: flex;
  align-items: center;
  padding: 13px 16px;
  border-bottom: 1px solid ${theme.border};
}
.kr-wiz__dialog-search svg {
  position: absolute;
  left: 28px;
  color: ${theme.textMuted};
  pointer-events: none;
}
.kr-wiz__dialog-search .kr-props__input { padding-left: 36px; }
.kr-wiz__dialog-body { flex: 1; overflow-y: auto; padding: 16px; }
.kr-wiz__dialog-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 13px 16px;
  border-top: 1px solid ${theme.border};
  background: ${theme.background};
}
.kr-wiz__dialog-foot .kr-wiz__help { margin: 0; }

.kr-wiz__library {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-wiz__library-item {
  appearance: none;
  display: block;
  width: 100%;
  padding: 7px;
  border: 1px solid ${theme.border};
  border-radius: 10px;
  background: ${theme.sidebar};
  color: ${theme.text};
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.kr-wiz__library-item:hover:not(:disabled) { border-color: ${theme.textMuted}55; }
.kr-wiz__library-item:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 1px; }
.kr-wiz__library-item--on { border-color: ${theme.primary}; background: ${theme.background}; }
.kr-wiz__library-item:disabled { opacity: .55; cursor: default; }
.kr-wiz__library-item img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 7px;
  background: ${theme.background};
}
.kr-wiz__library-name {
  display: block;
  margin-top: 7px;
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kr-wiz__library-flag {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 3px;
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.kr-wiz__library-flag--on { color: ${theme.text}; }

/* ── similar properties ───────────────────────────────── */
.kr-wiz__search {
  position: relative;
  display: flex;
  align-items: center;
  margin-bottom: 14px;
}
.kr-wiz__search svg {
  position: absolute;
  left: 12px;
  color: ${theme.textMuted};
  pointer-events: none;
}
.kr-wiz__search .kr-props__input { padding-left: 36px; }

.kr-wiz__similar {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-wiz__similar-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid ${theme.border};
  border-radius: 10px;
  background: ${theme.sidebar};
}
.kr-wiz__similar-row--pinned { border-color: ${theme.primary}; }
.kr-wiz__similar-row--dragging { opacity: .5; }
.kr-wiz__grip { color: ${theme.textMuted}; cursor: grab; flex-shrink: 0; }
.kr-wiz__rank {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border-radius: 50%;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
}
.kr-wiz__similar-body {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: 1;
  min-width: 180px;
}
.kr-wiz__similar-image {
  width: 52px;
  height: 40px;
  flex-shrink: 0;
  object-fit: cover;
  border-radius: 6px;
  background: ${theme.background};
}
.kr-wiz__similar-name { margin: 0; font-size: 15px; font-weight: 600; }
.kr-wiz__similar-meta { margin: 3px 0 0; color: ${theme.textMuted}; font-size: 13.5px; }
.kr-wiz__similar-state {
  margin: 0;
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.kr-wiz__similar-actions { display: flex; align-items: center; gap: 6px; margin-left: auto; }

/* ── review ───────────────────────────────────────────── */
.kr-wiz__checklist { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
.kr-wiz__checkline {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 0;
  border-bottom: 1px solid ${theme.border};
  font-size: 14.5px;
}
.kr-wiz__checkline:last-child { border-bottom: 0; }
.kr-wiz__checkmark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border: 1px solid ${theme.border};
  border-radius: 50%;
  background: ${theme.sidebar};
  color: ${theme.textMuted};
}
.kr-wiz__checkline--done .kr-wiz__checkmark {
  background: ${theme.primary};
  border-color: ${theme.primary};
  color: #fff;
}
.kr-wiz__checkline-label { display: block; font-weight: 600; font-size: 15px; }
.kr-wiz__checkline-state { display: block; margin-top: 3px; color: ${theme.textMuted}; font-size: 13.5px; }

.kr-wiz__review {
  padding: 15px 16px;
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
  background: ${theme.sidebar};
}
.kr-wiz__review-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}
.kr-wiz__review-title {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: ${theme.textMuted};
}
.kr-wiz__review-list { display: grid; gap: 1px; margin: 0; }
.kr-wiz__review-list > div {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  padding: 10px 0;
  border-top: 1px solid ${theme.border};
  font-size: 14.5px;
}
.kr-wiz__review-list > div:first-child { border-top: 0; }
.kr-wiz__review-list dt { min-width: 150px; color: ${theme.textMuted}; }
.kr-wiz__review-list dd { margin: 0; flex: 1; min-width: 0; font-weight: 600; }

.kr-wiz__publish-actions { display: flex; flex-wrap: wrap; gap: 10px; }
.kr-wiz__publish-actions .kr-props__btn { min-height: 44px; }

/* ── narrow screens ─────────────────────────────────────
   Stacked rather than shrunk. A control that has been squeezed to fit is a
   control somebody is going to miss with their thumb. */
@media (max-width: 760px) {
  .kr-wiz__photo { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .kr-wiz__photo-media img { aspect-ratio: 16 / 9; }
  .kr-wiz__photo-actions .kr-props__btn,
  .kr-wiz__plan-head .kr-props__btn { min-height: 44px; }

  .kr-wiz__similar-row { align-items: flex-start; }
  .kr-wiz__similar-actions { margin-left: 0; width: 100%; flex-wrap: wrap; }
  .kr-wiz__similar-actions .kr-props__btn { min-height: 44px; }
  .kr-wiz__similar-state { order: -1; }

  .kr-wiz__checks { grid-template-columns: minmax(0, 1fr); }

  .kr-wiz__inline { flex-direction: column; align-items: stretch; }
  .kr-wiz__inline .kr-props__btn { justify-content: center; }

  .kr-wiz__review-list > div,
  .kr-wiz__derived-list > div { flex-direction: column; gap: 2px; }
  .kr-wiz__review-list dt,
  .kr-wiz__derived-list dt { min-width: 0; }

  .kr-wiz__dialog { max-height: 92dvh; }
  .kr-wiz__ask { padding: 20px; }
  .kr-wiz__ask-actions { flex-direction: column-reverse; }
  .kr-wiz__scrim { padding: 10px; }
  .kr-wiz__library { grid-template-columns: repeat(auto-fill, minmax(126px, 1fr)); }

  .kr-wiz__publish-actions .kr-props__btn { flex: 1; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-wiz__choice, .kr-wiz__drop { transition: none; }
}
`;

export default wizardFormsCss;
