import React from "react";
import {
  LuCheck,
  LuCircle,
  LuCircleDashed,
  LuPencil,
  LuSave,
  LuTriangleAlert,
  LuUpload,
} from "react-icons/lu";

import { buildReview, readiness } from "../review";
import type { ReadinessState } from "../review";
import { canPublish, publishBlockers } from "../validation";
import type { StepProps } from "./types";

/**
 * Page 5 — check it, then publish it.
 *
 * A review screen, not a sixth form and not a dump of the record. Everything
 * here is derived from what would actually be saved, which is why it can be
 * trusted: it is not a summary of what was typed, it is a description of the
 * page that would appear.
 *
 * Each section carries an Edit link back to the step that owns it, so a
 * mistake spotted here costs one click rather than a hunt through five pages.
 */
export default function ReviewStep({
  draft,
  properties,
  onGoToStep,
  onSave,
  saving,
  saveError,
  savedAt,
}: StepProps) {
  const sections = buildReview(draft, properties);
  const checks = readiness(draft);
  const blockers = publishBlockers(draft);
  const ready = canPublish(draft);
  const published = draft.publication === "published";

  return (
    <div className="kr-wiz__fields">
      {/* ── what is still needed ────────────────────────── */}
      <section className="kr-wiz__group">
        <h3 className="kr-props__label">Before publishing</h3>

        <ul className="kr-wiz__checklist">
          {checks.map((check) => (
            <li key={check.label} className={`kr-wiz__checkline kr-wiz__checkline--${check.state}`}>
              <span className="kr-wiz__checkmark" aria-hidden="true">
                <Mark state={check.state} />
              </span>
              <span>
                <span className="kr-wiz__checkline-label">{check.label}</span>
                {/* The state in words as well as in a shape — never colour
                    alone, and never a shape alone either. */}
                <span className="kr-wiz__checkline-state">
                  {check.state === "done"
                    ? "Complete"
                    : check.state === "todo"
                      ? "Still needed"
                      : "Optional"}
                  {check.detail ? ` — ${check.detail}` : ""}
                </span>
              </span>
            </li>
          ))}
        </ul>

        {!ready ? (
          <div className="kr-wiz__trouble" role="status">
            <p className="kr-wiz__trouble-title">
              <LuTriangleAlert size={15} aria-hidden="true" />
              {blockers.length === 1
                ? "One thing is missing"
                : `${blockers.length} things are missing`}
            </p>
            <ul>
              {blockers.map((issue) => (
                <li key={`${issue.stepId}-${issue.field}`}>
                  <strong>{issue.label}</strong> — {issue.message}{" "}
                  <button
                    type="button"
                    className="kr-wiz__link"
                    onClick={() => onGoToStep(issue.stepId)}
                  >
                    Fix this
                  </button>
                </li>
              ))}
            </ul>
          </div>
        ) : null}
      </section>

      {/* ── the property as it will read ────────────────── */}
      {sections.map((section) => {
        const lines = section.lines.filter((line) => line.value);

        return (
          <section className="kr-wiz__review" key={section.stepId}>
            <div className="kr-wiz__review-head">
              <h3 className="kr-wiz__review-title">{section.title}</h3>
              <button
                type="button"
                className="kr-props__btn kr-props__btn--quiet"
                onClick={() => onGoToStep(section.stepId)}
              >
                <LuPencil size={13} aria-hidden="true" /> Edit
                <span className="kr-sr-only">{section.title}</span>
              </button>
            </div>

            {lines.length === 0 ? (
              <p className="kr-wiz__help">
                {section.empty ?? "Nothing entered yet."}
              </p>
            ) : (
              <dl className="kr-wiz__review-list">
                {lines.map((line) => (
                  <div key={line.label}>
                    <dt>{line.label}</dt>
                    <dd>{line.value}</dd>
                  </div>
                ))}
              </dl>
            )}
          </section>
        );
      })}

      {/* ── saving ──────────────────────────────────────── */}
      <section className="kr-wiz__publish">
        <div className="kr-wiz__publish-actions">
          <button
            type="button"
            className="kr-props__btn"
            disabled={saving !== null}
            onClick={() => onSave("draft")}
          >
            <LuSave size={14} aria-hidden="true" />
            {saving === "draft" ? "Saving…" : "Save draft"}
          </button>

          {/* Visible whether or not it can succeed, and never fired by simply
              arriving on this screen. Publishing is a thing somebody does. */}
          <button
            type="button"
            className="kr-props__btn kr-props__btn--primary"
            disabled={!ready || saving !== null}
            onClick={() => onSave("publish")}
          >
            <LuUpload size={14} aria-hidden="true" />
            {saving === "publish"
              ? "Publishing…"
              : published
                ? "Publish changes"
                : "Publish property"}
          </button>
        </div>

        {!ready ? (
          <p className="kr-wiz__help">
            Publishing is unavailable until the items listed above are filled
            in. Save draft still works.
          </p>
        ) : null}

        {saveError ? (
          <p className="kr-wiz__error kr-wiz__error--block" role="alert">
            <LuTriangleAlert size={14} aria-hidden="true" />
            <span>{saveError}</span>
          </p>
        ) : null}

        {savedAt && !saveError ? (
          <p className="kr-wiz__saved" role="status">
            <LuCheck size={14} aria-hidden="true" />
            <span>
              {savedAt === "publish"
                ? "Published. It is on the website now."
                : "Draft saved."}
            </span>
          </p>
        ) : null}
      </section>
    </div>
  );
}

function Mark({ state }: { state: ReadinessState }) {
  if (state === "done") return <LuCheck size={13} />;
  if (state === "todo") return <LuCircle size={13} />;
  return <LuCircleDashed size={13} />;
}
