// Styling for the property workflow.
//
// A focused setup experience rather than another dashboard inside the
// dashboard: one readable column of form, a list of steps beside it, and the
// same state shown compactly as dots beneath. Nothing here is a new visual
// language — the buttons, inputs and cards are the ones the CMS already uses,
// and every value comes from the CMS theme.

import theme from "../../config/opencms--theme";

const radius = theme.cardRadius ?? 14;
const ease = "cubic-bezier(.22, 1, .36, 1)";

export const wizardCss = `
.kr-wiz { color: ${theme.text}; }
.kr-wiz *, .kr-wiz *::before, .kr-wiz *::after { box-sizing: border-box; }

.kr-wiz__bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-bottom: 24px;
}
.kr-wiz__subject {
  margin: 0;
  min-width: 0;
  color: ${theme.textMuted};
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kr-wiz__layout {
  display: grid;
  grid-template-columns: 244px minmax(0, 1fr);
  gap: 32px;
  align-items: start;
}

/* ── the step list ─────────────────────────────────────── */
/* The navigation column. A grid child needs min-width:0 or a long step name
   sets the column's floor and pushes the form sideways.

   Sticky, because the form is long: step three alone scrolls well past the
   fold, and the step list is both the map and the way out. Having it scroll
   away meant going back to the top to reach any other step.

   align-self:start is what makes it work at all — the grid stretches its
   children by default, so the column was already as tall as the form and had
   nothing to stick within. The max-height and scroll are for a short window,
   where the list itself is taller than the space it has. */
.kr-wiz__nav {
  min-width: 0;
  position: sticky;
  top: 20px;
  align-self: start;
  max-height: calc(100dvh - 40px);
  overflow-y: auto;
}
.kr-wiz__nav-toggle { display: none; }

.kr-wiz__steps {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 2px;
}
.kr-wiz__step {
  appearance: none;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  padding: 11px 12px;
  border: 0;
  border-radius: 9px;
  background: none;
  color: ${theme.text};
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 140ms ${ease};
}
.kr-wiz__step:hover:not(:disabled) { background: ${theme.background}; }
.kr-wiz__step:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 1px; }
.kr-wiz__step:disabled { opacity: .5; cursor: default; }
.kr-wiz__step--current { background: ${theme.background}; }

/* The marker carries the state as a shape — a tick, a filled ring, an outlined
   number — and the words underneath say it too, so nothing depends on noticing
   a colour. */
.kr-wiz__marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  margin-top: 1px;
  border: 1px solid ${theme.border};
  border-radius: 50%;
  background: ${theme.sidebar};
  color: ${theme.textMuted};
  font-size: 11px;
  font-weight: 700;
}
.kr-wiz__step--complete .kr-wiz__marker {
  background: ${theme.primary};
  border-color: ${theme.primary};
  color: #fff;
}
.kr-wiz__step--current .kr-wiz__marker {
  border-color: ${theme.primary};
  color: ${theme.text};
  box-shadow: 0 0 0 3px ${theme.primary}1f;
}

.kr-wiz__step-text { min-width: 0; }
.kr-wiz__step-title {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.35;
}
.kr-wiz__step-state {
  display: block;
  margin-top: 2px;
  color: ${theme.textMuted};
  font-size: 11.5px;
}
.kr-wiz__step--current .kr-wiz__step-state { color: ${theme.primary}; }

/* ── the form column ───────────────────────────────────── */
.kr-wiz__main { min-width: 0; }
/* ── the step, as a stack of cards ────────────────────────
   This was ONE white card holding the heading, the description and every
   field in a single column. Nate's note was that it is too much to take in
   for the space, and he is right: with no gaps, six kinds of text sat at the
   same visual distance from each other and the only way to find anything was
   to read all of it.

   So the panel is no longer a card. It is a transparent stack, and the things
   inside it are the cards — the grey canvas between them is what does the
   chunking. One level of card, never a card inside a card. */
.kr-wiz__panel {
  /* A readable measure. A form does not get better by being as wide as the
     monitor it happens to be shown on. Wider than before because the type is
     bigger; the measure in characters is about what it was. */
  max-width: 720px;
  display: grid;
  gap: ${theme.cardRadius ? 14 : 14}px;
}

/* Only the outer step stack owns cards. The content scope both excludes nested
   floor-plan fields and outranks the section resets in wizard-forms-css. */
.kr-wiz .kr-wiz__intro,
.kr-wiz__content > .kr-wiz__fields > * {
  padding: 24px;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  border-radius: ${radius}px;
}
.kr-wiz__eyebrow {
  margin: 0 0 10px;
  color: ${theme.textMuted};
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.kr-wiz__title {
  margin: 0 0 10px;
  font-size: clamp(23px, 2.1vw, 27px);
  font-weight: 800;
  letter-spacing: -0.02em;
}
.kr-wiz__title:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 4px; }
/* Nate asked for this to be black and bigger, and he is right: it is the one
   sentence that explains what the step is FOR, and it was styled like the
   disabled hint text three levels below it. Near-black, 15.5px, and the last
   thing in the intro card so nothing follows it. */
.kr-wiz__description {
  margin: 0;
  color: ${theme.text};
  font-size: 15.5px;
  line-height: 1.65;
}
.kr-wiz__body { margin: 0 0 18px; font-size: 14px; line-height: 1.7; }
/* ── helper text ─────────────────────────────────────────
   Its own treatment rather than another grey sentence at another size. It
   sits further from the control than the label does, so it reads as attached
   to the field but not as part of the question, and it is the same size as
   the placeholder — which is the level it belongs at: something that may
   help, not something else to process. */
.kr-wiz__help {
  margin: 10px 0 0;
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.6;
}

.kr-wiz__note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin: 16px 0 0;
  padding: 12px 14px;
  border: 1px solid ${theme.border};
  border-radius: 8px;
  background: ${theme.background};
  color: ${theme.textMuted};
  font-size: 13.5px;
  line-height: 1.6;
}
.kr-wiz__note-icon { flex-shrink: 0; margin-top: 1px; }

.kr-wiz__fields { display: grid; gap: 14px; }
/* One field. The control geometry itself is the plugin sheet's, so every form
   in the properties plugin has the same field, not just this one. */
.kr-wiz__field { display: block; min-width: 0; }

.kr-wiz__drop {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 34px 20px;
  border: 1px dashed ${theme.border};
  border-radius: 10px;
  background: ${theme.background};
  text-align: center;
}
.kr-wiz__drop-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  margin-bottom: 6px;
  border-radius: 50%;
  background: ${theme.sidebar};
  border: 1px solid ${theme.border};
  color: ${theme.textMuted};
}
.kr-wiz__drop-title { margin: 0; font-size: 16px; font-weight: 700; }

.kr-wiz__outstanding {
  margin: 0 0 22px;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 1px;
  background: ${theme.border};
  border: 1px solid ${theme.border};
  border-radius: 9px;
  overflow: hidden;
}
.kr-wiz__outstanding li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  background: ${theme.sidebar};
  font-size: 13.5px;
}
.kr-wiz__publish { padding-top: 4px; }

/* ── actions and the compact navigation ────────────────── */
.kr-wiz__actions {
  display: flex;
  align-items: center;
  gap: 16px;
  max-width: 640px;
  margin-top: 18px;
}
.kr-wiz__dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 1;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-wiz__dot {
  appearance: none;
  display: block;
  width: 9px;
  height: 9px;
  padding: 0;
  border: 1px solid ${theme.border};
  border-radius: 50%;
  background: ${theme.sidebar};
  cursor: pointer;
  transition: background 140ms ${ease}, width 180ms ${ease};
}
.kr-wiz__dot--complete { background: ${theme.primary}; border-color: ${theme.primary}; }
/* The current one is a bar rather than a dot, so position reads at a glance
   without counting. */
.kr-wiz__dot--current {
  width: 26px;
  border-radius: 999px;
  background: ${theme.primaryHover};
  border-color: ${theme.primaryHover};
}
.kr-wiz__dot:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 3px; }
.kr-wiz__dot:disabled { cursor: default; opacity: .55; }
.kr-wiz__end { color: ${theme.textMuted}; font-size: 12.5px; }

/* ── narrow screens ───────────────────────────────────────
   Inherits the MTC-KRP-019 standard: the sidebar does not simply shrink and
   sit beside the form. */
@media (max-width: 900px) {
  .kr-wiz__layout { grid-template-columns: minmax(0, 1fr); gap: 16px; }
  /* Not sticky on a phone: the column is above the form rather than beside
     it, so pinning it would sit on top of the fields it introduces. */
  .kr-wiz__nav { position: static; max-height: none; overflow: visible; }

  /* The list becomes a summary that already says where you are, with the full
     set one tap away — rather than a sidebar eating half a phone screen. */
  .kr-wiz__nav-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    min-height: 52px;
    padding: 10px 14px;
    border: 1px solid ${theme.border};
    border-radius: ${radius}px;
    background: ${theme.sidebar};
    color: ${theme.text};
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  .kr-wiz__nav-toggle:focus-visible { outline: 2px solid ${theme.primary}; outline-offset: 2px; }
  .kr-wiz__nav-count {
    display: block;
    color: ${theme.textMuted};
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
  }
  .kr-wiz__nav-name { display: block; margin-top: 2px; font-size: 14px; font-weight: 700; }
  .kr-wiz__nav-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }

  .kr-wiz__steps { display: none; }
  .kr-wiz__steps--open {
    display: grid;
    margin-top: 8px;
    padding: 6px;
    border: 1px solid ${theme.border};
    border-radius: ${radius}px;
    background: ${theme.sidebar};
  }
  .kr-wiz__step { min-height: 52px; align-items: center; }

  .kr-wiz__panel { max-width: none; gap: 12px; }
  .kr-wiz .kr-wiz__intro,
  .kr-wiz__content > .kr-wiz__fields > * { padding: 18px 16px; }
  .kr-wiz__actions { max-width: none; gap: 12px; }
  .kr-wiz__actions .kr-props__btn { min-height: 44px; }
  .kr-wiz__title { font-size: 21px; }
  .kr-wiz__description { font-size: 15px; }
  /* 16px so a phone does not zoom the page when a field takes focus. */
  .kr-wiz__content .kr-props__input { font-size: 16px; }
}

@media (max-width: 420px) {
  /* The dots would crowd the two buttons, and the summary above already gives
     the position, so they stand down rather than shrink. */
  .kr-wiz__dots { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-wiz__step, .kr-wiz__dot { transition: none; }
}
`;

export default wizardCss;
