// @ppm--dependency--config.template--leads

import React from "react";

import { LEAD_STATUS_LABELS } from "./types";
import type { LeadStatus } from "./types";
import template from "../../config/gh-leads--template";

type Props = { status?: LeadStatus };

/** Subtle pill. Renders an em dash when a lead carries no status. */
export default function StatusBadge({ status }: Props) {
  if (!status) {
    return (
      <span className="leads-muted" aria-label="No status">
        —
      </span>
    );
  }

  const tint = template.status[status];

  if (!tint) {
    return <span className="leads-muted">{status}</span>;
  }

  return (
    <span
      className="leads-badge"
      style={{ background: tint.bg, color: tint.fg, borderColor: tint.border }}
    >
      {LEAD_STATUS_LABELS[status] || status}
    </span>
  );
}
