import React from "react";
import { LuBuilding2 } from "react-icons/lu";

import template from "../../config/gh-properties--template";
import { tutorialCss } from "../../templates/shared/tutorial-css";
import propertiesEnabled from "../../toggles/properties";
import propertiesPreviewEnabled from "../../toggles/properties--preview";
import propertiesViewEnabled from "../../toggles/properties--view";
import PropertiesPreview from "./PropertiesPreview";
import PropertiesView from "./PropertiesView";
import { PROPERTIES_VIEW_PATH } from "./types";
import type { CmsPlugin, CmsViewProps } from "../opencms/core/plugin-types";

/**
 * Emits the plugin's stylesheet and hands the pathname on, as gh-apply does.
 *
 * The stylesheet is set as raw HTML rather than as a text child, and that is
 * load-bearing rather than a stylistic choice. React escapes a text child, so
 * `<style>{css}</style>` server-renders a child combinator as `&gt;` — and a
 * `<style>` element is RAW TEXT in HTML, meaning the browser never decodes it.
 * The entity reaches the CSS parser verbatim, the selector is invalid, and the
 * whole rule is silently dropped. That rule is the one that makes each field
 * a card, so without this the MTC-KRP-029 layout would look correct in a
 * string comparison and do nothing at all in a browser.
 *
 * Safe here because the content is our own build-time template, never user
 * input.
 */
function PropertiesPage({ pathname }: CmsViewProps) {
  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: template.css }} />
      {/* The walkthrough overlay is shared code, and so is its styling. Without
          this the overlay mounts on the Properties page, finds none of its
          rules, and renders as unstyled text across the screen — which is
          exactly what it did before MTC-KRP-048 moved these out of the
          Application Builder's sheet. */}
      <style dangerouslySetInnerHTML={{ __html: tutorialCss }} />
      <PropertiesView pathname={pathname} />
    </>
  );
}

/**
 * Properties.
 *
 * Registered by nothing: plugins.ts finds this file with require.context, so
 * the folder existing is the whole installation step.
 *
 * Ordered at 250, which puts it directly under Leads (200) and above the
 * Application Builder (300) in the sidebar.
 */
const plugin: CmsPlugin = {
  id: "properties",

  views:
    propertiesEnabled && propertiesViewEnabled
      ? [
          {
            id: "properties",
            path: PROPERTIES_VIEW_PATH,
            label: template.labels.navLabel,
            component: PropertiesPage,
            nav: true,
            order: 250,
            icon: LuBuilding2,
          },
        ]
      : [],

  slots: {
    dashboard:
      propertiesEnabled && propertiesPreviewEnabled
        ? [{ id: "properties-dashboard", component: PropertiesPreview, order: 250 }]
        : [],
  },
};

export default plugin;
