import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  LuArrowLeft,
  LuArrowRight,
  LuCheck,
  LuChevronDown,
  LuInfo,
} from "react-icons/lu";

import WizardDialog from "./WizardDialog";
import PublicationBar from "./PublicationBar";
import { properties as catalogue } from "../../../primitives/property/property-data";
import { IMAGE_PLAN_NOTE, PROPERTY_WIZARD_STEPS } from "./propertyWizardSteps";
import { WizardStepContent } from "./WizardStepContent";
import {
  buildSteps,
  canContinueFrom,
  isLast,
  nextStepId,
  previousStepId,
  resolveStepId,
  stepIndex,
} from "./wizardMachine";
import {
  emptyDraft,
  hasUnsavedChanges,
  propertyDraftApi,
  toRecord,
  withProposedSlug,
} from "./draft";
import type { PropertyDraft, SaveIntent } from "./draft";
import demoLocalStorage from "../../../toggles/demo-local-storage";
import { usingSupabase } from "../../supabase/enabled";
import { clearDraft, loadDraft, saveDraft } from "./propertiesStore";
import {
  canPublish,
  continueBlockedReason,
  firstIssue,
  issuesForStep,
  publishBlockers,
} from "./validation";

/** Said once, so the in-app dialog and anything else quoting it agree. */
const LEAVE_WARNING =
  usingSupabase() || demoLocalStorage
    ? "You have changes that have not been saved to this property yet. Leaving now will keep them as a draft on this device, but they will not appear in My Properties until you save."
    : "Property storage isn't connected for this site yet, so anything you have entered cannot be kept. Leaving now will lose it.";

export type PropertyWizardProps = {
  mode: "create" | "edit";
  /** The step named by the URL. Unknown values fall back to the first step. */
  stepId?: string;
  /** Populated for edit; a fresh draft for create. */
  initialDraft?: PropertyDraft;
  /** Navigates to a step. The URL is the wizard's memory across a refresh. */
  onNavigateStep: (stepId: string) => void;
  onExit: () => void;
  /** Name of the property being edited, for the heading. */
  subjectName?: string;
  /**
   * Which saved draft this is: "new", or "edit:<slug>".
   *
   * Stable per route on purpose. A single key for "new" is what stops a
   * refresh of the Add New Property wizard starting a second half-finished
   * property every time.
   */
  draftKey?: string;
};

/**
 * The property workflow.
 *
 * One shell for both creating and editing: the only difference between them is
 * where the draft starts, so there is no second copy of any of this. Both read
 * the same five steps, the same completion rules and the same navigation.
 *
 * Two navigations, one state. The list on the left says what each step is and
 * how far along you are; the dots under the form are the compact version of
 * exactly the same thing. Neither holds its own idea of where you are — both
 * render `buildSteps`, which is why they cannot disagree.
 *
 * The step lives in the URL, so a refresh returns you to the step you were on
 * rather than the beginning. The DRAFT does not, and deliberately: see draft.ts
 * on why browser storage is not standing in for a save.
 */
export default function PropertyWizard({
  mode,
  stepId,
  initialDraft,
  onNavigateStep,
  onExit,
  subjectName,
  draftKey,
}: PropertyWizardProps) {
  const steps = PROPERTY_WIZARD_STEPS;

  const original = useMemo(() => initialDraft ?? emptyDraft(), [initialDraft]);

  /* Recovered from the last visit if there is one, so a refresh in the middle
     of the workflow comes back to the work rather than to an empty form. Read
     once, in the initialiser, so a later save cannot reset what is on screen.
     Returns the starting point untouched during the Gatsby build, where there
     is no browser to read. */
  const [draft, setDraft] = useState<PropertyDraft>(() => {
    if (!(usingSupabase() || demoLocalStorage) || !draftKey) return original;
    return loadDraft(draftKey) ?? original;
  });

  /* Moves forward with a successful save, so the unsaved-changes warning
     stops firing for work that has actually been kept. */
  const [saved, setSaved] = useState<PropertyDraft>(original);

  /* The furthest step reached, so stepping back does not lock the later ones
     away again. */
  const [furthest, setFurthest] = useState<string>(() =>
    resolveStepId(steps, stepId)
  );
  const [navOpen, setNavOpen] = useState(false);
  const [confirmExit, setConfirmExit] = useState(false);

  const [saving, setSaving] = useState<SaveIntent | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [savedAt, setSavedAt] = useState<SaveIntent | null>(null);

  /* Shown only after Continue has actually been pressed and refused. Marking
     fields red before somebody has finished typing in them is how a form
     becomes an argument. */
  const [tried, setTried] = useState(false);

  const currentId = resolveStepId(steps, stepId);
  const current = stepIndex(steps, currentId);
  const views = buildSteps(steps, draft, currentId, furthest);
  const step = steps[current];
  const view = views[current];

  const heading = useRef<HTMLHeadingElement | null>(null);
  const firstRender = useRef(true);

  useEffect(() => {
    if (stepIndex(steps, furthest) < current) setFurthest(currentId);
  }, [currentId, current, furthest, steps]);

  /* Focus the new step's heading rather than leaving it on a button that has
     just changed meaning or disappeared. Skipped on arrival, where moving
     focus would be taking it from the reader unasked. */
  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    heading.current?.focus();
    setNavOpen(false);
    setTried(false);
  }, [currentId]);

  const dirty = hasUnsavedChanges(draft, saved);

  /**
   * Keep the open draft recoverable.
   *
   * Debounced rather than written on every keystroke: this runs on a change to
   * the whole draft object, and a property has a lot of fields. Half a second
   * of quiet is long enough to batch a typed sentence into one write and short
   * enough that nobody loses anything by refreshing. Step navigation lands
   * inside the same window, so Continue, Back and the side list are all
   * covered without needing their own hooks.
   */
  useEffect(() => {
    if (!(usingSupabase() || demoLocalStorage) || !draftKey) return;
    if (!dirty) return;

    const timer = window.setTimeout(() => {
      const result = saveDraft(draftKey, draft);
      /* Only surfaced if it FAILED. A working autosave that announces itself
         every few seconds is noise. */
      if (!result.ok) setSaveError(result.reason);
    }, 500);

    return () => window.clearTimeout(timer);
  }, [draft, dirty, draftKey]);

  /**
   * The browser's own warning, for closing the tab, the window, or navigating
   * away entirely.
   *
   * Our dialog cannot help there — by the time the tab is closing there is no
   * page left to show one on. This is the only mechanism that can intervene,
   * and it is Chrome's native prompt: the browser writes the wording itself
   * and ignores any text a page supplies, which is deliberate on their part
   * and fine. What matters is that the manager gets a Leave / Stay choice
   * rather than silently losing an afternoon.
   *
   * Registered only while there is genuinely something to lose, so closing a
   * property you merely looked at does not nag.
   */
  useEffect(() => {
    if (!dirty) return;

    const warn = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      /* Legacy browsers need returnValue set to something; the string itself
         is not displayed by anything current. */
      event.returnValue = "";
      return "";
    };

    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [dirty]);

  const change = useCallback((patch: Partial<PropertyDraft>) => {
    setSavedAt(null);
    setDraft((currentDraft) => {
      const next = { ...currentDraft, ...patch };
      /* A new property's address follows its name; an existing one's does
         not. The rule lives in draft.ts and is applied on every change so it
         cannot be forgotten by one caller. */
      return withProposedSlug(next);
    });
  }, []);

  const goTo = (id: string) => onNavigateStep(id);
  const back = previousStepId(steps, currentId);
  const forward = nextStepId(steps, currentId);
  const mayContinue = canContinueFrom(steps, currentId, draft);
  const blockedReason = continueBlockedReason(currentId, draft);

  /**
   * Continue, or say why not.
   *
   * A disabled button that gives no reason is the thing this avoids: when it
   * refuses, the message appears and focus moves to the field that caused it,
   * so nobody has to work out which of eight controls is the problem.
   */
  const attemptContinue = () => {
    if (!forward) return;

    if (!mayContinue) {
      setTried(true);
      const issue = firstIssue(currentId, draft);
      const target = issue
        ? document.getElementById(issue.field)
        : document.getElementById("kr-wiz-title");

      target?.focus();
      target?.scrollIntoView({ block: "center", behavior: "smooth" });
      return;
    }

    goTo(forward);
  };

  const save = async (intent: SaveIntent) => {
    setSaving(intent);
    setSaveError(null);
    setSavedAt(null);

    /* What would actually be written — pricing rule applied, editing-only
       fields stripped, photo count removed. The same object the review screen
       described, so there is no gap between what was shown and what is sent. */
    const record = toRecord(draft);

    if (intent === "publish") {
      /* The gate, enforced HERE rather than on a button.
         MTC-KRP-033 requires the top control to obey the same validation as
         Step 5. Relying on each button's `disabled` to do that had already
         failed once — the publication bar left its button live and only
         tinted it, so the top control published properties Step 5 refused.
         Putting the check on the shared path means a new control cannot
         reintroduce that, because there is only one road to publication. */
      if (!canPublish(draft)) {
        const missing = publishBlockers(draft);
        setSaving(null);
        setSaveError(
          missing.length === 1
            ? `${missing[0].label} is needed before this can be published.`
            : `${missing.length} required fields are missing. Open Review & Publish to see which.`
        );
        return;
      }

      record.publication = "published";
    } else if (intent === "unpublish") {
      /* Force back to draft, everything else unchanged. The API receives
         intent "draft" because the API boundary only distinguishes publish
         vs not-publish; the intent label here is for the UI feedback. */
      record.publication = "draft";
    }

    /* For the API call, "unpublish" maps to "draft" — the adapter only knows
       publish vs draft. */
    const apiIntent = intent === "unpublish" ? "draft" : intent;
    const outcome = await propertyDraftApi.save(record, apiIntent);

    setSaving(null);

    if (!outcome.ok) {
      setSaveError(outcome.reason);
      return;
    }

    /* Publication changes only on a save that succeeded. */
    let next: PropertyDraft;
    if (intent === "publish") {
      next = { ...draft, publication: "published" as const };
    } else if (intent === "unpublish") {
      next = { ...draft, publication: "draft" as const };
    } else {
      next = draft;
    }

    setDraft(next);
    setSaved(next);   /* MTC-KRP-032: advance the clean baseline */
    setSavedAt(intent);

    /* The property exists now, so the half-finished copy of it should not.
       Leaving it would mean the next visit reopened the draft rather than the
       saved property. */
    if (draftKey) clearDraft(draftKey);

    /* Save Draft is a finishing move: somebody pressing it is saying they are
       done for now, and leaving them on the form made them hunt for the way
       back out. Publishing is not — after publishing people check the review
       step and the live page, so that stays put.

       `next` is already the clean baseline, so the leave guard has nothing to
       warn about on the way out. */
    if (intent === "draft") onExit();
  };

  const exit = () => (dirty ? setConfirmExit(true) : onExit());

  const issues = tried ? issuesForStep(currentId, draft) : [];

  return (
    <div className="kr-wiz">
      <div className="kr-wiz__bar">
        <button type="button" className="kr-props__btn" onClick={exit}>
          <LuArrowLeft size={14} aria-hidden="true" /> My Properties
        </button>

        <p className="kr-wiz__subject">
          {mode === "edit"
            ? subjectName || "Edit property"
            : draft.title?.trim() || "New property"}
        </p>
      </div>

      {/* ── publication status bar ─────────────────────────
          Property-level, not step-level. Lives here so it is always visible
          regardless of which wizard step is showing, and always reads from the
          same draft/save state as Step 5 — there is no second source of truth. */}
      <PublicationBar
        draft={draft}
        saving={saving}
        saveError={saveError}
        savedAt={savedAt}
        onSave={(intent) => void save(intent)}
      />

      <div className="kr-wiz__layout">
        {/* ── the descriptive navigation ──────────────────────
            A list on desktop; on a phone it collapses behind a summary that
            already says where you are, so the steps are one tap away without
            spending half the screen on them. */}
        <div className="kr-wiz__nav" data-tutorial="wizard-steps">
          <button
            type="button"
            className="kr-wiz__nav-toggle"
            aria-expanded={navOpen}
            aria-controls="kr-wiz-steps"
            onClick={() => setNavOpen((open) => !open)}
          >
            <span>
              <span className="kr-wiz__nav-count">
                Step {view.position} of {views.length}
              </span>
              <span className="kr-wiz__nav-name">{view.shortTitle}</span>
            </span>
            <LuChevronDown size={17} aria-hidden="true" />
          </button>

          <ol
            className={`kr-wiz__steps${navOpen ? " kr-wiz__steps--open" : ""}`}
            id="kr-wiz-steps"
          >
            {views.map((item) => (
              <li key={item.id}>
                <button
                  type="button"
                  className={`kr-wiz__step kr-wiz__step--${item.state}`}
                  aria-current={item.state === "current" ? "step" : undefined}
                  disabled={!item.reachable}
                  onClick={() => goTo(item.id)}
                >
                  <span className="kr-wiz__marker" aria-hidden="true">
                    {item.state === "complete" ? <LuCheck size={13} /> : item.position}
                  </span>

                  <span className="kr-wiz__step-text">
                    <span className="kr-wiz__step-title">{item.shortTitle}</span>
                    {/* Said in words as well as shown, so the state does not
                        depend on noticing a tick or a colour. */}
                    <span className="kr-wiz__step-state">
                      {item.state === "complete"
                        ? "Completed"
                        : item.state === "current"
                          ? "In progress"
                          : "Not started"}
                    </span>
                  </span>
                </button>
              </li>
            ))}
          </ol>
        </div>

        {/* ── the form ───────────────────────────────────────── */}
        <div className="kr-wiz__main">
          <div className="kr-wiz__panel">
            {/* The step's own card: where you are, what this step is, and why.
                Separated from the fields by grey rather than by a margin, so
                the answer to "where am I" is one glance instead of a read. */}
            <div className="kr-wiz__intro">
              <p className="kr-wiz__eyebrow">
                Step {view.position} of {views.length}
              </p>

              <h2 className="kr-wiz__title" tabIndex={-1} ref={heading}>
                {step.title}
              </h2>
              <p className="kr-wiz__description">{step.description}</p>

              {/* Said once, on the first step: the order of the workflow is a
                  plan, not something to discover at step three. */}
              {currentId === "basics" ? (
                <p className="kr-wiz__note">
                  <LuInfo size={15} className="kr-wiz__note-icon" aria-hidden="true" />
                  <span>{IMAGE_PLAN_NOTE}</span>
                </p>
              ) : null}
            </div>

            <div className="kr-wiz__content">
              <WizardStepContent
                stepId={currentId}
                draft={draft}
                onChange={change}
                issues={issues}
                properties={catalogue}
                onGoToStep={goTo}
                onSave={(intent) => void save(intent)}
                saving={saving}
                saveError={saveError}
                savedAt={savedAt}
              />
            </div>
          </div>

          <div className="kr-wiz__actions">
            <button
              type="button"
              className="kr-props__btn"
              disabled={!back}
              onClick={() => back && goTo(back)}
            >
              <LuArrowLeft size={14} aria-hidden="true" /> Back
            </button>

            {/* ── the compact navigation ──────────────────────
                The same state as the list, in the space of a few dots. */}
            <ol className="kr-wiz__dots" aria-label="Workflow progress">
              {views.map((item) => (
                <li key={item.id}>
                  <button
                    type="button"
                    className={`kr-wiz__dot kr-wiz__dot--${item.state}`}
                    aria-label={`${item.shortTitle}, step ${item.position} of ${views.length}, ${
                      item.state === "complete"
                        ? "completed"
                        : item.state === "current"
                          ? "in progress"
                          : "not started"
                    }`}
                    aria-current={item.state === "current" ? "step" : undefined}
                    disabled={!item.reachable}
                    onClick={() => goTo(item.id)}
                  />
                </li>
              ))}
            </ol>

            {forward ? (
              /* Not disabled. A control that refuses and explains beats one
                 that is simply dead — the user finds out WHY on the press,
                 and lands on the field that caused it. */
              <button
                type="button"
                className="kr-props__btn kr-props__btn--primary"
                aria-describedby={
                  tried && blockedReason ? "kr-wiz-continue-note" : undefined
                }
                onClick={attemptContinue}
              >
                Continue <LuArrowRight size={14} aria-hidden="true" />
              </button>
            ) : (
              <span className="kr-wiz__end">
                {isLast(steps, current) ? "Last step" : ""}
              </span>
            )}
          </div>

          {tried && blockedReason ? (
            <p className="kr-wiz__blocked" id="kr-wiz-continue-note" role="alert">
              {blockedReason}
            </p>
          ) : null}
        </div>
      </div>

      {confirmExit ? (
        <WizardDialog
          title="Leave without saving?"
          text={LEAVE_WARNING}
          confirmLabel="Leave anyway"
          cancelLabel="Stay here"
          danger
          onConfirm={onExit}
          onClose={() => setConfirmExit(false)}
        />
      ) : null}
    </div>
  );
}
