// @ppm--version--1.0
// @ppm--dependency--config.template--leads

import React from "react";
import template from "../../templates/gh-leads/default-template";
import { initialsOf, tintIndex } from "./format";

type Props = {
  name: string;
  /** Larger variant used by the dashboard preview. */
  size?: "sm" | "lg";
};

/**
 * Initials avatar. We never have real photographs for a lead, so the identity
 * cue is the initials plus a tint held stable by hashing the name.
 *
 * Styled inline rather than by class: this renders both inside LeadsView and
 * inside the dashboard preview, and the preview has no stylesheet mounted.
 */
export default function LeadAvatar({ name, size = "sm" }: Props) {
  const palette = template.avatarPalette;
  const tint = palette[tintIndex(name, palette.length)];
  const base = size === "lg" ? template.avatar.lg : template.avatar.base;

  return (
    <span
      style={{ ...base, background: tint.bg, color: tint.fg }}
      aria-hidden="true"
    >
      {initialsOf(name)}
    </span>
  );
}
