import React, { useEffect, useRef } from "react";
import { LuTriangleAlert } from "react-icons/lu";

/**
 * The property workflow's own dialog.
 *
 * It has its own rather than borrowing the Application Builder's because a
 * plugin only mounts its OWN stylesheet: the borrowed component rendered with
 * none of its classes defined, so the warning arrived as bare text and two
 * default browser buttons in the middle of the page. A dialog that does not
 * look like a dialog is not a warning — people read past it.
 *
 * The behaviour a modal has to have, all of it here rather than assumed:
 * focus moves in and comes back out, Tab cannot wander behind it, Escape is
 * the same as Cancel, the page underneath does not scroll, and the SAFE choice
 * is what holds focus when it opens — so an accidental Enter keeps your work
 * rather than discarding it.
 */
export type WizardDialogProps = {
  title: string;
  text: string;
  /** A quieter second line under the question, e.g. what can be undone. */
  note?: string;
  confirmLabel: string;
  cancelLabel: string;
  /** Renders the confirm action as destructive. */
  danger?: boolean;
  onConfirm: () => void;
  onClose: () => void;
};

export default function WizardDialog({
  title,
  text,
  note,
  confirmLabel,
  cancelLabel,
  danger = false,
  onConfirm,
  onClose,
}: WizardDialogProps) {
  const panel = useRef<HTMLDivElement | null>(null);
  const cancel = useRef<HTMLButtonElement | null>(null);
  const returnTo = useRef<HTMLElement | null>(null);

  useEffect(() => {
    returnTo.current = document.activeElement as HTMLElement | null;

    /* The cancel button, deliberately. Opening on "Leave anyway" would mean a
       stray Enter throws the work away. */
    cancel.current?.focus();

    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
        return;
      }

      if (event.key !== "Tab") return;

      /* Keep Tab inside the dialog. Without this the next Tab lands on the
         form behind it, which is both confusing and a way to edit a page you
         have been told you are leaving. */
      const focusable = panel.current?.querySelectorAll<HTMLElement>(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (!focusable || focusable.length === 0) return;

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    document.addEventListener("keydown", onKey);

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = previousOverflow;
      /* Back where it came from, so the keyboard user is not dropped at the
         top of the document. */
      returnTo.current?.focus?.();
    };
  }, [onClose]);

  return (
    <div
      className="kr-wiz__scrim"
      onMouseDown={(event) => {
        if (!panel.current?.contains(event.target as Node)) onClose();
      }}
    >
      <div
        className="kr-wiz__ask"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="kr-wiz-ask-title"
        aria-describedby="kr-wiz-ask-text"
        ref={panel}
      >
        <span
          className={`kr-wiz__ask-icon${danger ? " kr-wiz__ask-icon--danger" : ""}`}
          aria-hidden="true"
        >
          <LuTriangleAlert size={20} />
        </span>

        <h2 className="kr-wiz__ask-title" id="kr-wiz-ask-title">
          {title}
        </h2>
        <p className="kr-wiz__ask-text" id="kr-wiz-ask-text">
          {text}
        </p>

        {note ? <p className="kr-wiz__ask-note">{note}</p> : null}

        <div className="kr-wiz__ask-actions">
          <button
            type="button"
            className="kr-props__btn kr-props__btn--primary"
            ref={cancel}
            onClick={onClose}
          >
            {cancelLabel}
          </button>

          <button
            type="button"
            className={`kr-props__btn${danger ? " kr-props__btn--danger" : ""}`}
            onClick={onConfirm}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}
